def _evaluate_live_preflight_readonly_actual_adapter_contract_v1(
    adapter_input: dict[str, Any] | None,
    *,
    context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    adapter_input = dict(adapter_input or {})
    context = dict(context or {})
    blockers: list[str] = []
    warnings: list[str] = []

    if str(adapter_input.get("schema") or "") != "aits_live_preflight_readonly_actual_adapter_input_v1":
        blockers.append("adapter_input_schema_invalid")
    target_symbol = _normalize_symbol_text(str(adapter_input.get("target_symbol") or ""))
    if not target_symbol:
        blockers.append("target_symbol_missing")

    intended_amount = int(adapter_input.get("intended_amount_krw") or 0)
    min_order = int(adapter_input.get("min_order_krw") or 10_000)
    per_order_cap = int(adapter_input.get("per_order_hard_cap_krw") or 12_000)
    total_cap = int(adapter_input.get("total_guarded_window_cap_krw") or 20_000)
    total_used = int(adapter_input.get("mock_total_window_used_krw") or 0)
    total_after = total_used + intended_amount
    submitted_count = int(adapter_input.get("submitted_count") or 0)
    session_approved = set(_normalized_session_approved_symbols(adapter_input.get("session_approved_symbols")))
    managed_source = str(adapter_input.get("managed_source") or adapter_input.get("source") or "")
    freshness = str(adapter_input.get("ai_opinion_freshness_status") or "").strip().lower()
    callable_name = str(adapter_input.get("live_preflight_callable_name") or "")
    allowed_callables = set(str(item) for item in (adapter_input.get("allowed_callable_names") or []))

    if intended_amount < min_order:
        blockers.append("intended_amount_below_min_order")
    if intended_amount > per_order_cap:
        blockers.append("intended_amount_exceeds_per_order_hard_cap")
    if total_after > total_cap:
        blockers.append("total_guarded_window_cap_exceeded")
    if submitted_count != 0:
        blockers.append("submitted_count_not_zero")
    if target_symbol not in session_approved:
        blockers.append("target_symbol_not_session_approved")
    if managed_source == "user_added" and target_symbol not in session_approved:
        blockers.append("user_added_not_session_approved")
    if freshness in {"", "missing", "stale", "very_stale", "analysis_required", "manual_required"}:
        blockers.append("stale_or_missing_ai_opinion")

    required_truthy = {
        "source_policy_ready": "source_policy_not_ready",
        "router_validation_payload_ready": "router_validation_payload_not_ready",
        "one_shot_unlock_ready": "one_shot_unlock_not_ready",
        "riskguard_adapter_ready": "riskguard_adapter_not_ready",
        "riskguard_actual_readonly_adapter_ready": "riskguard_actual_readonly_adapter_not_ready",
        "live_preflight_readiness": "live_preflight_readiness_not_ready",
        "duplicate_guard_required": "duplicate_guard_missing",
        "repeat_guard_required": "repeat_guard_missing",
        "relock_required": "relock_missing",
        "static_callable_inspection_only": "static_callable_inspection_only_missing",
        "live_preflight_callable_identified": "live_preflight_callable_not_identified",
        "live_preflight_input_contract_ready": "live_preflight_input_contract_not_ready",
        "live_preflight_output_contract_ready": "live_preflight_output_contract_not_ready",
        "live_preflight_call_boundary_defined": "live_preflight_call_boundary_not_defined",
        "live_preflight_side_effect_boundary_defined": "live_preflight_side_effect_boundary_not_defined",
        "live_preflight_mutation_forbidden": "live_preflight_mutation_boundary_not_defined",
        "validation_only": "validation_only_missing",
    }
    for key, blocker in required_truthy.items():
        if not bool(adapter_input.get(key)):
            blockers.append(blocker)
    if callable_name not in allowed_callables or callable_name not in _LIVE_PREFLIGHT_STATIC_CALLABLE_CONTRACT_ALLOWLIST:
        blockers.append("live_preflight_callable_not_identified")

    if bool(adapter_input.get("actual_order")) or bool(context.get("actual_order", False)):
        blockers.append("actual_order_flag_detected")
    if bool(adapter_input.get("actual_order_intent_emitted")) or bool(context.get("actual_order_intent_emitted", False)):
        blockers.append("actual_emit_detected")

    forced_false_flags = (
        "would_call_live_preflight",
        "live_preflight_called",
        "live_preflight_result_present",
        "live_preflight_reachable",
        "would_call_riskguard",
        "risk_guard_called",
        "decision_router_called",
        "order_service_called",
        "order_adapter_called",
        "order_service_reachable",
        "order_adapter_reachable",
        "execution_bridge_reachable",
        "unlock_service_called",
        "unlock_consumed",
        "managed_pool_mutation",
        "order_risk_detected",
    )
    for key in forced_false_flags:
        if bool(context.get(key, False)):
            blockers.append(f"{key}_true")
    provider_external_call_count = int(context.get("provider_external_call_count") or 0)
    if provider_external_call_count != 0:
        blockers.append("provider_external_call_count_nonzero")

    blockers = list(dict.fromkeys(blockers))
    warnings = list(dict.fromkeys(warnings))
    contract_ready = bool(target_symbol and intended_amount and not any(item in blockers for item in ("adapter_input_schema_invalid", "target_symbol_missing")))
    actual_readonly_adapter_ready = bool(contract_ready and not blockers)
    return {
        "schema": "aits_live_preflight_readonly_actual_adapter_contract_v1",
        "input_schema": str(adapter_input.get("schema") or ""),
        "target_symbol": target_symbol,
        "source": str(adapter_input.get("source") or ""),
        "managed_source": managed_source,
        "intended_side": str(adapter_input.get("intended_side") or "buy"),
        "intended_amount_krw": intended_amount,
        "min_order_krw": min_order,
        "per_order_hard_cap_krw": per_order_cap,
        "total_guarded_window_cap_krw": total_cap,
        "total_window_after_candidate_krw": total_after,
        "adapter_mode": "actual_readonly_contract",
        "live_preflight_actual_readonly_adapter_ready": actual_readonly_adapter_ready,
        "adapter_ready": actual_readonly_adapter_ready,
        "live_preflight_callable_identified": bool(adapter_input.get("live_preflight_callable_identified")) and callable_name in _LIVE_PREFLIGHT_STATIC_CALLABLE_CONTRACT_ALLOWLIST,
        "live_preflight_callable_name": callable_name,
        "live_preflight_input_contract_ready": bool(adapter_input.get("live_preflight_input_contract_ready")),
        "live_preflight_output_contract_ready": bool(adapter_input.get("live_preflight_output_contract_ready")),
        "live_preflight_call_boundary_defined": bool(adapter_input.get("live_preflight_call_boundary_defined")),
        "live_preflight_side_effect_boundary_defined": bool(adapter_input.get("live_preflight_side_effect_boundary_defined")),
        "live_preflight_mutation_forbidden": bool(adapter_input.get("live_preflight_mutation_forbidden")),
        "would_call_live_preflight": False,
        "live_preflight_called": False,
        "live_preflight_decision": "not_evaluated",
        "live_preflight_result_present": False,
        "live_preflight_reachable": False,
        "would_call_riskguard": False,
        "risk_guard_called": False,
        "decision_router_called": False,
        "order_service_reachable": False,
        "order_adapter_reachable": False,
        "execution_bridge_reachable": False,
        "order_service_called": False,
        "order_adapter_called": False,
        "unlock_service_called": False,
        "unlock_consumed": False,
        "submitted": 0,
        "submitted_count": 0,
        "actual_order": False,
        "actual_order_intent_emitted": False,
        "provider_external_call_count": 0,
        "final_action_unchanged": True,
        "managed_pool_mutation": False,
        "order_risk_detected": False,
        "blockers": blockers,
        "warnings": warnings,
        "required_next_goal": "AITS-LIVE-PREFLIGHT-READONLY-ACTUAL-CALL-BOUNDARY-DESIGN-REVIEW-01",
    }


def _validate_live_preflight_readonly_actual_adapter_contract_v1(result: dict[str, Any] | None) -> list[str]:
    if not result:
        return ["live_preflight_readonly_actual_adapter_result_missing"]
    errors: list[str] = []
    if result.get("schema") != "aits_live_preflight_readonly_actual_adapter_contract_v1":
        errors.append("schema_invalid")
    if result.get("adapter_mode") != "actual_readonly_contract":
        errors.append("adapter_mode_invalid")
    if result.get("live_preflight_decision") != "not_evaluated":
        errors.append("live_preflight_decision_must_be_not_evaluated")
    for key in (
        "would_call_live_preflight",
        "live_preflight_called",
        "live_preflight_result_present",
        "live_preflight_reachable",
        "would_call_riskguard",
        "risk_guard_called",
        "decision_router_called",
        "order_service_reachable",
        "order_adapter_reachable",
        "execution_bridge_reachable",
        "order_service_called",
        "order_adapter_called",
        "unlock_service_called",
        "unlock_consumed",
        "actual_order",
        "actual_order_intent_emitted",
        "managed_pool_mutation",
        "order_risk_detected",
    ):
        if bool(result.get(key)):
            errors.append(f"{key}_must_be_false")
    if int(result.get("submitted") or 0) != 0:
        errors.append("submitted_must_be_zero")
    if int(result.get("submitted_count") or 0) != 0:
        errors.append("submitted_count_must_be_zero")
    if int(result.get("provider_external_call_count") or 0) != 0:
        errors.append("provider_call_count_must_be_zero")
    if result.get("live_preflight_actual_readonly_adapter_ready") and result.get("blockers"):
        errors.append("live_preflight_actual_readonly_adapter_ready_with_blockers")
    return errors


def _build_live_preflight_readonly_actual_adapter_result(
    candidate: dict[str, Any],
    *,
    target_symbol: str = "",
    session_approved_symbols: Any = None,
    mock_unlock_approved_symbols: Any = None,
    intended_amount_krw: int | None = None,
    mock_total_window_used_krw: int = 0,
    mock_submitted_count: int = 0,
    actual_input_overrides: dict[str, Any] | None = None,
    adapter_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    riskguard_actual_result = _build_riskguard_readonly_actual_adapter_result(
        candidate,
        target_symbol=target_symbol or str(candidate.get("symbol") or ""),
        session_approved_symbols=session_approved_symbols,
        mock_unlock_approved_symbols=mock_unlock_approved_symbols,
        intended_amount_krw=intended_amount_krw,
        mock_total_window_used_krw=mock_total_window_used_krw,
        mock_submitted_count=mock_submitted_count,
    )
    actual_input = _build_live_preflight_readonly_actual_adapter_input_v1(
        riskguard_actual_result,
        overrides=actual_input_overrides,
    )
    actual_contract = _evaluate_live_preflight_readonly_actual_adapter_contract_v1(
        actual_input,
        context=adapter_context,
    )
    validation_errors = _validate_live_preflight_readonly_actual_adapter_contract_v1(actual_contract)
    return {
        "candidate": dict(candidate or {}),
        "riskguard_readonly_actual_adapter_result": riskguard_actual_result,
        "actual_adapter_input": actual_input,
        "actual_adapter_contract": actual_contract,
        "schema": actual_contract.get("schema"),
        "target_symbol": actual_contract.get("target_symbol"),
        "live_preflight_actual_readonly_adapter_ready": bool(actual_contract.get("live_preflight_actual_readonly_adapter_ready")),
        "adapter_ready": bool(actual_contract.get("adapter_ready")),
        "adapter_mode": actual_contract.get("adapter_mode"),
        "live_preflight_callable_identified": bool(actual_contract.get("live_preflight_callable_identified")),
        "live_preflight_callable_name": actual_contract.get("live_preflight_callable_name"),
        "live_preflight_input_contract_ready": bool(actual_contract.get("live_preflight_input_contract_ready")),
        "live_preflight_output_contract_ready": bool(actual_contract.get("live_preflight_output_contract_ready")),
        "live_preflight_call_boundary_defined": bool(actual_contract.get("live_preflight_call_boundary_defined")),
        "live_preflight_side_effect_boundary_defined": bool(actual_contract.get("live_preflight_side_effect_boundary_defined")),
        "live_preflight_mutation_forbidden": bool(actual_contract.get("live_preflight_mutation_forbidden")),
        "would_call_live_preflight": bool(actual_contract.get("would_call_live_preflight")),
        "live_preflight_called": bool(actual_contract.get("live_preflight_called")),
        "live_preflight_decision": actual_contract.get("live_preflight_decision"),
        "live_preflight_result_present": bool(actual_contract.get("live_preflight_result_present")),
        "live_preflight_reachable": bool(actual_contract.get("live_preflight_reachable")),
        "would_call_riskguard": bool(actual_contract.get("would_call_riskguard")),
        "risk_guard_called": bool(actual_contract.get("risk_guard_called")),
        "decision_router_called": bool(actual_contract.get("decision_router_called")),
        "order_service_reachable": bool(actual_contract.get("order_service_reachable")),
        "order_adapter_reachable": bool(actual_contract.get("order_adapter_reachable")),
        "execution_bridge_reachable": bool(actual_contract.get("execution_bridge_reachable")),
        "order_service_called": bool(actual_contract.get("order_service_called")),
        "order_adapter_called": bool(actual_contract.get("order_adapter_called")),
        "unlock_service_called": bool(actual_contract.get("unlock_service_called")),
        "unlock_consumed": bool(actual_contract.get("unlock_consumed")),
        "final_action_unchanged": bool(actual_contract.get("final_action_unchanged")),
        "submitted_count": int(actual_contract.get("submitted_count") or 0),
        "provider_external_call_count": int(actual_contract.get("provider_external_call_count") or 0),
        "actual_order": bool(actual_contract.get("actual_order")),
        "actual_order_intent_emitted": bool(actual_contract.get("actual_order_intent_emitted")),
        "managed_pool_mutation": bool(actual_contract.get("managed_pool_mutation")),
        "order_risk_detected": bool(actual_contract.get("order_risk_detected")),
        "blockers": list(actual_contract.get("blockers") or []),
        "warnings": list(actual_contract.get("warnings") or []),
        "validation_errors": validation_errors,
    }


def _run_live_preflight_readonly_actual_adapter_fixture_proof(report: dict[str, Any]) -> None:
    valid = _base_source_policy_candidate("user_added", "KRW-PYTH")
    scenarios: list[dict[str, Any]] = [
        {"name": "valid_live_preflight_actual_readonly_adapter_ready", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "expected_ready": True, "expected_blockers": []},
        {"name": "session_approved_empty_blocks", "candidate": valid, "approved": [], "unlock": ["KRW-PYTH"], "expected_ready": False, "expected_blockers": ["user_added_not_session_approved"]},
        {"name": "intended_amount_13000_blocks", "candidate": {**valid, "intended_amount_krw": 13_000}, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "amount": 13_000, "expected_ready": False, "expected_blockers": ["intended_amount_exceeds_per_order_hard_cap"]},
        {"name": "mock_submitted_count_1_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "submitted": 1, "expected_ready": False, "expected_blockers": ["submitted_count_not_zero"]},
        {"name": "live_preflight_callable_identified_false_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "overrides": {"live_preflight_callable_identified": False}, "expected_ready": False, "expected_blockers": ["live_preflight_callable_not_identified"]},
        {"name": "live_preflight_input_contract_not_ready_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "overrides": {"live_preflight_input_contract_ready": False}, "expected_ready": False, "expected_blockers": ["live_preflight_input_contract_not_ready"]},
        {"name": "live_preflight_output_contract_not_ready_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "overrides": {"live_preflight_output_contract_ready": False}, "expected_ready": False, "expected_blockers": ["live_preflight_output_contract_not_ready"]},
        {"name": "live_preflight_call_boundary_not_defined_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "overrides": {"live_preflight_call_boundary_defined": False}, "expected_ready": False, "expected_blockers": ["live_preflight_call_boundary_not_defined"]},
        {"name": "riskguard_actual_readonly_not_ready_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "overrides": {"riskguard_actual_readonly_adapter_ready": False}, "expected_ready": False, "expected_blockers": ["riskguard_actual_readonly_adapter_not_ready"]},
        {"name": "live_preflight_readiness_not_ready_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "overrides": {"live_preflight_readiness": False}, "expected_ready": False, "expected_blockers": ["live_preflight_readiness_not_ready"]},
        {"name": "actual_order_flag_detected_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "overrides": {"actual_order": True}, "expected_ready": False, "expected_blockers": ["actual_order_flag_detected"]},
        {"name": "would_call_live_preflight_true_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "context": {"would_call_live_preflight": True}, "expected_ready": False, "expected_blockers": ["would_call_live_preflight_true"]},
    ]
    forced_false_keys = (
        "would_call_live_preflight",
        "live_preflight_called",
        "live_preflight_result_present",
        "live_preflight_reachable",
        "would_call_riskguard",
        "risk_guard_called",
        "actual_order",
        "actual_order_intent_emitted",
        "decision_router_called",
        "order_service_reachable",
        "order_adapter_reachable",
        "execution_bridge_reachable",
        "order_service_called",
        "order_adapter_called",
        "unlock_service_called",
        "unlock_consumed",
        "managed_pool_mutation",
        "order_risk_detected",
    )
    results: list[dict[str, Any]] = []
    for scenario in scenarios:
        result = _build_live_preflight_readonly_actual_adapter_result(
            scenario["candidate"],
            target_symbol=str(scenario["candidate"].get("symbol") or ""),
            session_approved_symbols=scenario.get("approved"),
            mock_unlock_approved_symbols=scenario.get("unlock"),
            intended_amount_krw=scenario.get("amount"),
            mock_total_window_used_krw=int(scenario.get("used") or 0),
            mock_submitted_count=int(scenario.get("submitted") or 0),
            actual_input_overrides=scenario.get("overrides"),
            adapter_context=scenario.get("context"),
        )
        blockers = set(result.get("blockers") or [])
        passed = bool(result.get("live_preflight_actual_readonly_adapter_ready")) == bool(scenario["expected_ready"])
        passed = passed and all(blocker in blockers for blocker in scenario.get("expected_blockers") or [])
        passed = passed and result.get("live_preflight_decision") == "not_evaluated"
        passed = passed and not result.get("validation_errors")
        passed = passed and not any(bool(result.get(key)) for key in forced_false_keys)
        results.append({"name": scenario["name"], "pass": passed, **result})
    report.update(
        {
            "live_preflight_readonly_actual_adapter_supported": True,
            "schema": "aits_live_preflight_readonly_actual_adapter_contract_v1",
            "adapter_helper_owner": "tools/runtime_smoke/aits_qt_smoke_harness.py::_evaluate_live_preflight_readonly_actual_adapter_contract_v1",
            "callable_contract_source": "static_design_contract",
            "fixture_results": results,
            "fixture_pass_count": sum(1 for item in results if item.get("pass")),
            "fixture_fail_count": sum(1 for item in results if not item.get("pass")),
            "actual_order": False,
            "actual_order_intent_emitted": False,
            "decision_router_called": False,
            "would_call_riskguard": False,
            "risk_guard_called": False,
            "would_call_live_preflight": False,
            "live_preflight_called": False,
            "live_preflight_decision": "not_evaluated",
            "live_preflight_result_present": False,
            "live_preflight_reachable": False,
            "order_service_called": False,
            "order_adapter_called": False,
            "order_service_reachable": False,
            "order_adapter_reachable": False,
            "execution_bridge_reachable": False,
            "unlock_service_called": False,
            "unlock_consumed": False,
            "final_action_unchanged": True,
            "submitted_count": 0,
            "provider_external_call_count": 0,
            "managed_pool_mutation": False,
            "order_risk_detected": False,
        }
    )
    report["pass_status"] = "pass" if report["fixture_fail_count"] == 0 else "fail"
    report["status"] = report["pass_status"]


def _run_live_preflight_readonly_actual_adapter_live_proof(
    report: dict[str, Any],
    *,
    output_dir: Path,
    target_symbol: str | None = None,
    min_score: float = 60.0,
    session_approved_symbols: Any = None,
    mock_unlock_approved_symbols: Any = None,
    intended_amount_krw: int = 10_000,
    mock_total_window_used_krw: int = 0,
    mock_submitted_count: int = 0,
) -> None:
    embedded: dict[str, Any] = {"mode": "riskguard-readonly-actual-adapter-live-proof", "embedded": True}
    _run_riskguard_readonly_actual_adapter_live_proof(
        embedded,
        output_dir=output_dir,
        target_symbol=target_symbol,
        min_score=min_score,
        session_approved_symbols=session_approved_symbols,
        mock_unlock_approved_symbols=mock_unlock_approved_symbols,
        intended_amount_krw=intended_amount_krw,
        mock_total_window_used_krw=mock_total_window_used_krw,
        mock_submitted_count=mock_submitted_count,
    )
    candidate = dict(embedded.get("candidate") or {})
    if not candidate:
        candidate = _base_source_policy_candidate("user_added", str(target_symbol or "KRW-PYTH"))
    result = _build_live_preflight_readonly_actual_adapter_result(
        candidate,
        target_symbol=str(target_symbol or embedded.get("target_symbol") or candidate.get("symbol") or ""),
        session_approved_symbols=session_approved_symbols,
        mock_unlock_approved_symbols=mock_unlock_approved_symbols,
        intended_amount_krw=intended_amount_krw,
        mock_total_window_used_krw=mock_total_window_used_krw,
        mock_submitted_count=mock_submitted_count,
    )
    expected_safe = not any(
        bool(result.get(key))
        for key in (
            "would_call_live_preflight",
            "live_preflight_called",
            "live_preflight_result_present",
            "live_preflight_reachable",
            "would_call_riskguard",
            "risk_guard_called",
            "actual_order",
            "actual_order_intent_emitted",
            "decision_router_called",
            "order_service_reachable",
            "order_adapter_reachable",
            "execution_bridge_reachable",
            "order_service_called",
            "order_adapter_called",
            "unlock_service_called",
            "unlock_consumed",
            "managed_pool_mutation",
            "order_risk_detected",
        )
    )
    report.update(
        {
            "mode": "live-preflight-readonly-actual-adapter-live-proof",
            "live_preflight_readonly_actual_adapter_supported": True,
            "schema": "aits_live_preflight_readonly_actual_adapter_contract_v1",
            "adapter_helper_owner": "tools/runtime_smoke/aits_qt_smoke_harness.py::_evaluate_live_preflight_readonly_actual_adapter_contract_v1",
            "callable_contract_source": "static_design_contract",
            "target_symbol": str(target_symbol or embedded.get("target_symbol") or result.get("target_symbol") or ""),
            "session_approved_symbols": _normalized_session_approved_symbols(session_approved_symbols),
            "mock_unlock_approved_symbols": _normalized_session_approved_symbols(mock_unlock_approved_symbols),
            "embedded_riskguard_readonly_actual_adapter_report": {
                "status": embedded.get("status"),
                "actual_readonly_adapter_ready": embedded.get("actual_readonly_adapter_ready"),
                "would_call_riskguard": embedded.get("would_call_riskguard"),
                "risk_guard_called": embedded.get("risk_guard_called"),
                "risk_decision": embedded.get("risk_decision"),
                "risk_result_present": embedded.get("risk_result_present"),
                "blockers": embedded.get("blockers"),
                "validation_errors": embedded.get("validation_errors"),
            },
            **result,
        }
    )
    report["pass_status"] = "pass" if expected_safe and not result.get("validation_errors") else "fail"
    report["status"] = report["pass_status"]


def _build_live_order_final_gate_integration_input_v1(
    live_preflight_actual_result: dict[str, Any] | None,
    *,
    overrides: dict[str, Any] | None = None,
) -> dict[str, Any]:
    live_preflight_actual_result = dict(live_preflight_actual_result or {})
    actual_input = dict(live_preflight_actual_result.get("actual_adapter_input") or {})
    candidate = dict(live_preflight_actual_result.get("candidate") or {})
    target_symbol = _normalize_symbol_text(
        str(actual_input.get("target_symbol") or live_preflight_actual_result.get("target_symbol") or candidate.get("symbol") or "")
    )
    intended_side = str(actual_input.get("intended_side") or candidate.get("side") or "buy").strip().lower()
    intended_amount = int(actual_input.get("intended_amount_krw") or candidate.get("intended_amount_krw") or 0)
    total_window_used = int(actual_input.get("mock_total_window_used_krw") or 0)
    payload = {
        "schema": "aits_live_order_final_gate_integration_input_v1",
        "target_symbol": target_symbol,
        "source": str(actual_input.get("source") or candidate.get("source") or "unknown"),
        "managed_source": str(actual_input.get("managed_source") or candidate.get("managed_source") or candidate.get("source") or "unknown"),
        "intended_side": intended_side,
        "intended_amount_krw": intended_amount,
        "min_order_krw": int(actual_input.get("min_order_krw") or 10_000),
        "per_order_hard_cap_krw": int(actual_input.get("per_order_hard_cap_krw") or 12_000),
        "total_guarded_window_cap_krw": int(actual_input.get("total_guarded_window_cap_krw") or 20_000),
        "mock_total_window_used_krw": total_window_used,
        "submitted_count": int(actual_input.get("submitted_count") or 0),
        "session_approved_symbols": list(actual_input.get("session_approved_symbols") or []),
        "ai_opinion_freshness_status": str(actual_input.get("ai_opinion_freshness_status") or candidate.get("ai_freshness") or ""),
        "source_policy_ready": bool(actual_input.get("source_policy_ready")),
        "router_validation_payload_ready": bool(actual_input.get("router_validation_payload_ready")),
        "riskguard_actual_readonly_adapter_ready": bool(actual_input.get("riskguard_actual_readonly_adapter_ready") or live_preflight_actual_result.get("riskguard_readonly_actual_adapter_result", {}).get("actual_readonly_adapter_ready")),
        "live_preflight_actual_readonly_adapter_ready": bool(live_preflight_actual_result.get("live_preflight_actual_readonly_adapter_ready")),
        "one_shot_unlock_ready": bool(actual_input.get("one_shot_unlock_ready")),
        "unlock_token_present_or_mocked": True,
        "unlock_scope_symbol": target_symbol,
        "unlock_scope_side": intended_side,
        "unlock_scope_amount_krw": max(intended_amount, 10_000),
        "unlock_expiry_status": "valid",
        "duplicate_check_ready": True,
        "repeat_check_ready": True,
        "relock_check_ready": True,
        "duplicate_order_detected": False,
        "repeat_order_detected": False,
        "relock_required": False,
        "final_emit_gate_contract_ready": True,
        "actual_order": False,
        "actual_order_intent_emitted": False,
        "would_emit_order_intent": False,
        "order_intent_emitted": False,
        "would_consume_unlock": False,
        "unlock_consumed": False,
        "provider_external_call_count": 0,
    }
    if overrides:
        payload.update(dict(overrides))
    return payload


def _evaluate_live_order_final_gate_integration_contract_v1(
    gate_input: dict[str, Any] | None,
    *,
    context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    gate_input = dict(gate_input or {})
    context = dict(context or {})
    blockers: list[str] = []
    warnings: list[str] = []

    if str(gate_input.get("schema") or "") != "aits_live_order_final_gate_integration_input_v1":
        blockers.append("input_schema_invalid")
    target_symbol = _normalize_symbol_text(str(gate_input.get("target_symbol") or ""))
    if not target_symbol:
        blockers.append("target_symbol_missing")
    intended_side = str(gate_input.get("intended_side") or "").strip().lower()
    intended_amount = int(gate_input.get("intended_amount_krw") or 0)
    min_order = int(gate_input.get("min_order_krw") or 10_000)
    per_order_cap = int(gate_input.get("per_order_hard_cap_krw") or 12_000)
    total_cap = int(gate_input.get("total_guarded_window_cap_krw") or 20_000)
    total_used = int(gate_input.get("mock_total_window_used_krw") or 0)
    total_after = total_used + intended_amount
    submitted_count = int(gate_input.get("submitted_count") or 0)
    session_approved = set(_normalized_session_approved_symbols(gate_input.get("session_approved_symbols")))
    managed_source = str(gate_input.get("managed_source") or gate_input.get("source") or "")
    freshness = str(gate_input.get("ai_opinion_freshness_status") or "").strip().lower()
    unlock_symbol = _normalize_symbol_text(str(gate_input.get("unlock_scope_symbol") or ""))
    unlock_side = str(gate_input.get("unlock_scope_side") or "").strip().lower()
    unlock_amount = int(gate_input.get("unlock_scope_amount_krw") or 0)
    unlock_expiry = str(gate_input.get("unlock_expiry_status") or "").strip().lower()

    if intended_amount < min_order:
        blockers.append("intended_amount_below_min_order")
    if intended_amount > per_order_cap:
        blockers.append("intended_amount_exceeds_per_order_hard_cap")
    if total_after > total_cap:
        blockers.append("total_guarded_window_cap_exceeded")
    if submitted_count != 0:
        blockers.append("submitted_count_not_zero")
    if target_symbol not in session_approved:
        blockers.append("target_symbol_not_session_approved")
    if managed_source == "user_added" and target_symbol not in session_approved:
        blockers.append("user_added_not_session_approved")
    if freshness in {"", "missing", "stale", "very_stale", "analysis_required", "manual_required"}:
        blockers.append("stale_or_missing_ai_opinion")

    required_truthy = {
        "source_policy_ready": "source_policy_not_ready",
        "router_validation_payload_ready": "router_validation_payload_not_ready",
        "riskguard_actual_readonly_adapter_ready": "riskguard_actual_readonly_adapter_not_ready",
        "live_preflight_actual_readonly_adapter_ready": "live_preflight_actual_readonly_adapter_not_ready",
        "one_shot_unlock_ready": "one_shot_unlock_not_ready",
        "unlock_token_present_or_mocked": "unlock_token_missing",
        "duplicate_check_ready": "duplicate_check_not_ready",
        "repeat_check_ready": "repeat_check_not_ready",
        "relock_check_ready": "relock_check_not_ready",
        "final_emit_gate_contract_ready": "final_emit_gate_contract_not_ready",
    }
    for key, blocker in required_truthy.items():
        if not bool(gate_input.get(key)):
            blockers.append(blocker)
    if unlock_symbol != target_symbol:
        blockers.append("unlock_scope_symbol_mismatch")
    if unlock_side != intended_side:
        blockers.append("unlock_scope_side_mismatch")
    if intended_amount > unlock_amount:
        blockers.append("unlock_amount_scope_exceeded")
    if unlock_expiry == "expired":
        blockers.append("unlock_expired")
    if bool(gate_input.get("duplicate_order_detected")):
        blockers.append("duplicate_order_detected")
    if bool(gate_input.get("repeat_order_detected")):
        blockers.append("repeat_order_detected")
    if bool(gate_input.get("relock_required")):
        blockers.append("relock_required")
    if bool(gate_input.get("actual_order")) or bool(context.get("actual_order", False)):
        blockers.append("actual_order_flag_detected")
    if bool(gate_input.get("actual_order_intent_emitted")) or bool(context.get("actual_order_intent_emitted", False)):
        blockers.append("actual_emit_detected")
    if bool(gate_input.get("unlock_consumed")) or bool(context.get("unlock_consumed", False)):
        blockers.append("unlock_already_consumed")
    provider_external_call_count = int(gate_input.get("provider_external_call_count") or context.get("provider_external_call_count") or 0)
    if provider_external_call_count != 0:
        blockers.append("provider_external_call_detected")

    forced_false_flags = (
        "would_emit_order_intent",
        "order_intent_emitted",
        "would_consume_unlock",
        "unlock_service_called",
        "would_call_riskguard",
        "risk_guard_called",
        "would_call_live_preflight",
        "live_preflight_called",
        "decision_router_called",
        "order_service_called",
        "order_adapter_called",
        "execution_bridge_called",
        "managed_pool_mutation",
        "order_risk_detected",
    )
    for key in forced_false_flags:
        if bool(gate_input.get(key)) or bool(context.get(key, False)):
            blockers.append(f"{key}_true")

    blockers = list(dict.fromkeys(blockers))
    warnings = list(dict.fromkeys(warnings))
    final_confirmation_ready = not any(
        item in blockers
        for item in (
            "one_shot_unlock_not_ready",
            "unlock_token_missing",
            "unlock_scope_symbol_mismatch",
            "unlock_scope_side_mismatch",
            "unlock_amount_scope_exceeded",
            "unlock_expired",
            "unlock_already_consumed",
        )
    )
    duplicate_repeat_relock_ready = not any(
        item in blockers
        for item in (
            "duplicate_check_not_ready",
            "repeat_check_not_ready",
            "relock_check_not_ready",
            "duplicate_order_detected",
            "repeat_order_detected",
            "relock_required",
        )
    )
    final_emit_gate_ready = bool(gate_input.get("final_emit_gate_contract_ready")) and "final_emit_gate_contract_not_ready" not in blockers
    live_minimal_order_readiness_ready = not any(
        item in blockers
        for item in (
            "intended_amount_below_min_order",
            "intended_amount_exceeds_per_order_hard_cap",
            "total_guarded_window_cap_exceeded",
            "submitted_count_not_zero",
            "source_policy_not_ready",
            "router_validation_payload_not_ready",
            "riskguard_actual_readonly_adapter_not_ready",
            "live_preflight_actual_readonly_adapter_not_ready",
            "stale_or_missing_ai_opinion",
        )
    )
    live_order_final_gate_ready = bool(
        final_confirmation_ready
        and duplicate_repeat_relock_ready
        and final_emit_gate_ready
        and live_minimal_order_readiness_ready
        and not blockers
    )
    safety_flags = {
        "actual_order": False,
        "actual_order_intent_emitted": False,
        "would_emit_order_intent": False,
        "order_intent_emitted": False,
        "would_consume_unlock": False,
        "unlock_consumed": False,
        "unlock_service_called": False,
        "would_call_riskguard": False,
        "risk_guard_called": False,
        "would_call_live_preflight": False,
        "live_preflight_called": False,
        "decision_router_called": False,
        "order_service_called": False,
        "order_adapter_called": False,
        "execution_bridge_called": False,
        "provider_external_call_count": 0,
        "submitted_count": 0,
        "managed_pool_mutation": False,
        "order_risk_detected": False,
    }
    return {
        "schema": "aits_live_order_final_gate_integration_contract_v1",
        "input_schema": str(gate_input.get("schema") or ""),
        "target_symbol": target_symbol,
        "source": str(gate_input.get("source") or ""),
        "managed_source": managed_source,
        "intended_side": intended_side,
        "intended_amount_krw": intended_amount,
        "total_window_after_candidate_krw": total_after,
        "live_order_final_gate_ready": live_order_final_gate_ready,
        "final_gate_mode": "readonly_integration_proof",
        "final_confirmation_ready": final_confirmation_ready,
        "duplicate_repeat_relock_ready": duplicate_repeat_relock_ready,
        "final_emit_gate_ready": final_emit_gate_ready,
        "live_minimal_order_readiness_ready": live_minimal_order_readiness_ready,
        "next_allowed_goal": "AITS-LIVE-MINIMAL-ORDER-ARMED-BUT-NOT-SUBMITTED-01",
        "actual_order": False,
        "actual_order_intent_emitted": False,
        "would_emit_order_intent": False,
        "order_intent_emitted": False,
        "would_consume_unlock": False,
        "unlock_consumed": False,
        "unlock_service_called": False,
        "would_call_riskguard": False,
        "risk_guard_called": False,
        "would_call_live_preflight": False,
        "live_preflight_called": False,
        "decision_router_called": False,
        "order_service_called": False,
        "order_adapter_called": False,
        "execution_bridge_called": False,
        "provider_external_call_count": 0,
        "submitted_count": 0,
        "managed_pool_mutation": False,
        "order_risk_detected": False,
        "blockers": blockers,
        "warnings": warnings,
        "safety_flags": safety_flags,
    }


def _validate_live_order_final_gate_integration_contract_v1(result: dict[str, Any] | None) -> list[str]:
    if not result:
        return ["live_order_final_gate_result_missing"]
    errors: list[str] = []
    if result.get("schema") != "aits_live_order_final_gate_integration_contract_v1":
        errors.append("schema_invalid")
    if result.get("final_gate_mode") != "readonly_integration_proof":
        errors.append("final_gate_mode_invalid")
    for key in (
        "actual_order",
        "actual_order_intent_emitted",
        "would_emit_order_intent",
        "order_intent_emitted",
        "would_consume_unlock",
        "unlock_consumed",
        "unlock_service_called",
        "would_call_riskguard",
        "risk_guard_called",
        "would_call_live_preflight",
        "live_preflight_called",
        "decision_router_called",
        "order_service_called",
        "order_adapter_called",
        "execution_bridge_called",
        "managed_pool_mutation",
        "order_risk_detected",
    ):
        if bool(result.get(key)):
            errors.append(f"{key}_must_be_false")
    if int(result.get("submitted_count") or 0) != 0:
        errors.append("submitted_count_must_be_zero")
    if int(result.get("provider_external_call_count") or 0) != 0:
        errors.append("provider_call_count_must_be_zero")
    if result.get("live_order_final_gate_ready") and result.get("blockers"):
        errors.append("final_gate_ready_with_blockers")
    return errors


def _build_live_order_final_gate_integration_result(
    candidate: dict[str, Any],
    *,
    target_symbol: str = "",
    session_approved_symbols: Any = None,
    mock_unlock_approved_symbols: Any = None,
    intended_amount_krw: int | None = None,
    mock_total_window_used_krw: int = 0,
    mock_submitted_count: int = 0,
    gate_input_overrides: dict[str, Any] | None = None,
    gate_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    live_preflight_actual_result = _build_live_preflight_readonly_actual_adapter_result(
        candidate,
        target_symbol=target_symbol or str(candidate.get("symbol") or ""),
        session_approved_symbols=session_approved_symbols,
        mock_unlock_approved_symbols=mock_unlock_approved_symbols,
        intended_amount_krw=intended_amount_krw,
        mock_total_window_used_krw=mock_total_window_used_krw,
        mock_submitted_count=mock_submitted_count,
    )
    gate_input = _build_live_order_final_gate_integration_input_v1(
        live_preflight_actual_result,
        overrides=gate_input_overrides,
    )
    gate_contract = _evaluate_live_order_final_gate_integration_contract_v1(
        gate_input,
        context=gate_context,
    )
    validation_errors = _validate_live_order_final_gate_integration_contract_v1(gate_contract)
    return {
        "candidate": dict(candidate or {}),
        "live_preflight_readonly_actual_adapter_result": live_preflight_actual_result,
        "final_gate_input": gate_input,
        "final_gate_contract": gate_contract,
        "schema": gate_contract.get("schema"),
        "target_symbol": gate_contract.get("target_symbol"),
        "live_order_final_gate_ready": bool(gate_contract.get("live_order_final_gate_ready")),
        "final_gate_mode": gate_contract.get("final_gate_mode"),
        "final_confirmation_ready": bool(gate_contract.get("final_confirmation_ready")),
        "duplicate_repeat_relock_ready": bool(gate_contract.get("duplicate_repeat_relock_ready")),
        "final_emit_gate_ready": bool(gate_contract.get("final_emit_gate_ready")),
        "live_minimal_order_readiness_ready": bool(gate_contract.get("live_minimal_order_readiness_ready")),
        "next_allowed_goal": gate_contract.get("next_allowed_goal"),
        "actual_order": bool(gate_contract.get("actual_order")),
        "actual_order_intent_emitted": bool(gate_contract.get("actual_order_intent_emitted")),
        "would_emit_order_intent": bool(gate_contract.get("would_emit_order_intent")),
        "order_intent_emitted": bool(gate_contract.get("order_intent_emitted")),
        "would_consume_unlock": bool(gate_contract.get("would_consume_unlock")),
        "unlock_consumed": bool(gate_contract.get("unlock_consumed")),
        "unlock_service_called": bool(gate_contract.get("unlock_service_called")),
        "would_call_riskguard": bool(gate_contract.get("would_call_riskguard")),
        "risk_guard_called": bool(gate_contract.get("risk_guard_called")),
        "would_call_live_preflight": bool(gate_contract.get("would_call_live_preflight")),
        "live_preflight_called": bool(gate_contract.get("live_preflight_called")),
        "decision_router_called": bool(gate_contract.get("decision_router_called")),
        "order_service_called": bool(gate_contract.get("order_service_called")),
        "order_adapter_called": bool(gate_contract.get("order_adapter_called")),
        "execution_bridge_called": bool(gate_contract.get("execution_bridge_called")),
        "submitted_count": int(gate_contract.get("submitted_count") or 0),
        "provider_external_call_count": int(gate_contract.get("provider_external_call_count") or 0),
        "managed_pool_mutation": bool(gate_contract.get("managed_pool_mutation")),
        "order_risk_detected": bool(gate_contract.get("order_risk_detected")),
        "blockers": list(gate_contract.get("blockers") or []),
        "warnings": list(gate_contract.get("warnings") or []),
        "safety_flags": dict(gate_contract.get("safety_flags") or {}),
        "validation_errors": validation_errors,
    }


def _run_live_order_final_gate_integration_fixture_proof(report: dict[str, Any]) -> None:
    valid = _base_source_policy_candidate("user_added", "KRW-PYTH")
    scenarios: list[dict[str, Any]] = [
        {"name": "valid_final_gate_ready", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "expected_ready": True, "expected_blockers": []},
        {"name": "session_approved_empty_blocks", "candidate": valid, "approved": [], "unlock": ["KRW-PYTH"], "expected_ready": False, "expected_blockers": ["user_added_not_session_approved"]},
        {"name": "intended_amount_13000_blocks", "candidate": {**valid, "intended_amount_krw": 13_000}, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "amount": 13_000, "expected_ready": False, "expected_blockers": ["intended_amount_exceeds_per_order_hard_cap"]},
        {"name": "mock_submitted_count_1_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "submitted": 1, "expected_ready": False, "expected_blockers": ["submitted_count_not_zero"]},
        {"name": "unlock_token_missing_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "overrides": {"unlock_token_present_or_mocked": False}, "expected_ready": False, "expected_blockers": ["unlock_token_missing"]},
        {"name": "duplicate_order_detected_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "overrides": {"duplicate_order_detected": True}, "expected_ready": False, "expected_blockers": ["duplicate_order_detected"]},
        {"name": "final_emit_gate_contract_not_ready_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "overrides": {"final_emit_gate_contract_ready": False}, "expected_ready": False, "expected_blockers": ["final_emit_gate_contract_not_ready"]},
        {"name": "unlock_scope_symbol_mismatch_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "overrides": {"unlock_scope_symbol": "KRW-BTC"}, "expected_ready": False, "expected_blockers": ["unlock_scope_symbol_mismatch"]},
        {"name": "unlock_scope_side_mismatch_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "overrides": {"unlock_scope_side": "sell"}, "expected_ready": False, "expected_blockers": ["unlock_scope_side_mismatch"]},
        {"name": "unlock_expired_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "overrides": {"unlock_expiry_status": "expired"}, "expected_ready": False, "expected_blockers": ["unlock_expired"]},
        {"name": "would_emit_order_intent_true_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "context": {"would_emit_order_intent": True}, "expected_ready": False, "expected_blockers": ["would_emit_order_intent_true"]},
        {"name": "would_consume_unlock_true_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "context": {"would_consume_unlock": True}, "expected_ready": False, "expected_blockers": ["would_consume_unlock_true"]},
    ]
    forced_false_keys = (
        "actual_order",
        "actual_order_intent_emitted",
        "would_emit_order_intent",
        "order_intent_emitted",
        "would_consume_unlock",
        "unlock_consumed",
        "unlock_service_called",
        "would_call_riskguard",
        "risk_guard_called",
        "would_call_live_preflight",
        "live_preflight_called",
        "decision_router_called",
        "order_service_called",
        "order_adapter_called",
        "execution_bridge_called",
        "managed_pool_mutation",
        "order_risk_detected",
    )
    results: list[dict[str, Any]] = []
    for scenario in scenarios:
        result = _build_live_order_final_gate_integration_result(
            scenario["candidate"],
            target_symbol=str(scenario["candidate"].get("symbol") or ""),
            session_approved_symbols=scenario.get("approved"),
            mock_unlock_approved_symbols=scenario.get("unlock"),
            intended_amount_krw=scenario.get("amount"),
            mock_total_window_used_krw=int(scenario.get("used") or 0),
            mock_submitted_count=int(scenario.get("submitted") or 0),
            gate_input_overrides=scenario.get("overrides"),
            gate_context=scenario.get("context"),
        )
        blockers = set(result.get("blockers") or [])
        passed = bool(result.get("live_order_final_gate_ready")) == bool(scenario["expected_ready"])
        passed = passed and all(blocker in blockers for blocker in scenario.get("expected_blockers") or [])
        passed = passed and result.get("final_gate_mode") == "readonly_integration_proof"
        passed = passed and not result.get("validation_errors")
        passed = passed and not any(bool(result.get(key)) for key in forced_false_keys)
        results.append({"name": scenario["name"], "pass": passed, **result})
    report.update(
        {
            "live_order_final_gate_integration_supported": True,
            "schema": "aits_live_order_final_gate_integration_contract_v1",
            "contract_helper_owner": "tools/runtime_smoke/aits_qt_smoke_harness.py::_evaluate_live_order_final_gate_integration_contract_v1",
            "fixture_results": results,
            "fixture_pass_count": sum(1 for item in results if item.get("pass")),
            "fixture_fail_count": sum(1 for item in results if not item.get("pass")),
            "actual_order": False,
            "actual_order_intent_emitted": False,
            "would_emit_order_intent": False,
            "order_intent_emitted": False,
            "would_consume_unlock": False,
            "unlock_consumed": False,
            "unlock_service_called": False,
            "would_call_riskguard": False,
            "risk_guard_called": False,
            "would_call_live_preflight": False,
            "live_preflight_called": False,
            "decision_router_called": False,
            "order_service_called": False,
            "order_adapter_called": False,
            "execution_bridge_called": False,
            "final_action_unchanged": True,
            "submitted_count": 0,
            "provider_external_call_count": 0,
            "managed_pool_mutation": False,
            "order_risk_detected": False,
        }
    )
    report["pass_status"] = "pass" if report["fixture_fail_count"] == 0 else "fail"
    report["status"] = report["pass_status"]


def _run_live_order_final_gate_integration_live_proof(
    report: dict[str, Any],
    *,
    output_dir: Path,
    target_symbol: str | None = None,
    min_score: float = 60.0,
    session_approved_symbols: Any = None,
    mock_unlock_approved_symbols: Any = None,
    intended_amount_krw: int = 10_000,
    mock_total_window_used_krw: int = 0,
    mock_submitted_count: int = 0,
) -> None:
    embedded: dict[str, Any] = {"mode": "live-preflight-readonly-actual-adapter-live-proof", "embedded": True}
    _run_live_preflight_readonly_actual_adapter_live_proof(
        embedded,
        output_dir=output_dir,
        target_symbol=target_symbol,
        min_score=min_score,
        session_approved_symbols=session_approved_symbols,
        mock_unlock_approved_symbols=mock_unlock_approved_symbols,
        intended_amount_krw=intended_amount_krw,
        mock_total_window_used_krw=mock_total_window_used_krw,
        mock_submitted_count=mock_submitted_count,
    )
    candidate = dict(embedded.get("candidate") or {})
    if not candidate:
        candidate = _base_source_policy_candidate("user_added", str(target_symbol or "KRW-PYTH"))
    result = _build_live_order_final_gate_integration_result(
        candidate,
        target_symbol=str(target_symbol or embedded.get("target_symbol") or candidate.get("symbol") or ""),
        session_approved_symbols=session_approved_symbols,
        mock_unlock_approved_symbols=mock_unlock_approved_symbols,
        intended_amount_krw=intended_amount_krw,
        mock_total_window_used_krw=mock_total_window_used_krw,
        mock_submitted_count=mock_submitted_count,
    )
    expected_safe = not any(
        bool(result.get(key))
        for key in (
            "actual_order",
            "actual_order_intent_emitted",
            "would_emit_order_intent",
            "order_intent_emitted",
            "would_consume_unlock",
            "unlock_consumed",
            "unlock_service_called",
            "would_call_riskguard",
            "risk_guard_called",
            "would_call_live_preflight",
            "live_preflight_called",
            "decision_router_called",
            "order_service_called",
            "order_adapter_called",
            "execution_bridge_called",
            "managed_pool_mutation",
            "order_risk_detected",
        )
    )
    report.update(
        {
            "mode": "live-order-final-gate-integration-live-proof",
            "live_order_final_gate_integration_supported": True,
            "schema": "aits_live_order_final_gate_integration_contract_v1",
            "contract_helper_owner": "tools/runtime_smoke/aits_qt_smoke_harness.py::_evaluate_live_order_final_gate_integration_contract_v1",
            "target_symbol": str(target_symbol or embedded.get("target_symbol") or result.get("target_symbol") or ""),
            "session_approved_symbols": _normalized_session_approved_symbols(session_approved_symbols),
            "mock_unlock_approved_symbols": _normalized_session_approved_symbols(mock_unlock_approved_symbols),
            "embedded_live_preflight_actual_readonly_report": {
                "status": embedded.get("status"),
                "live_preflight_actual_readonly_adapter_ready": embedded.get("live_preflight_actual_readonly_adapter_ready"),
                "would_call_live_preflight": embedded.get("would_call_live_preflight"),
                "live_preflight_called": embedded.get("live_preflight_called"),
                "live_preflight_decision": embedded.get("live_preflight_decision"),
                "live_preflight_result_present": embedded.get("live_preflight_result_present"),
                "blockers": embedded.get("blockers"),
                "validation_errors": embedded.get("validation_errors"),
            },
            **result,
        }
    )
    report["pass_status"] = "pass" if expected_safe and not result.get("validation_errors") else "fail"
    report["status"] = report["pass_status"]


def _build_live_minimal_order_armed_input_v1(
    final_gate_result: dict[str, Any] | None,
    *,
    operator_confirm_phrase: str = "",
    configured_order_amount_krw: int | None = None,
    overrides: dict[str, Any] | None = None,
) -> dict[str, Any]:
    final_gate_result = dict(final_gate_result or {})
    final_gate_contract = dict(final_gate_result.get("final_gate_contract") or {})
    final_gate_input = dict(final_gate_result.get("final_gate_input") or {})
    target_symbol = _normalize_symbol_text(
        str(final_gate_contract.get("target_symbol") or final_gate_input.get("target_symbol") or final_gate_result.get("target_symbol") or "")
    )
    intended_side = str(final_gate_contract.get("intended_side") or final_gate_input.get("intended_side") or "buy").strip().lower()
    intended_amount = int(final_gate_contract.get("intended_amount_krw") or final_gate_input.get("intended_amount_krw") or 0)
    configured_amount = int(configured_order_amount_krw if configured_order_amount_krw is not None else intended_amount)
    expected_confirm_phrase = f"AITS LIVE ORDER {target_symbol} {intended_side.upper()} {configured_amount}" if target_symbol else ""
    payload = {
        "schema": "aits_live_minimal_order_armed_input_v1",
        "target_symbol": target_symbol,
        "source": str(final_gate_contract.get("source") or final_gate_input.get("source") or "unknown"),
        "managed_source": str(final_gate_contract.get("managed_source") or final_gate_input.get("managed_source") or final_gate_input.get("source") or "unknown"),
        "intended_side": intended_side,
        "intended_amount_krw": intended_amount,
        "configured_order_amount_krw": configured_amount,
        "current_setting_order_amount_krw": configured_amount,
        "min_order_krw": int(final_gate_input.get("min_order_krw") or 10_000),
        "per_order_hard_cap_krw": int(final_gate_input.get("per_order_hard_cap_krw") or 12_000),
        "total_guarded_window_cap_krw": int(final_gate_input.get("total_guarded_window_cap_krw") or 20_000),
        "mock_total_window_used_krw": int(final_gate_input.get("mock_total_window_used_krw") or 0),
        "submitted_count": int(final_gate_input.get("submitted_count") or final_gate_contract.get("submitted_count") or 0),
        "session_approved_symbols": list(final_gate_input.get("session_approved_symbols") or []),
        "ai_opinion_freshness_status": str(final_gate_input.get("ai_opinion_freshness_status") or ""),
        "live_order_final_gate_ready": bool(final_gate_contract.get("live_order_final_gate_ready")),
        "final_confirmation_ready": bool(final_gate_contract.get("final_confirmation_ready")),
        "duplicate_repeat_relock_ready": bool(final_gate_contract.get("duplicate_repeat_relock_ready")),
        "final_emit_gate_ready": bool(final_gate_contract.get("final_emit_gate_ready")),
        "live_minimal_order_readiness_ready": bool(final_gate_contract.get("live_minimal_order_readiness_ready")),
        "riskguard_actual_readonly_adapter_ready": bool(final_gate_input.get("riskguard_actual_readonly_adapter_ready")),
        "live_preflight_actual_readonly_adapter_ready": bool(final_gate_input.get("live_preflight_actual_readonly_adapter_ready")),
        "one_shot_unlock_ready": bool(final_gate_input.get("one_shot_unlock_ready")),
        "unlock_token_present_or_mocked": bool(final_gate_input.get("unlock_token_present_or_mocked")),
        "unlock_scope_symbol": _normalize_symbol_text(str(final_gate_input.get("unlock_scope_symbol") or "")),
        "unlock_scope_side": str(final_gate_input.get("unlock_scope_side") or "").strip().lower(),
        "unlock_scope_amount_krw": int(final_gate_input.get("unlock_scope_amount_krw") or 0),
        "unlock_expiry_status": str(final_gate_input.get("unlock_expiry_status") or ""),
        "operator_confirm_required": True,
        "operator_confirm_phrase": str(operator_confirm_phrase or ""),
        "expected_confirm_phrase": expected_confirm_phrase,
        "actual_order": False,
        "actual_order_intent_emitted": False,
        "would_emit_order_intent": False,
        "order_intent_emitted": False,
        "would_consume_unlock": False,
        "unlock_consumed": False,
        "provider_external_call_count": 0,
    }
    if overrides:
        payload.update(dict(overrides))
    return payload


def _evaluate_live_minimal_order_armed_contract_v1(
    armed_input: dict[str, Any] | None,
    *,
    context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    armed_input = dict(armed_input or {})
    context = dict(context or {})
    blockers: list[str] = []
    warnings: list[str] = []

    if str(armed_input.get("schema") or "") != "aits_live_minimal_order_armed_input_v1":
        blockers.append("input_schema_invalid")
    target_symbol = _normalize_symbol_text(str(armed_input.get("target_symbol") or ""))
    if not target_symbol:
        blockers.append("target_symbol_missing")
    intended_side = str(armed_input.get("intended_side") or "").strip().lower()
    intended_amount = int(armed_input.get("intended_amount_krw") or 0)
    configured_amount = int(armed_input.get("configured_order_amount_krw") or armed_input.get("current_setting_order_amount_krw") or intended_amount or 0)
    current_setting_amount = int(armed_input.get("current_setting_order_amount_krw") or configured_amount or 0)
    min_order = int(armed_input.get("min_order_krw") or 10_000)
    per_order_cap = int(armed_input.get("per_order_hard_cap_krw") or 12_000)
    total_cap = int(armed_input.get("total_guarded_window_cap_krw") or 20_000)
    total_used = int(armed_input.get("mock_total_window_used_krw") or 0)
    total_after = total_used + configured_amount
    submitted_count = int(armed_input.get("submitted_count") or 0)
    session_approved = set(_normalized_session_approved_symbols(armed_input.get("session_approved_symbols")))
    managed_source = str(armed_input.get("managed_source") or armed_input.get("source") or "")
    unlock_symbol = _normalize_symbol_text(str(armed_input.get("unlock_scope_symbol") or ""))
    unlock_side = str(armed_input.get("unlock_scope_side") or "").strip().lower()
    unlock_amount = int(armed_input.get("unlock_scope_amount_krw") or 0)
    unlock_expiry = str(armed_input.get("unlock_expiry_status") or "").strip().lower()
    expected_confirm_phrase = str(armed_input.get("expected_confirm_phrase") or "")
    operator_confirm_phrase = str(armed_input.get("operator_confirm_phrase") or "")

    if intended_side != "buy":
        blockers.append("intended_side_not_buy")
    if intended_amount != configured_amount:
        blockers.append("intended_amount_not_matching_configured_setting")
    if configured_amount < min_order:
        blockers.append("configured_amount_below_min_order")
    if configured_amount > per_order_cap:
        blockers.append("configured_amount_exceeds_per_order_hard_cap")
    if total_after > total_cap:
        blockers.append("configured_amount_exceeds_guarded_window_cap")
    if submitted_count != 0:
        blockers.append("submitted_count_not_zero")
    if managed_source == "user_added" and target_symbol not in session_approved:
        blockers.append("user_added_not_session_approved")

    required_truthy = {
        "live_order_final_gate_ready": "live_order_final_gate_not_ready",
        "final_confirmation_ready": "final_confirmation_not_ready",
        "duplicate_repeat_relock_ready": "duplicate_repeat_relock_not_ready",
        "final_emit_gate_ready": "final_emit_gate_not_ready",
        "live_minimal_order_readiness_ready": "live_minimal_order_readiness_not_ready",
        "riskguard_actual_readonly_adapter_ready": "riskguard_actual_readonly_adapter_not_ready",
        "live_preflight_actual_readonly_adapter_ready": "live_preflight_actual_readonly_adapter_not_ready",
        "one_shot_unlock_ready": "one_shot_unlock_not_ready",
        "unlock_token_present_or_mocked": "unlock_token_missing",
        "operator_confirm_required": "operator_confirm_not_required",
    }
    for key, blocker in required_truthy.items():
        if not bool(armed_input.get(key)):
            blockers.append(blocker)
    if unlock_symbol != target_symbol:
        blockers.append("unlock_scope_symbol_mismatch")
    if unlock_side != intended_side:
        blockers.append("unlock_scope_side_mismatch")
    if configured_amount > unlock_amount:
        blockers.append("unlock_amount_scope_exceeded")
    if unlock_expiry == "expired":
        blockers.append("unlock_expired")
    if not operator_confirm_phrase:
        blockers.append("operator_confirm_phrase_missing")
    elif operator_confirm_phrase != expected_confirm_phrase:
        blockers.append("operator_confirm_phrase_mismatch")
    if bool(armed_input.get("actual_order")) or bool(context.get("actual_order", False)):
        blockers.append("actual_order_flag_detected")
    if bool(armed_input.get("actual_order_intent_emitted")) or bool(context.get("actual_order_intent_emitted", False)):
        blockers.append("actual_emit_detected")
    if bool(armed_input.get("would_emit_order_intent")) or bool(context.get("would_emit_order_intent", False)):
        blockers.append("would_emit_order_intent_detected")
    if bool(armed_input.get("order_intent_emitted")) or bool(context.get("order_intent_emitted", False)):
        blockers.append("actual_emit_detected")
    if bool(armed_input.get("would_consume_unlock")) or bool(context.get("would_consume_unlock", False)):
        blockers.append("unlock_would_consume_detected")
    if bool(armed_input.get("unlock_consumed")) or bool(context.get("unlock_consumed", False)):
        blockers.append("unlock_already_consumed")
    provider_external_call_count = int(armed_input.get("provider_external_call_count") or context.get("provider_external_call_count") or 0)
    if provider_external_call_count != 0:
        blockers.append("provider_external_call_detected")

    blockers = list(dict.fromkeys(blockers))
    warnings = list(dict.fromkeys(warnings))
    final_gate_passed = bool(armed_input.get("live_order_final_gate_ready")) and "live_order_final_gate_not_ready" not in blockers
    amount_matches_current_setting = intended_amount == configured_amount == current_setting_amount
    amount_locked_to_current_setting = amount_matches_current_setting
    amount_locked_to_10000_deprecated = amount_locked_to_current_setting and configured_amount == 10_000
    caps_validated = not any(
        item in blockers
        for item in (
            "intended_amount_not_matching_configured_setting",
            "configured_amount_below_min_order",
            "configured_amount_exceeds_per_order_hard_cap",
            "configured_amount_exceeds_guarded_window_cap",
        )
    )
    source_policy_validated = "user_added_not_session_approved" not in blockers
    riskguard_readonly_validated = "riskguard_actual_readonly_adapter_not_ready" not in blockers
    live_preflight_readonly_validated = "live_preflight_actual_readonly_adapter_not_ready" not in blockers
    unlock_final_confirmation_validated = not any(
        item in blockers
        for item in (
            "one_shot_unlock_not_ready",
            "unlock_token_missing",
            "unlock_scope_symbol_mismatch",
            "unlock_scope_side_mismatch",
            "unlock_amount_scope_exceeded",
            "unlock_expired",
            "unlock_would_consume_detected",
            "unlock_already_consumed",
        )
    )
    duplicate_repeat_relock_validated = bool(armed_input.get("duplicate_repeat_relock_ready")) and "duplicate_repeat_relock_not_ready" not in blockers
    final_emit_gate_validated = bool(armed_input.get("final_emit_gate_ready")) and "final_emit_gate_not_ready" not in blockers
    operator_confirm_phrase_matched = bool(operator_confirm_phrase) and operator_confirm_phrase == expected_confirm_phrase
    live_minimal_order_armed = bool(not blockers)
    safety_flags = {
        "actual_order": False,
        "actual_order_intent_emitted": False,
        "would_emit_order_intent": False,
        "order_intent_emitted": False,
        "would_consume_unlock": False,
        "unlock_consumed": False,
        "unlock_service_called": False,
        "decision_router_called": False,
        "risk_guard_called": False,
        "live_preflight_called": False,
        "execution_bridge_called": False,
        "order_service_called": False,
        "order_adapter_called": False,
        "provider_external_call_count": 0,
        "submitted_count": 0,
        "managed_pool_mutation": False,
        "order_risk_detected": False,
    }
    return {
        "schema": "aits_live_minimal_order_armed_contract_v1",
        "input_schema": str(armed_input.get("schema") or ""),
        "target_symbol": target_symbol,
        "source": str(armed_input.get("source") or ""),
        "managed_source": managed_source,
        "intended_side": intended_side,
        "intended_amount_krw": intended_amount,
        "configured_order_amount_krw": configured_amount,
        "current_setting_order_amount_krw": current_setting_amount,
        "total_window_after_candidate_krw": total_after,
        "live_minimal_order_armed": live_minimal_order_armed,
        "armed_mode": "not_submitted",
        "next_allowed_goal": "AITS-LIVE-MINIMAL-ORDER-SETTING-AMOUNT-ONE-SHOT-TEST-01",
        "operator_confirm_required": True,
        "expected_confirm_phrase": expected_confirm_phrase,
        "operator_confirm_phrase_matched": operator_confirm_phrase_matched,
        "final_gate_passed": final_gate_passed,
        "amount_matches_current_setting": amount_matches_current_setting,
        "amount_locked_to_current_setting": amount_locked_to_current_setting,
        "amount_locked_to_10000_deprecated": amount_locked_to_10000_deprecated,
        "caps_validated": caps_validated,
        "source_policy_validated": source_policy_validated,
        "riskguard_readonly_validated": riskguard_readonly_validated,
        "live_preflight_readonly_validated": live_preflight_readonly_validated,
        "unlock_final_confirmation_validated": unlock_final_confirmation_validated,
        "duplicate_repeat_relock_validated": duplicate_repeat_relock_validated,
        "final_emit_gate_validated": final_emit_gate_validated,
        "actual_order": False,
        "actual_order_intent_emitted": False,
        "would_emit_order_intent": False,
        "order_intent_emitted": False,
        "would_consume_unlock": False,
        "unlock_consumed": False,
        "unlock_service_called": False,
        "decision_router_called": False,
        "risk_guard_called": False,
        "live_preflight_called": False,
        "execution_bridge_called": False,
        "order_service_called": False,
        "order_adapter_called": False,
        "provider_external_call_count": 0,
        "submitted_count": 0,
        "managed_pool_mutation": False,
        "order_risk_detected": False,
        "blockers": blockers,
        "warnings": warnings,
        "safety_summary": {
            "mode": "armed_but_not_submitted",
            "actual_order": False,
            "submitted_count": 0,
            "unlock_consumed": False,
            "order_adapter_called": False,
            "operator_confirm_phrase_required_for_next_goal": True,
        },
        "safety_flags": safety_flags,
    }


def _validate_live_minimal_order_armed_contract_v1(result: dict[str, Any] | None) -> list[str]:
    if not result:
        return ["live_minimal_order_armed_result_missing"]
    errors: list[str] = []
    if result.get("schema") != "aits_live_minimal_order_armed_contract_v1":
        errors.append("schema_invalid")
    if result.get("armed_mode") != "not_submitted":
        errors.append("armed_mode_invalid")
    for key in (
        "actual_order",
        "actual_order_intent_emitted",
        "would_emit_order_intent",
        "order_intent_emitted",
        "would_consume_unlock",
        "unlock_consumed",
        "unlock_service_called",
        "decision_router_called",
        "risk_guard_called",
        "live_preflight_called",
        "execution_bridge_called",
        "order_service_called",
        "order_adapter_called",
        "managed_pool_mutation",
        "order_risk_detected",
    ):
        if bool(result.get(key)):
            errors.append(f"{key}_must_be_false")
    if int(result.get("submitted_count") or 0) != 0:
        errors.append("submitted_count_must_be_zero")
    if int(result.get("provider_external_call_count") or 0) != 0:
        errors.append("provider_call_count_must_be_zero")
    if result.get("live_minimal_order_armed") and result.get("blockers"):
        errors.append("armed_ready_with_blockers")
    if result.get("live_minimal_order_armed") and not result.get("operator_confirm_phrase_matched"):
        errors.append("armed_without_confirm_phrase_match")
    return errors


def _build_live_minimal_order_armed_result(
    candidate: dict[str, Any],
    *,
    target_symbol: str = "",
    session_approved_symbols: Any = None,
    mock_unlock_approved_symbols: Any = None,
    intended_amount_krw: int | None = None,
    mock_total_window_used_krw: int = 0,
    mock_submitted_count: int = 0,
    operator_confirm_phrase: str = "",
    configured_order_amount_krw: int | None = None,
    armed_input_overrides: dict[str, Any] | None = None,
    armed_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    final_gate_result = _build_live_order_final_gate_integration_result(
        candidate,
        target_symbol=target_symbol or str(candidate.get("symbol") or ""),
        session_approved_symbols=session_approved_symbols,
        mock_unlock_approved_symbols=mock_unlock_approved_symbols,
        intended_amount_krw=intended_amount_krw,
        mock_total_window_used_krw=mock_total_window_used_krw,
        mock_submitted_count=mock_submitted_count,
    )
    armed_input = _build_live_minimal_order_armed_input_v1(
        final_gate_result,
        operator_confirm_phrase=operator_confirm_phrase,
        configured_order_amount_krw=configured_order_amount_krw,
        overrides=armed_input_overrides,
    )
    armed_contract = _evaluate_live_minimal_order_armed_contract_v1(
        armed_input,
        context=armed_context,
    )
    validation_errors = _validate_live_minimal_order_armed_contract_v1(armed_contract)
    return {
        "candidate": dict(candidate or {}),
        "final_gate_result": final_gate_result,
        "armed_input": armed_input,
        "armed_contract": armed_contract,
        "schema": armed_contract.get("schema"),
        "target_symbol": armed_contract.get("target_symbol"),
        "intended_side": armed_contract.get("intended_side"),
        "intended_amount_krw": armed_contract.get("intended_amount_krw"),
        "configured_order_amount_krw": armed_contract.get("configured_order_amount_krw"),
        "current_setting_order_amount_krw": armed_contract.get("current_setting_order_amount_krw"),
        "live_minimal_order_armed": bool(armed_contract.get("live_minimal_order_armed")),
        "armed_mode": armed_contract.get("armed_mode"),
        "next_allowed_goal": armed_contract.get("next_allowed_goal"),
        "expected_confirm_phrase": armed_contract.get("expected_confirm_phrase"),
        "operator_confirm_phrase_matched": bool(armed_contract.get("operator_confirm_phrase_matched")),
        "final_gate_passed": bool(armed_contract.get("final_gate_passed")),
        "amount_matches_current_setting": bool(armed_contract.get("amount_matches_current_setting")),
        "amount_locked_to_current_setting": bool(armed_contract.get("amount_locked_to_current_setting")),
        "amount_locked_to_10000_deprecated": bool(armed_contract.get("amount_locked_to_10000_deprecated")),
        "caps_validated": bool(armed_contract.get("caps_validated")),
        "source_policy_validated": bool(armed_contract.get("source_policy_validated")),
        "riskguard_readonly_validated": bool(armed_contract.get("riskguard_readonly_validated")),
        "live_preflight_readonly_validated": bool(armed_contract.get("live_preflight_readonly_validated")),
        "unlock_final_confirmation_validated": bool(armed_contract.get("unlock_final_confirmation_validated")),
        "duplicate_repeat_relock_validated": bool(armed_contract.get("duplicate_repeat_relock_validated")),
        "final_emit_gate_validated": bool(armed_contract.get("final_emit_gate_validated")),
        "actual_order": False,
        "actual_order_intent_emitted": False,
        "would_emit_order_intent": False,
        "order_intent_emitted": False,
        "would_consume_unlock": False,
        "unlock_consumed": False,
        "unlock_service_called": False,
        "decision_router_called": False,
        "risk_guard_called": False,
        "live_preflight_called": False,
        "execution_bridge_called": False,
        "order_service_called": False,
        "order_adapter_called": False,
        "provider_external_call_count": 0,
        "submitted_count": 0,
        "managed_pool_mutation": False,
        "order_risk_detected": False,
        "blockers": list(armed_contract.get("blockers") or []),
        "warnings": list(armed_contract.get("warnings") or []),
        "safety_summary": dict(armed_contract.get("safety_summary") or {}),
        "validation_errors": validation_errors,
    }


def _run_live_minimal_order_armed_fixture_proof(
    report: dict[str, Any],
    *,
    configured_order_amount_krw: int = 10_000,
    intended_amount_krw: int = 10_000,
    operator_confirm_phrase: str = "",
    mock_submitted_count: int = 0,
) -> None:
    valid = _base_source_policy_candidate("user_added", "KRW-PYTH")
    phrase = "AITS LIVE ORDER KRW-PYTH BUY 10000"
    requested_expected_phrase = f"AITS LIVE ORDER KRW-PYTH BUY {int(configured_order_amount_krw or 0)}"
    requested_expected_armed = (
        int(configured_order_amount_krw or 0) == int(intended_amount_krw or 0)
        and 10_000 <= int(configured_order_amount_krw or 0) <= 12_000
        and int(mock_submitted_count or 0) == 0
        and str(operator_confirm_phrase or "") == requested_expected_phrase
    )
    requested_expected_blockers: list[str] = []
    if int(configured_order_amount_krw or 0) != int(intended_amount_krw or 0):
        requested_expected_blockers.append("intended_amount_not_matching_configured_setting")
    if int(configured_order_amount_krw or 0) < 10_000:
        requested_expected_blockers.append("configured_amount_below_min_order")
    if int(configured_order_amount_krw or 0) > 12_000:
        requested_expected_blockers.append("configured_amount_exceeds_per_order_hard_cap")
    if int(mock_submitted_count or 0) != 0:
        requested_expected_blockers.append("submitted_count_not_zero")
    if not str(operator_confirm_phrase or ""):
        requested_expected_blockers.append("operator_confirm_phrase_missing")
    elif str(operator_confirm_phrase or "") != requested_expected_phrase:
        requested_expected_blockers.append("operator_confirm_phrase_mismatch")
    scenarios: list[dict[str, Any]] = [
        {"name": "requested_setting_amount_case", "candidate": {**valid, "intended_amount_krw": int(intended_amount_krw or 0)}, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "amount": int(intended_amount_krw or 0), "configured": int(configured_order_amount_krw or 0), "phrase": str(operator_confirm_phrase or ""), "submitted": int(mock_submitted_count or 0), "expected_armed": requested_expected_armed, "expected_blockers": requested_expected_blockers},
        {"name": "valid_10000_current_setting_armed_not_submitted", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "configured": 10_000, "amount": 10_000, "phrase": phrase, "expected_armed": True, "expected_blockers": []},
        {"name": "valid_11000_current_setting_armed_not_submitted", "candidate": {**valid, "intended_amount_krw": 11_000}, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "configured": 11_000, "amount": 11_000, "phrase": "AITS LIVE ORDER KRW-PYTH BUY 11000", "expected_armed": True, "expected_blockers": []},
        {"name": "configured_11000_intended_10000_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "configured": 11_000, "amount": 10_000, "phrase": phrase, "expected_armed": False, "expected_blockers": ["intended_amount_not_matching_configured_setting"]},
        {"name": "configured_amount_13000_blocks", "candidate": {**valid, "intended_amount_krw": 13_000}, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "configured": 13_000, "amount": 13_000, "phrase": "AITS LIVE ORDER KRW-PYTH BUY 13000", "expected_armed": False, "expected_blockers": ["configured_amount_exceeds_per_order_hard_cap"]},
        {"name": "configured_amount_5000_blocks", "candidate": {**valid, "intended_amount_krw": 5_000}, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "configured": 5_000, "amount": 5_000, "phrase": "AITS LIVE ORDER KRW-PYTH BUY 5000", "expected_armed": False, "expected_blockers": ["configured_amount_below_min_order"]},
        {"name": "mock_submitted_count_1_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "submitted": 1, "phrase": phrase, "expected_armed": False, "expected_blockers": ["submitted_count_not_zero"]},
        {"name": "session_approved_empty_blocks", "candidate": valid, "approved": [], "unlock": ["KRW-PYTH"], "phrase": phrase, "expected_armed": False, "expected_blockers": ["user_added_not_session_approved"]},
        {"name": "operator_confirm_phrase_missing_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "phrase": "", "expected_armed": False, "expected_blockers": ["operator_confirm_phrase_missing"]},
        {"name": "operator_confirm_phrase_mismatch_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "phrase": "AITS LIVE ORDER KRW-PYTH BUY 9999", "expected_armed": False, "expected_blockers": ["operator_confirm_phrase_mismatch"]},
        {"name": "would_emit_order_intent_true_blocks", "candidate": valid, "approved": ["KRW-PYTH"], "unlock": ["KRW-PYTH"], "phrase": phrase, "context": {"would_emit_order_intent": True}, "expected_armed": False, "expected_blockers": ["would_emit_order_intent_detected"]},
    ]
    forced_false_keys = (
        "actual_order",
        "actual_order_intent_emitted",
        "would_emit_order_intent",
        "order_intent_emitted",
        "would_consume_unlock",
        "unlock_consumed",
        "unlock_service_called",
        "decision_router_called",
        "risk_guard_called",
        "live_preflight_called",
        "execution_bridge_called",
        "order_service_called",
        "order_adapter_called",
        "managed_pool_mutation",
        "order_risk_detected",
    )
    results: list[dict[str, Any]] = []
    for scenario in scenarios:
        result = _build_live_minimal_order_armed_result(
            scenario["candidate"],
            target_symbol=str(scenario["candidate"].get("symbol") or ""),
            session_approved_symbols=scenario.get("approved"),
            mock_unlock_approved_symbols=scenario.get("unlock"),
            intended_amount_krw=scenario.get("amount"),
            mock_total_window_used_krw=int(scenario.get("used") or 0),
            mock_submitted_count=int(scenario.get("submitted") or 0),
            operator_confirm_phrase=str(scenario.get("phrase") or ""),
            configured_order_amount_krw=int(scenario.get("configured") or scenario.get("amount") or 10_000),
            armed_input_overrides=scenario.get("overrides"),
            armed_context=scenario.get("context"),
        )
        blockers = set(result.get("blockers") or [])
        passed = bool(result.get("live_minimal_order_armed")) == bool(scenario["expected_armed"])
        passed = passed and all(blocker in blockers for blocker in scenario.get("expected_blockers") or [])
        passed = passed and result.get("armed_mode") == "not_submitted"
        passed = passed and result.get("next_allowed_goal") == "AITS-LIVE-MINIMAL-ORDER-SETTING-AMOUNT-ONE-SHOT-TEST-01"
        passed = passed and not result.get("validation_errors")
        passed = passed and not any(bool(result.get(key)) for key in forced_false_keys)
        results.append({"name": scenario["name"], "pass": passed, **result})
    valid_result = next((item for item in results if item.get("name") == "requested_setting_amount_case"), {})
    report.update(
        {
            "live_minimal_order_armed_supported": True,
            "schema": "aits_live_minimal_order_armed_contract_v1",
            "contract_helper_owner": "tools/runtime_smoke/aits_qt_smoke_harness.py::_evaluate_live_minimal_order_armed_contract_v1",
            "fixture_results": results,
            "fixture_pass_count": sum(1 for item in results if item.get("pass")),
            "fixture_fail_count": sum(1 for item in results if not item.get("pass")),
            "live_minimal_order_armed": bool(valid_result.get("live_minimal_order_armed")),
            "armed_mode": valid_result.get("armed_mode"),
            "next_allowed_goal": valid_result.get("next_allowed_goal"),
            "intended_amount_krw": valid_result.get("intended_amount_krw"),
            "configured_order_amount_krw": valid_result.get("configured_order_amount_krw"),
            "current_setting_order_amount_krw": valid_result.get("current_setting_order_amount_krw"),
            "amount_matches_current_setting": bool(valid_result.get("amount_matches_current_setting")),
            "amount_locked_to_current_setting": bool(valid_result.get("amount_locked_to_current_setting")),
            "amount_locked_to_10000_deprecated": bool(valid_result.get("amount_locked_to_10000_deprecated")),
            "expected_confirm_phrase": valid_result.get("expected_confirm_phrase"),
            "operator_confirm_phrase_matched": bool(valid_result.get("operator_confirm_phrase_matched")),
            "actual_order": False,
            "actual_order_intent_emitted": False,
            "would_emit_order_intent": False,
            "order_intent_emitted": False,
            "would_consume_unlock": False,
            "unlock_consumed": False,
            "unlock_service_called": False,
            "decision_router_called": False,
            "risk_guard_called": False,
            "live_preflight_called": False,
            "execution_bridge_called": False,
            "order_service_called": False,
            "order_adapter_called": False,
            "final_action_unchanged": True,
            "submitted_count": 0,
            "provider_external_call_count": 0,
            "managed_pool_mutation": False,
            "order_risk_detected": False,
        }
    )
    report["pass_status"] = "pass" if report["fixture_fail_count"] == 0 else "fail"
    report["status"] = report["pass_status"]


def _run_live_minimal_order_armed_live_proof(
    report: dict[str, Any],
    *,
    output_dir: Path,
    target_symbol: str | None = None,
    min_score: float = 60.0,
    session_approved_symbols: Any = None,
    mock_unlock_approved_symbols: Any = None,
    intended_amount_krw: int = 10_000,
    configured_order_amount_krw: int | None = None,
    mock_total_window_used_krw: int = 0,
    mock_submitted_count: int = 0,
    operator_confirm_phrase: str = "",
) -> None:
    embedded: dict[str, Any] = {"mode": "live-order-final-gate-integration-live-proof", "embedded": True}
    _run_live_order_final_gate_integration_live_proof(
        embedded,
        output_dir=output_dir,
        target_symbol=target_symbol,
        min_score=min_score,
        session_approved_symbols=session_approved_symbols,
        mock_unlock_approved_symbols=mock_unlock_approved_symbols,
        intended_amount_krw=intended_amount_krw,
        mock_total_window_used_krw=mock_total_window_used_krw,
        mock_submitted_count=mock_submitted_count,
    )
    candidate = dict(embedded.get("candidate") or {})
    if not candidate:
        candidate = _base_source_policy_candidate("user_added", str(target_symbol or "KRW-PYTH"))
    result = _build_live_minimal_order_armed_result(
        candidate,
        target_symbol=str(target_symbol or embedded.get("target_symbol") or candidate.get("symbol") or ""),
        session_approved_symbols=session_approved_symbols,
        mock_unlock_approved_symbols=mock_unlock_approved_symbols,
        intended_amount_krw=intended_amount_krw,
        mock_total_window_used_krw=mock_total_window_used_krw,
        mock_submitted_count=mock_submitted_count,
        operator_confirm_phrase=operator_confirm_phrase,
        configured_order_amount_krw=configured_order_amount_krw,
    )
    expected_safe = not any(
        bool(result.get(key))
        for key in (
            "actual_order",
            "actual_order_intent_emitted",
            "would_emit_order_intent",
            "order_intent_emitted",
            "would_consume_unlock",
            "unlock_consumed",
            "unlock_service_called",
            "decision_router_called",
            "risk_guard_called",
            "live_preflight_called",
            "execution_bridge_called",
            "order_service_called",
            "order_adapter_called",
            "managed_pool_mutation",
            "order_risk_detected",
        )
    )
    report.update(
        {
            "mode": "live-minimal-order-armed-live-proof",
            "live_minimal_order_armed_supported": True,
            "schema": "aits_live_minimal_order_armed_contract_v1",
            "contract_helper_owner": "tools/runtime_smoke/aits_qt_smoke_harness.py::_evaluate_live_minimal_order_armed_contract_v1",
            "target_symbol": str(target_symbol or embedded.get("target_symbol") or result.get("target_symbol") or ""),
            "session_approved_symbols": _normalized_session_approved_symbols(session_approved_symbols),
            "mock_unlock_approved_symbols": _normalized_session_approved_symbols(mock_unlock_approved_symbols),
            "embedded_final_gate_report": {
                "status": embedded.get("status"),
                "live_order_final_gate_ready": embedded.get("live_order_final_gate_ready"),
                "final_confirmation_ready": embedded.get("final_confirmation_ready"),
                "duplicate_repeat_relock_ready": embedded.get("duplicate_repeat_relock_ready"),
                "final_emit_gate_ready": embedded.get("final_emit_gate_ready"),
                "live_minimal_order_readiness_ready": embedded.get("live_minimal_order_readiness_ready"),
                "blockers": embedded.get("blockers"),
                "validation_errors": embedded.get("validation_errors"),
            },
            **result,
        }
    )
    report["pass_status"] = "pass" if expected_safe and not result.get("validation_errors") and result.get("live_minimal_order_armed") else "fail"
    report["status"] = report["pass_status"]


def _run_live_minimal_order_setting_readpath_preflight(
    report: dict[str, Any],
    *,
    target_symbol: str | None = None,
) -> None:
    blockers: list[str] = []
    warnings: list[str] = []
    configured_amount = 0
    configured_source = "unknown"
    prefs_path = ""
    load_error = ""

    try:
        from app.utils.prefs import _get_prefs_path, load_settings

        prefs_path = str(_get_prefs_path() or "")
        settings = load_settings()
        strategy = getattr(settings, "strategy", None)
        if hasattr(strategy, "model_dump"):
            strategy_payload = strategy.model_dump()
        elif isinstance(strategy, dict):
            strategy_payload = dict(strategy)
        else:
            strategy_payload = {}
        configured_amount = int(strategy_payload.get("order_amount_krw") or 0)
        configured_source = "prefs.load_settings.strategy.order_amount_krw"
    except Exception as exc:
        load_error = f"{type(exc).__name__}: {exc}"
        blockers.append("configured_order_amount_read_path_missing")

    schema_default = 0
    try:
        from app.utils.settings_schema import StrategyConfig

        schema_default = int(getattr(StrategyConfig(), "order_amount_krw", 0) or 0)
    except Exception as exc:
        warnings.append(f"settings_schema_default_unavailable:{type(exc).__name__}")

    target = _normalize_symbol_text(str(target_symbol or "KRW-PYTH"))
    min_order = 10_000
    per_order_cap = 12_000
    window_cap = 20_000
    total_window_used = 0
    total_after = total_window_used + configured_amount
    template = "AITS LIVE ORDER {symbol} {side.upper()} {configured_order_amount_krw}"
    sample_phrase = f"AITS LIVE ORDER {target} BUY {configured_amount}" if target and configured_amount else ""

    amount_ssot_confirmed = bool(
        configured_amount
        and configured_source == "prefs.load_settings.strategy.order_amount_krw"
        and schema_default == 10_000
    )
    amount_is_hardcoded = False
    if not configured_amount:
        blockers.append("configured_order_amount_read_path_missing")
    if not amount_ssot_confirmed:
        blockers.append("amount_ssot_not_confirmed")
    if amount_is_hardcoded:
        blockers.append("amount_hardcoded_to_10000")
    if configured_amount and configured_amount < min_order:
        blockers.append("configured_amount_below_min_order")
    if configured_amount and configured_amount > per_order_cap:
        blockers.append("configured_amount_exceeds_per_order_hard_cap")
    if configured_amount and total_after > window_cap:
        blockers.append("guarded_window_cap_not_verifiable")
    if "{configured_order_amount_krw}" not in template:
        blockers.append("confirm_phrase_not_setting_amount_based")

    safety_flags = {
        "actual_order": False,
        "actual_order_intent_emitted": False,
        "would_emit_order_intent": False,
        "order_intent_emitted": False,
        "would_consume_unlock": False,
        "unlock_consumed": False,
        "unlock_service_called": False,
        "decision_router_called": False,
        "risk_guard_called": False,
        "live_preflight_called": False,
        "execution_bridge_called": False,
        "order_service_called": False,
        "order_adapter_called": False,
        "provider_external_call_count": 0,
        "submitted_count": 0,
        "managed_pool_mutation": False,
        "order_risk_detected": False,
    }
    ready = bool(not blockers)
    report.update(
        {
            "mode": "live-minimal-order-setting-readpath-preflight",
            "schema": "aits_live_minimal_order_setting_readpath_preflight_v1",
            "configured_order_amount_krw": configured_amount,
            "configured_order_amount_source": configured_source,
            "ui_setting_key": "StrategyTab.spn_order_amount -> settings.strategy.order_amount_krw",
            "runtime_setting_key": "MainWindow._settings.strategy.order_amount_krw",
            "prefs_key": "prefs.json.strategy.order_amount_krw",
            "settings_schema_key": "StrategyConfig.order_amount_krw",
            "prefs_path": prefs_path,
            "read_error": load_error,
            "amount_ssot_confirmed": amount_ssot_confirmed,
            "amount_is_hardcoded": amount_is_hardcoded,
            "current_default_or_current_value_krw": configured_amount or schema_default,
            "settings_schema_default_order_amount_krw": schema_default,
            "min_order_krw": min_order,
            "ui_preflight_min_order_krw": 5_000,
            "per_order_hard_cap_krw": per_order_cap,
            "total_guarded_window_cap_krw": window_cap,
            "hard_cap_validated": bool(configured_amount and min_order <= configured_amount <= per_order_cap),
            "window_cap_validated": bool(configured_amount and total_after <= window_cap),
            "next_confirm_phrase_template": template,
            "sample_confirm_phrase_for_current_amount": sample_phrase,
            "ready_for_setting_amount_one_shot_test": ready,
            "next_allowed_goal": "AITS-LIVE-MINIMAL-ORDER-SETTING-AMOUNT-ONE-SHOT-TEST-01",
            "blockers": list(dict.fromkeys(blockers)),
            "warnings": list(dict.fromkeys(warnings)),
            "actual_order": False,
            "actual_order_intent_emitted": False,
            "submitted_count": 0,
            "provider_external_call_count": 0,
            "safety_flags": safety_flags,
            **safety_flags,
        }
    )
    report["pass_status"] = "pass" if ready else "blocked"
    report["status"] = report["pass_status"]


def _read_live_on_runtime_e2e_order_amount() -> tuple[int, str, str]:
    try:
        from app.utils.prefs import load_settings

        settings = load_settings()
        strategy = getattr(settings, "strategy", None)
        if hasattr(strategy, "model_dump"):
            payload = strategy.model_dump()
        elif isinstance(strategy, dict):
            payload = dict(strategy)
        else:
            payload = {}
        return int(payload.get("order_amount_krw") or 0), "prefs.load_settings.strategy.order_amount_krw", ""
    except Exception as exc:
        return 0, "unavailable", f"{type(exc).__name__}: {exc}"


def _live_on_runtime_e2e_tail_log(max_chars: int = 12_000_000) -> tuple[list[str], str, str]:
    log_dir = ROOT / "data" / "logs"
    log_candidates = [
        log_dir / "aits.log.3",
        log_dir / "aits.log.2",
        log_dir / "aits.log.1",
        log_dir / "aits.log",
    ]
    existing_paths = [path for path in log_candidates if path.exists()]
    if not existing_paths:
        return [], str(log_dir / "aits.log"), "log_missing"
    try:
        text = "\n".join(path.read_text(encoding="utf-8", errors="replace") for path in existing_paths)
    except Exception as exc:
        return [], ",".join(str(path) for path in existing_paths), f"log_read_error:{type(exc).__name__}"
    if len(text) > max_chars:
        text = text[-max_chars:]
    return text.splitlines(), ",".join(str(path) for path in existing_paths), ""



def _aits_extract_kv_text(line: str, key: str) -> str:
    match = re.search(rf"(?:^|[\s|]){re.escape(key)}[=:]\s*([^\s|]+)", str(line or ""))
    return str(match.group(1)).strip() if match else ""


def _aits_extract_kv_int(line: str, key: str, default: int = 0) -> int:
    raw = _aits_extract_kv_text(line, key)
    if raw == "":
        return default
    try:
        return int(float(str(raw).replace(",", "")))
    except Exception:
        return default


def _aits_extract_kv_bool(line: str, key: str, default: bool = False) -> bool:
    raw = _aits_extract_kv_text(line, key).lower()
    if raw in {"true", "1", "yes", "ok", "ready"}:
        return True
    if raw in {"false", "0", "no", "failed", "degraded"}:
        return False
    return default


def _aits_latest_line_with(lines: list[str], *needles: str) -> str:
    lowered_needles = [str(n).lower() for n in needles if str(n or "")]
    for line in reversed(lines):
        low = line.lower()
        if all(n in low for n in lowered_needles):
            return line
    return ""


def _aits_latest_report_at_or_after(report: dict[str, Any], since: datetime | None) -> bool:
    if since is None:
        return True
    raw = str(report.get("finished_at") or report.get("started_at") or "")
    if not raw:
        return False
    try:
        dt = datetime.fromisoformat(raw)
        if dt.tzinfo is None and since.tzinfo is not None:
            dt = dt.replace(tzinfo=since.tzinfo)
        return dt >= since
    except Exception:
        return False


def _aits_current_git_head() -> str:
    try:
        proc = subprocess.run(
            ["git", "rev-parse", "--short=12", "HEAD"],
            cwd=str(ROOT),
            capture_output=True,
            text=True,
            timeout=5,
        )
        if proc.returncode == 0:
            return str(proc.stdout or "").strip()
    except Exception:
        pass
    return ""


def _market_feed_profile_from_feed_report(
    profile_name: str,
    feed: dict[str, Any],
    *,
    python_executable: str = "",
    cwd: str = "",
    frozen: bool = False,
    git_head: str = "",
    request_target: str = "https://api.upbit.com/v1/market/all,/v1/ticker",
) -> dict[str, Any]:
    return {
        "profile_name": profile_name,
        "python_executable": python_executable or sys.executable,
        "cwd": cwd or str(ROOT),
        "frozen": bool(frozen),
        "git_head": git_head or _aits_current_git_head(),
        "request_target": request_target,
        "market_count_raw": int(feed.get("market_count_raw") or 0),
        "ticker_count": int(feed.get("ticker_count") or 0),
        "top_markets_count": int(feed.get("top_markets_count") or 0),
        "exception_type": str(feed.get("exception_type") or ""),
        "exception_message_sanitized": str(feed.get("error_message_sanitized") or "")[:220],
        "elapsed_ms": int(feed.get("duration_ms") or 0),
        "network_ok": bool(int(feed.get("top_markets_count") or 0) > 0),
        "empty_reason": str(feed.get("empty_reason") or ""),
        "network_state": str(feed.get("network_state") or ""),
        "submitted": 0,
        "order_allowed": False,
        "real_order": False,
    }


def _market_feed_profile_from_runtime_logs(profile_name: str, lines: list[str]) -> dict[str, Any]:
    provenance = _aits_latest_line_with(lines, "[aits][runtimeprovenance]")
    runtime = _aits_latest_line_with(lines, "[aits][runtimefeedreadiness]")
    public_top = _aits_latest_line_with(lines, "[aits][publicmarketfeed]", "event=top_markets_result")
    public_ticker = _aits_latest_line_with(lines, "[aits][publicmarketfeed]", "event=tickers_result")
    feed = _analyze_live_on_market_feed_readiness(lines)
    app_gui_file = _aits_extract_kv_text(provenance, "app_gui_file")
    git_head = _aits_extract_kv_text(provenance, "git_head_if_available") or _aits_current_git_head()
    python_exe = _aits_extract_kv_text(provenance, "python_executable")
    cwd = _aits_extract_kv_text(provenance, "cwd") or str(ROOT)
    frozen = _aits_extract_kv_bool(provenance, "frozen", False)
    exception_type = (
        str(feed.get("latest_public_feed_exception_type") or "")
        or _aits_extract_kv_text(public_top, "exception_type")
        or _aits_extract_kv_text(public_ticker, "exception_type")
    )
    return {
        "profile_name": profile_name,
        "python_executable": python_exe,
        "cwd": cwd,
        "frozen": bool(frozen),
        "git_head": git_head,
        "app_gui_file": app_gui_file,
        "request_target": "runtime_log_public_market_feed",
        "market_count_raw": 0,
        "ticker_count": int(feed.get("latest_tickers_count") or 0),
        "top_markets_count": int(feed.get("latest_top_markets_count") or 0),
        "exception_type": exception_type,
        "exception_message_sanitized": "",
        "elapsed_ms": 0,
        "network_ok": bool(feed.get("market_feed_ok")),
        "market_feed_ok": bool(feed.get("market_feed_ok")),
        "market_feed_blocker": str(feed.get("market_feed_blocker") or ""),
        "market_feed_reason": str(feed.get("market_feed_reason") or ""),
        "runtime_feed_line_present": bool(runtime),
        "public_feed_line_present": bool(public_top or public_ticker),
        "submitted": 0,
        "order_allowed": False,
        "real_order": False,
    }


def _runtime_provenance_session_lines(lines: list[str]) -> tuple[list[str], str, datetime | None, int, int]:
    provenance_indices = [idx for idx, line in enumerate(lines) if "[AITS][RuntimeProvenance]" in line]
    if not provenance_indices:
        return [], "", None, -1, -1
    start_idx = provenance_indices[-1]
    latest_provenance = lines[start_idx]
    session_started_at_dt = _runtime_provenance_line_ts(latest_provenance)
    session_lines = lines[start_idx:]
    if session_started_at_dt is not None:
        session_lines = [
            line for line in session_lines
            if (_runtime_provenance_line_ts(line) is None or _runtime_provenance_line_ts(line) >= session_started_at_dt)
        ]
    return session_lines, latest_provenance, session_started_at_dt, start_idx + 1, len(lines)


def _dt_from_report_field(item: dict[str, Any], key: str, fallback: str = "") -> datetime | None:
    raw = str(item.get(key) or item.get(fallback) or "")
    if not raw:
        return None
    try:
        return datetime.fromisoformat(raw)
    except Exception:
        return None


def _harness_report_for_session_start(session_started_at_dt: datetime | None, reports: list[dict[str, Any]]) -> str:
    if session_started_at_dt is None:
        return ""
    harness_launch_modes = {
        "dry-read",
        "dry-navigation",
        "live-on-runtime-harness-driven-click-run",
        "live-on-runtime-harness-driven-click-run-provider-check-once",
        "provider-key-resolution-bootstrap-trace",
        "provider-key-resolution-restart-regression-proof",
        "engine-connection-status-path-diagnostic",
        "engine-connection-status-regression-proof",
        "engine-connection-key-refresh-regression-proof",
        "provider-settings-runtime-ssot-diagnostic",
        "provider-settings-restart-restore-regression-proof",
        "provider-switching-cross-provider-regression-proof",
    }
    for item in reports:
        if str(item.get("mode") or "") not in harness_launch_modes:
            continue
        started_dt = _dt_from_report_field(item, "started_at")
        finished_dt = _dt_from_report_field(item, "finished_at", fallback="started_at")
        if started_dt is None or finished_dt is None:
            continue
        if session_started_at_dt.tzinfo is None and started_dt.tzinfo is not None:
            session_started_at_dt = session_started_at_dt.replace(tzinfo=started_dt.tzinfo)
        if session_started_at_dt.tzinfo is None and finished_dt.tzinfo is not None:
            session_started_at_dt = session_started_at_dt.replace(tzinfo=finished_dt.tzinfo)
        if started_dt.tzinfo is None and session_started_at_dt.tzinfo is not None:
            started_dt = started_dt.replace(tzinfo=session_started_at_dt.tzinfo)
        if finished_dt.tzinfo is None and session_started_at_dt.tzinfo is not None:
            finished_dt = finished_dt.replace(tzinfo=session_started_at_dt.tzinfo)
        if started_dt <= session_started_at_dt <= finished_dt:
            return str(item.get("_report_path") or item.get("report_path") or item.get("mode") or "")
    return ""


def _latest_non_harness_runtime_session(
    lines: list[str],
    reports: list[dict[str, Any]],
) -> tuple[list[str], str, datetime | None, int, int, str]:
    provenance_indices = [idx for idx, line in enumerate(lines) if "[AITS][RuntimeProvenance]" in line]
    latest_harness_report = ""
    for pos in range(len(provenance_indices) - 1, -1, -1):
        start_idx = provenance_indices[pos]
        end_idx = provenance_indices[pos + 1] if pos + 1 < len(provenance_indices) else len(lines)
        provenance = lines[start_idx]
        started_at = _runtime_provenance_line_ts(provenance)
        harness_report = _harness_report_for_session_start(started_at, reports)
        if harness_report:
            latest_harness_report = latest_harness_report or harness_report
            continue
        session_lines = lines[start_idx:end_idx]
        if started_at is not None:
            session_lines = [
                line for line in session_lines
                if (_runtime_provenance_line_ts(line) is None or _runtime_provenance_line_ts(line) >= started_at)
            ]
        return session_lines, provenance, started_at, start_idx + 1, end_idx, latest_harness_report
    latest_provenance = lines[provenance_indices[-1]] if provenance_indices else ""
    latest_started = _runtime_provenance_line_ts(latest_provenance)
    return [], latest_provenance, latest_started, -1, -1, latest_harness_report


def _run_real_user_app_public_feed_profile_summary(report: dict[str, Any], *, output_dir: Path) -> None:
    lines, log_path, log_read_error = _live_on_runtime_e2e_tail_log(max_chars=1_500_000)
    reports = _live_on_runtime_e2e_latest_reports(output_dir)
    session_lines, latest_provenance, session_started_at_dt, start_line, end_line, harness_session_report = _latest_non_harness_runtime_session(lines, reports)
    user_session_detected = bool(session_lines)
    user_profile = _market_feed_profile_from_runtime_logs("user_app_process", session_lines) if user_session_detected else {}
    network_profile = _live_on_runtime_e2e_latest_report_by_mode(reports, "public-market-feed-network-profile-proof")
    harness_ok = bool(network_profile.get("harness_process_network_ok"))
    observed_app_ok = bool(network_profile.get("app_process_network_ok"))
    external_ok = bool(network_profile.get("external_public_read_network_ok"))
    user_ok = bool(user_profile.get("network_ok")) if user_profile else False
    feed = _analyze_live_on_market_feed_readiness(session_lines) if user_session_detected else {}
    score_lines = [
        line for line in session_lines
        if "CandidateFeedState" in line or "score_update" in line or "ai score update" in line
    ]
    process_pid = _aits_extract_kv_text(latest_provenance, "process_pid")
    started_at = session_started_at_dt.isoformat(timespec="seconds") if session_started_at_dt else ""
    if not session_lines:
        split_result = "no_user_app_session_detected"
        next_fix = "ask_user_to_launch_app_manually_and_wait_for_feed_logs"
    elif harness_session_report and not session_lines:
        split_result = "harness_launched_app_session_detected"
        next_fix = "ask_user_to_launch_app_manually_and_wait_for_feed_logs"
    elif user_ok and not harness_ok:
        split_result = "user_app_ok_harness_restricted"
        next_fix = "run_on_runtime_click_in_user_app_profile_or_attach_user_app_event_log"
    elif (not user_ok) and (not harness_ok) and external_ok:
        split_result = "external_ok_all_local_restricted"
        next_fix = "fix_windows_app_process_public_feed_network"
    elif (not user_ok) and (not harness_ok):
        split_result = "user_app_and_harness_both_restricted"
        next_fix = "fix_windows_app_process_public_feed_network"
    elif user_ok:
        split_result = "user_app_public_feed_ok"
        next_fix = "continue_live_on_runtime_stage_trace_in_user_app_profile"
    else:
        split_result = "user_app_public_feed_not_ready"
        next_fix = "inspect_user_app_public_feed_log_reason"
    report.update(
        {
            "schema": "aits_real_user_app_public_feed_profile_summary_v1",
            "diagnostic_status": "pass",
            "runtime_provenance_detected": bool(latest_provenance),
            "user_app_process_detected": user_session_detected,
            "harness_launched_app_session_detected": bool(harness_session_report),
            "harness_session_report": harness_session_report,
            "process_pid": process_pid,
            "python_executable": _aits_extract_kv_text(latest_provenance, "python_executable"),
            "cwd": _aits_extract_kv_text(latest_provenance, "cwd"),
            "frozen": _aits_extract_kv_bool(latest_provenance, "frozen", False),
            "git_head_detected": _aits_extract_kv_text(latest_provenance, "git_head_if_available"),
            "app_gui_file": _aits_extract_kv_text(latest_provenance, "app_gui_file"),
            "started_at": started_at,
            "session_log_start_line": start_line,
            "session_log_end_line": end_line,
            "log_path": log_path,
            "log_read_error": log_read_error,
            "user_app_process_profile": user_profile,
            "user_app_market_feed_ok": bool(feed.get("market_feed_ok")),
            "user_app_process_network_ok": user_ok,
            "user_app_network_status": str(feed.get("latest_network_status") or user_profile.get("network_state") or ""),
            "user_app_top_markets_count": int(feed.get("latest_top_markets_count") or 0),
            "user_app_tickers_count": int(feed.get("latest_tickers_count") or 0),
            "user_app_score_update_total": len(score_lines),
            "user_app_buy_ready_count": int(feed.get("latest_candidate_feed_buy_ready") or 0),
            "user_app_market_data_stale": bool(feed.get("latest_candidate_feed_market_data_stale")),
            "user_app_public_feed_exception_type": str(feed.get("latest_public_feed_exception_type") or user_profile.get("exception_type") or ""),
            "user_app_public_feed_exception_message_sanitized": str(user_profile.get("exception_message_sanitized") or "")[:220],
            "user_app_last_ok_age_sec": int(feed.get("market_feed_last_ok_age_sec") or -1),
            "user_app_market_feed_blocker": str(feed.get("market_feed_blocker") or user_profile.get("market_feed_blocker") or ""),
            "user_app_market_feed_reason": str(feed.get("market_feed_reason") or user_profile.get("market_feed_reason") or ""),
            "harness_process_network_ok": harness_ok,
            "observed_app_process_network_ok": observed_app_ok,
            "external_public_read_network_ok": external_ok,
            "profile_split_result": split_result,
            "runtime_network_profile_split_detected": bool(user_ok and not harness_ok),
            "market_feed_user_app_ok": user_ok,
            "next_fix_target": next_fix,
            "actual_order": False,
            "submitted_count": 0,
            "order_allowed": False,
            "real_order": False,
            "provider_external_call_count": 0,
            "order_risk_detected": False,
            "pass_status": "pass",
            "status": "pass",
        }
    )


def _run_public_market_feed_network_profile_proof(report: dict[str, Any], *, output_dir: Path, max_markets: int = 20) -> None:
    profiles: list[dict[str, Any]] = []
    feed_report: dict[str, Any] = {}
    _run_top_markets_feed_proof(feed_report, max_markets=max_markets)
    harness_profile = _market_feed_profile_from_feed_report(
        "harness_process",
        feed_report,
        python_executable=sys.executable,
        cwd=str(Path.cwd()),
        frozen=bool(getattr(sys, "frozen", False)),
    )
    profiles.append(harness_profile)
    profiles.append(dict(harness_profile, profile_name="direct_service_call"))

    lines, log_path, log_read_error = _live_on_runtime_e2e_tail_log()
    provenance_lines = [line for line in lines if "[AITS][RuntimeProvenance]" in line]
    latest_provenance = provenance_lines[-1] if provenance_lines else ""
    session_started_at_dt = _runtime_provenance_line_ts(latest_provenance)
    if session_started_at_dt is not None:
        lines = [
            line for line in lines
            if (_runtime_provenance_line_ts(line) is None or _runtime_provenance_line_ts(line) >= session_started_at_dt)
        ]
    app_profile = _market_feed_profile_from_runtime_logs("app_process", lines)
    profiles.append(app_profile)
    profiles.append(dict(app_profile, profile_name="existing_app_runtime_log"))

    reports = _live_on_runtime_e2e_latest_reports(output_dir)
    latest_public = _live_on_runtime_e2e_latest_report_by_mode(reports, "public-market-feed-diagnostic")
    if latest_public:
        profiles.append(_market_feed_profile_from_feed_report("latest_public_market_diagnostic_report", latest_public))
    latest_public_ok = next(
        (
            r for r in reports
            if r.get("mode") == "public-market-feed-diagnostic" and int(r.get("top_markets_count") or 0) > 0
        ),
        {},
    )
    if latest_public_ok:
        profiles.append(_market_feed_profile_from_feed_report("escalated_public_read_or_external_profile", latest_public_ok))

    harness_ok = bool(harness_profile.get("network_ok"))
    app_ok = bool(app_profile.get("network_ok"))
    external_ok = any(
        p.get("profile_name") in {"escalated_public_read_or_external_profile", "latest_public_market_diagnostic_report"}
        and p.get("network_ok")
        for p in profiles
    )
    split_detected = bool((not harness_ok) and app_ok)
    if split_detected:
        root_cause = "harness_or_sandbox_network_restricted"
        next_fix = "use_app_process_feed_status_for_runtime_or_run_e2e_in_app_profile"
    elif (not harness_ok) and (not app_ok) and external_ok:
        root_cause = "harness_and_observed_app_profile_restricted_external_public_read_ok"
        next_fix = "run_e2e_in_real_app_network_profile_or_fix_app_process_network_permission"
    elif harness_ok or app_ok:
        root_cause = "public_feed_available"
        next_fix = "continue_to_balance_or_candidate_gate"
    else:
        root_cause = "public_feed_unavailable_in_observed_profiles"
        next_fix = "inspect_public_feed_network_or_firewall"

    report.update(
        {
            "schema": "aits_public_market_feed_network_profile_proof_v1",
            "diagnostic_status": "pass",
            "profiles": profiles,
            "profile_count": len(profiles),
            "harness_process_network_ok": harness_ok,
            "app_process_network_ok": app_ok,
            "external_public_read_network_ok": external_ok,
            "runtime_network_profile_split_detected": split_detected,
            "market_feed_app_process_ok": app_ok,
            "log_path": log_path,
            "log_read_error": log_read_error,
            "root_cause": root_cause,
            "next_fix_target": next_fix,
            "actual_order": False,
            "submitted_count": 0,
            "order_allowed": False,
            "real_order": False,
            "provider_external_call_count": 0,
            "order_risk_detected": False,
            "pass_status": "pass",
        }
    )


def _analyze_live_on_market_feed_readiness(lines: list[str]) -> dict[str, Any]:
    runtime_line = _aits_latest_line_with(lines, "[aits][runtimefeedreadiness]")
    public_top_line = _aits_latest_line_with(lines, "[aits][publicmarketfeed]", "event=top_markets_result")
    public_ticker_line = _aits_latest_line_with(lines, "[aits][publicmarketfeed]", "event=tickers_result")
    recovery_line = _aits_latest_line_with(lines, "[aits][networkrecovery]", "candidate_refresh_rendered")
    degraded_line = _aits_latest_line_with(lines, "[aits][networkrecovery]", "candidate_refresh_incomplete")
    score_line = ""
    for line in reversed(lines):
        low = line.lower()
        if "candidatefeedstate" in low and "event=score_update" in low:
            score_line = line
            break
        if "ai score update" in low:
            score_line = line
            break
    top_line = _aits_latest_line_with(lines, "top_markets_return")
    ticker_line = _aits_latest_line_with(lines, "tickers_return")
    network_line = _aits_latest_line_with(lines, "[aits][networkstate]")

    runtime_ok = _aits_extract_kv_bool(runtime_line, "market_feed_ok", False) if runtime_line else False
    score_total = _aits_extract_kv_int(runtime_line, "score_update_total", 0) if runtime_line else 0
    if score_total <= 0:
        score_total = _aits_extract_kv_int(score_line, "total", 0)
    buy_ready = _aits_extract_kv_int(runtime_line, "buy_ready_count", 0) if runtime_line else 0
    if buy_ready <= 0:
        buy_ready = _aits_extract_kv_int(score_line, "buy_ready", 0)
    top_count = _aits_extract_kv_int(runtime_line, "top_markets_count", 0) if runtime_line else 0
    if top_count <= 0:
        top_count = _aits_extract_kv_int(top_line, "count", 0)
    if top_count <= 0:
        top_count = _aits_extract_kv_int(public_top_line, "response_count", 0)
    ticker_count = _aits_extract_kv_int(runtime_line, "tickers_count", 0) if runtime_line else 0
    if ticker_count <= 0:
        ticker_count = _aits_extract_kv_int(ticker_line, "count", 0)
    if ticker_count <= 0:
        ticker_count = _aits_extract_kv_int(public_ticker_line, "response_count", 0)

    stale = _aits_extract_kv_bool(runtime_line, "market_data_stale", False) if runtime_line else False
    if score_line:
        stale = _aits_extract_kv_bool(score_line, "market_data_stale", stale)
    network_status = _aits_extract_kv_text(runtime_line, "network_status") if runtime_line else ""
    if not network_status:
        network_status = _aits_extract_kv_text(network_line, "status")
    last_ok_age = _aits_extract_kv_int(runtime_line, "last_ok_age_sec", -1) if runtime_line else -1
    reason = _aits_extract_kv_text(runtime_line, "reason") if runtime_line else ""
    if not reason:
        reason = _aits_extract_kv_text(public_top_line, "empty_reason") or _aits_extract_kv_text(public_ticker_line, "empty_reason")
    exception_type = _aits_extract_kv_text(public_top_line, "exception_type") or _aits_extract_kv_text(public_ticker_line, "exception_type")
    public_network = _aits_extract_kv_text(public_top_line, "network_status") or _aits_extract_kv_text(public_ticker_line, "network_status")
    if not network_status and public_network:
        network_status = public_network
    recovery_seen = bool(recovery_line)
    degraded_seen = bool(degraded_line or (public_top_line and _aits_extract_kv_int(public_top_line, "response_count", 0) <= 0))

    source = "runtime_feed_readiness" if runtime_line else ""
    market_ok = False
    if runtime_line:
        market_ok = bool(runtime_ok)
    if not market_ok and score_total > 0 and not stale:
        market_ok = True
        source = source or "candidate_score_update"
        reason = reason or "score_update_ready"
    if not market_ok and (top_count > 0 or ticker_count > 0) and not stale:
        market_ok = True
        source = source or "market_feed_counts"
        reason = reason or "feed_count_ready"
    if not market_ok and recovery_seen and score_total > 0 and not stale:
        market_ok = True
        source = source or "network_recovery"
        reason = reason or "feed_recovered"

    if not source:
        source = "public_market_feed" if (public_top_line or public_ticker_line) else "log_summary"
    if not reason:
        if exception_type:
            reason = "network_exception"
        elif stale:
            reason = "market_data_stale"
        elif ticker_line and ticker_count <= 0:
            reason = "ticker_empty"
        elif top_line and top_count <= 0:
            reason = "top_markets_empty"
        elif network_status in {"degraded", "disconnected"}:
            reason = "network_degraded"
        else:
            reason = "market_feed_snapshot_missing"

    if market_ok:
        blocker = ""
    elif exception_type or reason in {"exception", "network_exception"}:
        blocker = "market_feed_network_error"
    elif reason in {"ticker_empty", "top_markets_empty"}:
        blocker = "market_feed_ticker_empty" if reason == "ticker_empty" else "market_feed_top_markets_empty"
    elif reason in {"network_degraded", "market_data_stale"} or network_status in {"degraded", "disconnected"}:
        blocker = "market_feed_degraded"
    elif runtime_line or score_line or top_line or ticker_line or network_line:
        blocker = "market_feed_not_ready"
    else:
        blocker = "market_feed_snapshot_missing"

    return {
        "market_feed_ok": bool(market_ok),
        "market_feed_source": source,
        "market_feed_reason": reason,
        "market_feed_blocker": blocker,
        "latest_candidate_feed_total": int(score_total or 0),
        "latest_candidate_feed_buy_ready": int(buy_ready or 0),
        "latest_candidate_feed_market_data_stale": bool(stale),
        "latest_top_markets_count": int(top_count or 0),
        "latest_tickers_count": int(ticker_count or 0),
        "latest_network_status": network_status or "unknown",
        "market_feed_last_ok_age_sec": int(last_ok_age),
        "latest_runtime_feed_line": runtime_line,
        "latest_feed_recovery_seen": bool(recovery_seen),
        "latest_feed_degraded_seen": bool(degraded_seen),
        "latest_public_feed_exception_type": exception_type,
    }


def _analyze_live_on_balance_gate(lines: list[str]) -> dict[str, Any]:
    balance_line = _aits_latest_line_with(lines, "[aits][krwbalancesource]")
    preflight_line = _aits_latest_line_with(lines, "[aits][liveonpreflight]")
    on_preflight_line = ""
    for line in reversed(lines):
        low = line.lower()
        if "[aits][on]" in low and "event=preflight_result" in low and "status=fail" in low:
            on_preflight_line = line
            break
    detected = bool(balance_line or preflight_line or on_preflight_line)
    available = _aits_extract_kv_int(balance_line, "available_krw", _aits_extract_kv_int(preflight_line, "available_krw", 0))
    effective = _aits_extract_kv_int(preflight_line, "effective_hard_cap_krw", 0)
    hard_cap = _aits_extract_kv_int(preflight_line, "hard_cap_krw", 0)
    window_cap = _aits_extract_kv_int(preflight_line, "total_guarded_window_cap_krw", 0)
    order_amount = _aits_extract_kv_int(preflight_line, "configured_order_amount_krw", 0)
    if available <= 0 and on_preflight_line:
        match = re.search(r"(?:available_krw=|KRW\s*)([0-9,]+)", on_preflight_line, flags=re.IGNORECASE)
        if match:
            available = int(str(match.group(1)).replace(",", "") or 0)
    if order_amount <= 0 and on_preflight_line:
        match = re.search(r"(?:configured_order_amount_krw=|order\s*)([0-9,]+)|(?:1[^0-9]*)([0-9,]+)", on_preflight_line, flags=re.IGNORECASE)
        if match:
            order_amount = int(str(match.group(1) or match.group(2) or "0").replace(",", "") or 0)
    fallback_used = _aits_extract_kv_bool(balance_line, "fallback_used", False)
    balance_status = _aits_extract_kv_text(balance_line, "balance_status")
    blocker = _aits_extract_kv_text(balance_line, "blocker") or _aits_extract_kv_text(preflight_line, "blocker")
    if not blocker and on_preflight_line and available <= 0:
        blocker = "insufficient_available_krw"
    return {
        "balance_gate_detected": detected,
        "available_krw": available,
        "available_krw_source": _aits_extract_kv_text(balance_line, "balance_source") or _aits_extract_kv_text(preflight_line, "balance_source"),
        "accounts_fetch_status": balance_status,
        "accounts_response_shape": _aits_extract_kv_text(balance_line, "response_shape"),
        "balance_fallback_used": fallback_used,
        "balance_fallback_reason": _aits_extract_kv_text(balance_line, "fallback_reason"),
        "order_amount_krw": order_amount,
        "per_order_hard_cap_krw": hard_cap,
        "total_guarded_window_cap_krw": window_cap,
        "effective_cap_krw": effective,
        "balance_gate_blocker": blocker,
        "latest_balance_gate_line": balance_line,
        "latest_balance_preflight_line": preflight_line or on_preflight_line,
    }

def _live_on_runtime_e2e_latest_reports(output_dir: Path) -> list[dict[str, Any]]:
    try:
        paths = sorted(output_dir.glob("runtime_smoke_report_*.json"), key=lambda p: p.stat().st_mtime, reverse=True)
    except Exception:
        paths = []
    reports: list[dict[str, Any]] = []
    for path in paths[:80]:
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if isinstance(data, dict):
            data["_report_path"] = str(path)
            reports.append(data)
    return reports


def _live_on_runtime_e2e_latest_report_by_mode(reports: list[dict[str, Any]], mode: str) -> dict[str, Any]:
    for report in reports:
        if report.get("mode") == mode:
            return report
    return {}


def _live_on_runtime_e2e_extract_symbol(line: str) -> str:
    for pattern in (
        r"symbol[=:]\s*(KRW-[A-Z0-9]+)",
        r"target_symbol[=:]\s*(KRW-[A-Z0-9]+)",
        r"candidate_symbol[=:]\s*(KRW-[A-Z0-9]+)",
        r"\b(KRW-[A-Z0-9]+)\b",
    ):
        match = re.search(pattern, line)
        if match:
            return _normalize_symbol_text(match.group(1))
    return ""


def _live_on_runtime_e2e_extract_amount(line: str) -> int:
    for pattern in (
        r"amount_krw[=:]\s*([0-9]+)",
        r"intended_amount_krw[=:]\s*([0-9]+)",
        r"configured_order_amount_krw[=:]\s*([0-9]+)",
        r"price[=:]\s*([0-9]+)",
    ):
        match = re.search(pattern, line)
        if match:
            try:
                return int(match.group(1))
            except Exception:
                return 0
    return 0


def _live_on_runtime_e2e_extract_side(line: str) -> str:
    match = re.search(r"\bside[=:]\s*([A-Za-z_]+)", line)
    return str(match.group(1)).strip().lower() if match else ""


def _live_on_runtime_bool_marker(line: str, key: str) -> bool:
    return bool(re.search(rf"\b{re.escape(key)}[=:]\s*(?:True|true|1)\b", line))


