def _run_live_on_preflight_krw_balance_source_summary(report: dict[str, Any]) -> None:
    lines, log_path, log_read_error = _live_on_runtime_e2e_tail_log(max_chars=1_200_000)
    balance_lines = [line for line in lines if "[AITS][KRWBalanceSource]" in line]
    account_result_lines = [
        line
        for line in lines
        if "[AITS][UpbitAccounts]" in line and "event=accounts_fetch_result" in line
    ]
    account_lines = [
        line
        for line in lines
        if "[AITS][OrderService] fetch_accounts called" in line
        or line in account_result_lines
    ]
    preflight_lines = [line for line in lines if "[AITS][LiveOnPreflight]" in line or "[PREFLIGHT]" in line]
    latest_balance = balance_lines[-1] if balance_lines else (account_result_lines[-1] if account_result_lines else (account_lines[-1] if account_lines else ""))
    latest_preflight = preflight_lines[-1] if preflight_lines else ""

    def _extract_text(line: str, key: str) -> str:
        if not line:
            return ""
        match = re.search(rf"(?:^|[|\s]){re.escape(key)}=([^|\s]+)", line)
        return str(match.group(1)).strip() if match else ""

    def _extract_int(line: str, key: str) -> int:
        raw = _extract_text(line, key)
        try:
            return int(float(raw))
        except Exception:
            return 0

    def _extract_bool(line: str, key: str) -> bool:
        return _extract_text(line, key).lower() in {"1", "true", "yes", "ok"}

    available_krw = _extract_int(latest_balance, "available_krw")
    balance_status = _extract_text(latest_balance, "balance_status") or "balance_not_loaded"
    if "fetch_accounts called" in latest_balance:
        balance_status = _extract_text(latest_balance, "status") or balance_status
    elif "accounts_fetch_result" in latest_balance:
        balance_status = _extract_text(latest_balance, "status") or balance_status
    balance_source = _extract_text(latest_balance, "balance_source") or "svc_order.compute_available_krw_snapshot"
    if "fetch_accounts called" in latest_balance:
        balance_source = "svc_order.fetch_accounts"
    fallback_reason = _extract_text(latest_balance, "fallback_reason")
    blocker = _extract_text(latest_balance, "blocker")
    if not blocker and latest_preflight:
        match = re.search(r"blocker[=:]\s*([A-Za-z0-9_\\-]+)", latest_preflight)
        blocker = "" if not match or match.group(1) == "-" else match.group(1)

    suspected = "balance_log_not_found"
    if latest_balance:
        if balance_status == "private_api_not_connected":
            suspected = "upbit_private_api_not_connected"
        elif balance_status == "balance_fetch_failed":
            suspected = "upbit_balance_fetch_failed"
        elif balance_status == "actual_krw_balance_zero":
            suspected = "actual_krw_balance_zero"
        elif balance_status == "ok":
            suspected = "balance_source_ok"
        else:
            suspected = balance_status or "unknown_balance_source"

    next_fix = {
        "private_api_not_connected": "verify_upbit_private_api_key_settings",
        "balance_fetch_failed": "inspect_upbit_accounts_read_failure",
        "accounts_response_empty": "verify_actual_accounts_response_or_run_explicit_readonly_accounts_diagnostic",
        "krw_balance_missing_from_accounts": "verify_upbit_accounts_krw_row",
        "upbit_response_parse_error": "inspect_upbit_accounts_response_parser",
        "upbit_http_401_unauthorized": "verify_upbit_key_validity_and_permissions",
        "upbit_http_403_forbidden": "verify_upbit_accounts_permission_or_ip_allowlist",
        "upbit_timeout": "inspect_network_timeout_or_upbit_availability",
        "upbit_network_error": "inspect_network_dns_ssl_firewall",
        "balance_not_loaded": "trigger_or_verify_readonly_balance_refresh_before_on_preflight",
        "actual_krw_balance_zero": "fund_krw_or_lower_test_until_min_order_policy_allows",
        "balance_cache_stale": "refresh_balance_cache_before_on_preflight",
    }.get(balance_status, "rerun_on_click_and_collect_krw_balance_source_log")

    report.update(
        {
            "schema": "aits_live_on_preflight_krw_balance_source_summary_v1",
            "diagnostic_status": "pass",
            "pass_status": "pass",
            "report_status": "pass",
            "log_path": log_path,
            "log_read_error": log_read_error,
            "preflight_popup_detected": bool(preflight_lines),
            "krw_balance_source_line_count": len(balance_lines),
            "account_fetch_trace_line_count": len(account_lines),
            "latest_balance_source_line": latest_balance,
            "latest_preflight_line": latest_preflight,
            "available_krw": available_krw,
            "balance_status": balance_status,
            "balance_source": balance_source,
            "balance_cache_present": _extract_bool(latest_balance, "balance_cache_present"),
            "balance_cache_age_sec": _extract_int(latest_balance, "balance_cache_age_sec"),
            "balance_fetch_attempted": bool(latest_balance),
            "balance_fetch_success": _extract_bool(latest_balance, "balance_fetch_success") or _extract_bool(latest_balance, "success"),
            "balance_fetch_error_type": _extract_text(latest_balance, "balance_fetch_error_type") or _extract_text(latest_balance, "error_type"),
            "upbit_private_connected": _extract_bool(latest_balance, "upbit_private_connected") or _extract_bool(latest_balance, "success"),
            "account_service_ready": bool(latest_balance),
            "fallback_used": _extract_bool(latest_balance, "fallback_used") or _extract_bool(latest_balance, "default_used"),
            "fallback_reason": fallback_reason,
            "first_blocker": blocker or balance_status,
            "suspected_root_cause": suspected,
            "next_fix_target": next_fix,
            "safety_flags": {
                "actual_order": False,
                "submitted_count": 0,
                "provider_external_call_count": 0,
            },
            "provider_external_call_count": 0,
            "submitted_count": 0,
            "order_risk_detected": False,
        }
    )


def _run_upbit_accounts_readonly_krw_parse_proof(report: dict[str, Any]) -> None:
    from app.services.order_service import (
        classify_upbit_accounts_http_failure,
        parse_upbit_accounts_krw_snapshot,
    )

    scenarios = [
        (
            "krw_balance_15000_locked_0",
            [{"currency": "KRW", "balance": "15000", "locked": "0"}],
            {"status": "ok"},
            {"balance_status": "ok", "available_krw": 15000.0, "krw_row_found": True},
        ),
        (
            "krw_balance_15000_locked_5000",
            [{"currency": "KRW", "balance": "15000", "locked": "5000"}],
            {"status": "ok"},
            {"balance_status": "ok", "available_krw": 10000.0, "krw_row_found": True},
        ),
        (
            "krw_row_missing",
            [{"currency": "BTC", "balance": "1", "locked": "0"}],
            {"status": "ok"},
            {"balance_status": "krw_balance_missing_from_accounts", "available_krw": 0.0, "krw_row_found": False},
        ),
        (
            "invalid_numeric_balance",
            [{"currency": "KRW", "balance": "not-a-number", "locked": "0"}],
            {"status": "ok"},
            {"balance_status": "upbit_response_parse_error", "available_krw": 0.0, "krw_row_found": True},
        ),
        (
            "empty_accounts_response",
            [],
            {"status": "ok"},
            {"balance_status": "accounts_response_empty", "available_krw": 0.0, "krw_row_found": False},
        ),
    ]
    results: list[dict[str, Any]] = []
    for name, rows, trace, expected in scenarios:
        parsed = parse_upbit_accounts_krw_snapshot(rows, trace)
        passed = True
        for key, value in expected.items():
            if key == "available_krw":
                passed = passed and abs(float(parsed.get(key) or 0.0) - float(value)) < 0.0001
            else:
                passed = passed and parsed.get(key) == value
        results.append(
            {
                "name": name,
                "passed": bool(passed),
                "expected": expected,
                "actual": parsed,
            }
        )

    http_results = [
        {
            "name": "http_401_mock",
            "passed": classify_upbit_accounts_http_failure(401) == "upbit_http_401_unauthorized",
            "actual": classify_upbit_accounts_http_failure(401),
        },
        {
            "name": "http_403_mock",
            "passed": classify_upbit_accounts_http_failure(403) == "upbit_http_403_forbidden",
            "actual": classify_upbit_accounts_http_failure(403),
        },
    ]
    results.extend(http_results)
    pass_count = sum(1 for item in results if item.get("passed"))
    fail_count = len(results) - pass_count
    report.update(
        {
            "schema": "aits_upbit_accounts_readonly_krw_parse_proof_v1",
            "diagnostic_status": "pass" if fail_count == 0 else "fail",
            "pass_status": "pass" if fail_count == 0 else "fail",
            "status": "pass" if fail_count == 0 else "fail",
            "report_status": "pass" if fail_count == 0 else "fail",
            "fixture_pass_count": pass_count,
            "fixture_fail_count": fail_count,
            "fixture_results": results,
            "provider_external_call_count": 0,
            "order_submit_count": 0,
            "private_order_call_count": 0,
            "submitted_count": 0,
            "actual_order": False,
            "order_risk_detected": False,
            "safety_flags": {
                "actual_order": False,
                "submitted_count": 0,
                "provider_external_call_count": 0,
                "private_order_call_count": 0,
            },
        }
    )


def _run_upbit_accounts_readonly_balance_fetch_diagnostic(
    report: dict[str, Any],
    *,
    allow_upbit_readonly_accounts_call: bool = False,
) -> None:
    from app.services.order_service import svc_order

    settings = None
    settings_error = ""
    try:
        from app.utils.prefs import load_settings

        settings = load_settings()
    except Exception as exc:
        settings_error = f"{type(exc).__name__}: {exc}"
    try:
        if settings is not None:
            svc_order.set_settings(settings)
    except Exception:
        pass

    access_key = ""
    secret_key = ""
    key_error = ""
    try:
        access_key, secret_key = svc_order._extract_upbit_keys()
    except Exception as exc:
        key_error = type(exc).__name__
    access_present = bool(access_key and len(str(access_key)) >= 10)
    secret_present = bool(secret_key and len(str(secret_key)) >= 10)
    key_fp = ""
    if access_present and secret_present:
        key_fp = hashlib.sha256(f"{access_key}:{secret_key}".encode("utf-8")).hexdigest()[:8]

    jwt_build_attempted = False
    jwt_build_success = False
    authorization_header_present = False
    jwt_error_type = ""
    if access_present and secret_present:
        jwt_build_attempted = True
        try:
            headers = svc_order._make_auth_headers({})
            jwt_build_success = True
            authorization_header_present = bool(headers.get("Authorization"))
        except Exception as exc:
            jwt_error_type = type(exc).__name__

    accounts_fetch_attempted = False
    rows: list[Any] = []
    if allow_upbit_readonly_accounts_call:
        accounts_fetch_attempted = True
        rows = svc_order.fetch_accounts()
        trace = svc_order.get_last_accounts_fetch_trace()
    else:
        trace = {
            "status": "readonly_accounts_call_not_allowed",
            "error_type": "readonly_accounts_call_not_allowed",
            "access_key_present": access_present,
            "secret_key_present": secret_present,
            "key_present": access_present and secret_present,
            "upbit_key_fp": key_fp,
            "jwt_build_attempted": jwt_build_attempted,
            "jwt_build_success": jwt_build_success,
            "authorization_header_present": authorization_header_present,
            "http_status": None,
            "response_shape": "not_called",
            "default_used": True,
            "fallback_reason": "readonly_accounts_call_not_allowed",
        }

    failure_type = str(trace.get("error_type") or trace.get("status") or "")
    if key_error:
        failure_type = f"key_resolution_error:{key_error}"
    elif not access_present:
        failure_type = "upbit_access_key_missing"
    elif not secret_present:
        failure_type = "upbit_secret_key_missing"
    elif jwt_build_attempted and not jwt_build_success:
        failure_type = "upbit_jwt_generation_failed"
    elif not allow_upbit_readonly_accounts_call:
        failure_type = "readonly_accounts_call_not_allowed"

    first_blocker = ""
    if failure_type and failure_type != "ok":
        first_blocker = failure_type
    elif not bool(trace.get("krw_row_found")):
        first_blocker = "krw_balance_missing_from_accounts"
    elif float(trace.get("available_krw") or 0.0) <= 0:
        first_blocker = str(trace.get("balance_status") or "actual_krw_balance_zero")

    next_fix = {
        "upbit_access_key_missing": "verify_upbit_access_key_storage",
        "upbit_secret_key_missing": "verify_upbit_secret_key_storage",
        "upbit_jwt_generation_failed": "inspect_upbit_jwt_generation",
        "upbit_http_401_unauthorized": "verify_upbit_key_validity_and_permissions",
        "upbit_http_403_forbidden": "verify_upbit_accounts_permission_or_ip_allowlist",
        "upbit_http_429_rate_limited": "retry_after_rate_limit_window",
        "upbit_network_error": "inspect_network_dns_ssl_firewall",
        "upbit_timeout": "inspect_network_timeout_or_upbit_availability",
        "readonly_accounts_call_not_allowed": "rerun_with_explicit_readonly_accounts_permission_if_needed",
    }.get(first_blocker, "inspect_upbit_accounts_read_failure")

    report.update(
        {
            "schema": "aits_upbit_accounts_readonly_balance_fetch_diagnostic_v1",
            "diagnostic_status": "pass",
            "pass_status": "pass",
            "status": "pass",
            "report_status": "pass",
            "settings_error": settings_error,
            "accounts_fetch_attempted": accounts_fetch_attempted,
            "accounts_fetch_success": bool(trace.get("success")),
            "accounts_fetch_failure_type": failure_type,
            "access_key_present": access_present,
            "secret_key_present": secret_present,
            "upbit_key_fp": key_fp,
            "jwt_build_attempted": jwt_build_attempted,
            "jwt_build_success": jwt_build_success,
            "authorization_header_present": authorization_header_present,
            "jwt_error_type": jwt_error_type,
            "http_status": trace.get("http_status"),
            "response_shape": str(trace.get("response_shape") or ""),
            "krw_row_found": bool(trace.get("krw_row_found")),
            "krw_balance_raw_present": bool(trace.get("krw_balance_raw_present")),
            "krw_locked_raw_present": bool(trace.get("krw_locked_raw_present")),
            "available_krw": float(trace.get("available_krw") or 0.0),
            "balance_status": str(trace.get("balance_status") or trace.get("status") or ""),
            "fallback_used": bool(trace.get("default_used")),
            "fallback_reason": str(trace.get("fallback_reason") or ""),
            "first_blocker": first_blocker,
            "suspected_root_cause": first_blocker or "accounts_read_path_ok",
            "next_fix_target": next_fix,
            "actual_readonly_accounts_call_executed": bool(allow_upbit_readonly_accounts_call),
            "returned_row_count": len(rows) if isinstance(rows, list) else 0,
            "provider_external_call_count": 0,
            "order_submit_count": 0,
            "private_order_call_count": 0,
            "submitted_count": 0,
            "actual_order": False,
            "order_risk_detected": False,
            "safety_flags": {
                "actual_order": False,
                "submitted_count": 0,
                "provider_external_call_count": 0,
                "private_order_call_count": 0,
            },
        }
    )


def _fixture_result(name: str, passed: bool, plan: dict[str, Any], detail: str = "") -> dict[str, Any]:
    return {
        "name": name,
        "passed": bool(passed),
        "detail": detail,
        "planned_add_count": len(plan.get("planned_add") or []),
        "planned_remove_count": len(plan.get("planned_remove") or []),
        "planned_rotation_count": len(plan.get("planned_rotation") or []),
        "pool_size_after": plan.get("pool_size_after"),
        "protected_violation": bool(plan.get("protected_violation")),
    }


def _run_managed_pool_promotion_policy_proof(
    report: dict[str, Any],
    *,
    output_dir: Path,
    max_managed: int = 10,
) -> None:
    from app.services.managed_pool_promotion_policy import build_managed_pool_promotion_plan

    config = {
        "max_managed_pool_size": int(max_managed or 10),
        "promotion_min_score": 60.0,
        "promotion_min_trade_value_krw": None,
        "quality_gate_enabled": True,
        "fill_to_max": False,
        "auto_add_enabled": True,
        "auto_remove_enabled": True,
        "protect_user_added": True,
        "protect_holdings_until_liquidated": True,
        "protect_system_seed_initially": True,
        "rotation_enabled": True,
        "rotation_min_score_gap": 0.0,
        "order_execution_enabled": False,
    }

    def plan(rows: list[dict[str, Any]], candidates: list[dict[str, Any]], holdings: list[dict[str, Any]] | None = None) -> dict[str, Any]:
        return build_managed_pool_promotion_plan(rows, candidates, holdings or [], config)

    fixtures: list[dict[str, Any]] = []

    p1 = plan(
        [{"symbol": "KRW-BTC", "source_type": "system_seed", "score": 54}],
        [{"symbol": "KRW-AAA", "rank": 1, "score": 70}, {"symbol": "KRW-BBB", "rank": 2, "score": 68}],
    )
    fixtures.append(_fixture_result("pool_under_10_auto_add", len(p1["planned_add"]) == 2 and p1["pool_size_after"] == 3, p1))

    p2 = plan(
        [{"symbol": "KRW-USER", "source_type": "user_added", "score": 10}]
        + [{"symbol": f"KRW-B{i}", "source_type": "basic_added", "score": 20 + i} for i in range(10)],
        [{"symbol": "KRW-NEW", "rank": 1, "score": 99}],
    )
    fixtures.append(
        _fixture_result(
            "user_added_protected_from_remove",
            all(item.get("symbol") != "KRW-USER" for item in p2["planned_remove"]) and not p2["protected_violation"],
            p2,
        )
    )

    p3 = plan(
        [{"symbol": "KRW-HOLD", "source_type": "basic_added", "score": 30, "holding": True}]
        + [{"symbol": f"KRW-C{i}", "source_type": "basic_added", "score": 40 + i} for i in range(10)],
        [{"symbol": "KRW-NEW", "rank": 1, "score": 90}],
        [{"symbol": "KRW-HOLD", "qty": 1.0}],
    )
    fixtures.append(
        _fixture_result(
            "holding_protected_until_liquidated",
            all(item.get("symbol") != "KRW-HOLD" for item in p3["planned_remove"]) and not p3["protected_violation"],
            p3,
        )
    )

    p4 = plan(
        [{"symbol": f"KRW-D{i}", "source_type": "basic_added", "score": 40 + i} for i in range(10)],
        [{"symbol": "KRW-HIGH", "rank": 1, "score": 80}],
    )
    fixtures.append(
        _fixture_result(
            "basic_added_low_rank_remove_candidate",
            any(item.get("symbol") == "KRW-D0" for item in p4["planned_remove"]),
            p4,
        )
    )

    p5 = plan(
        [{"symbol": f"KRW-E{i}", "source_type": "basic_added", "score": 50 + i} for i in range(10)],
        [{"symbol": "KRW-HIGH", "rank": 1, "score": 90}],
    )
    fixtures.append(
        _fixture_result(
            "pool_max_10_enforced",
            int(p5.get("pool_size_after_capped") or 0) <= int(max_managed or 10),
            p5,
        )
    )

    p6 = plan(
        [{"symbol": "KRW-HOLD", "source_type": "basic_added", "score": 60, "holding": True}],
        [{"symbol": "KRW-ROTIN", "rank": 1, "score": 70}],
        [{"symbol": "KRW-HOLD", "qty": 1.0}],
    )
    fixtures.append(
        _fixture_result(
            "rotation_holding_60_candidate_70",
            bool(p6["planned_rotation"])
            and p6["planned_rotation"][0].get("rotate_out") == "KRW-HOLD"
            and p6["planned_rotation"][0].get("rotate_in") == "KRW-ROTIN"
            and p6["planned_rotation"][0].get("actual_order") is False,
            p6,
        )
    )

    p7 = plan(
        [{"symbol": "KRW-HOLD", "source_type": "basic_added", "score": 70, "holding": True}],
        [{"symbol": "KRW-LOW", "rank": 1, "score": 60}],
        [{"symbol": "KRW-HOLD", "qty": 1.0}],
    )
    fixtures.append(_fixture_result("candidate_below_existing_no_rotation", not p7["planned_rotation"], p7))

    p8 = plan(
        [{"symbol": "KRW-BTC", "source_type": "system_seed", "score": 54}],
        [{"symbol": "KRW-BTC", "rank": 1, "score": 99}, {"symbol": "KRW-DUP", "rank": 2, "score": 80}],
    )
    fixtures.append(
        _fixture_result(
            "duplicate_candidate_ignored",
            all(item.get("symbol") != "KRW-BTC" for item in p8["planned_add"])
            and any(item.get("symbol") == "KRW-DUP" for item in p8["planned_add"]),
            p8,
        )
    )

    latest = _latest_basic_candidate_report(output_dir)
    real_plan: dict[str, Any] = {}
    if latest:
        rows = [{"symbol": symbol, "source_type": "system_seed"} for symbol in latest.get("managed_pool_symbols_after") or []]
        real_plan = plan(rows, list(latest.get("top_candidates") or []), [])

    fixture_pass = all(item.get("passed") for item in fixtures)
    order_risk = any(
        bool(item.get("actual_order"))
        for item in (real_plan.get("planned_add") or [])
        + (real_plan.get("planned_remove") or [])
        + (real_plan.get("planned_rotation") or [])
    )
    report.update(
        {
            "policy_supported": True,
            "max_managed_pool_size": int(max_managed or 10),
            "auto_add_enabled": True,
            "auto_remove_enabled": True,
            "promotion_min_score": real_plan.get("promotion_min_score", 60.0),
            "quality_gate_enabled": real_plan.get("quality_gate_enabled", True),
            "fill_to_max": real_plan.get("fill_to_max", False),
            "protect_user_added": True,
            "protect_holdings_until_liquidated": True,
            "protect_system_seed_initially": True,
            "rotation_enabled": True,
            "rotation_min_score_gap": 0.0,
            "order_execution_enabled": False,
            "fixture_results": fixtures,
            "fixture_pass_count": sum(1 for item in fixtures if item.get("passed")),
            "fixture_total_count": len(fixtures),
            "actual_candidate_source_report": latest.get("_report_path", ""),
            "current_pool_size": real_plan.get("current_pool_size", 0),
            "candidate_count": real_plan.get("candidate_count", 0),
            "planned_add": real_plan.get("planned_add", []),
            "planned_remove": real_plan.get("planned_remove", []),
            "planned_keep": real_plan.get("planned_keep", []),
            "protected_rows": real_plan.get("protected_rows", []),
            "planned_rotation": real_plan.get("planned_rotation", []),
            "pool_size_after": real_plan.get("pool_size_after", 0),
            "actual_mutation_performed": False,
            "managed_pool_mutation_performed": False,
            "order_risk_detected": bool(order_risk),
            "place_order_call_count": 0,
            "cancel_call_count": 0,
            "sell_call_count": 0,
            "retry_call_count": 0,
            "provider_external_call_count": 0,
        }
    )
    report["pass_status"] = "pass" if fixture_pass and not order_risk and latest else "partial"


def _run_managed_pool_promotion_quality_gate_proof(
    report: dict[str, Any],
    *,
    max_managed: int = 10,
    min_score: float = 60.0,
) -> None:
    from app.services.managed_pool_promotion_policy import build_managed_pool_promotion_plan

    config = {
        "max_managed_pool_size": int(max_managed or 10),
        "promotion_min_score": float(min_score),
        "promotion_min_trade_value_krw": None,
        "quality_gate_enabled": True,
        "fill_to_max": False,
        "auto_add_enabled": True,
        "auto_remove_enabled": False,
        "protect_user_added": True,
        "protect_holdings_until_liquidated": True,
        "protect_system_seed_initially": True,
        "rotation_enabled": False,
        "rotation_min_score_gap": 0.0,
        "order_execution_enabled": False,
    }

    def plan(rows: list[dict[str, Any]], candidates: list[dict[str, Any]]) -> dict[str, Any]:
        return build_managed_pool_promotion_plan(rows, candidates, [], config)

    rows_8 = [{"symbol": f"KRW-M{i}", "source_type": "basic_added", "score": 50 + i} for i in range(8)]
    p1 = plan(
        rows_8,
        [
            {"symbol": "KRW-PASS1", "rank": 1, "score": 72, "trade_value": 100000000},
            {"symbol": "KRW-PASS2", "rank": 2, "score": 64, "trade_value": 90000000},
            {"symbol": "KRW-LOW1", "rank": 3, "score": 55, "trade_value": 80000000},
            {"symbol": "KRW-LOW2", "rank": 4, "score": 40, "trade_value": 70000000},
        ],
    )
    p2 = plan(rows_8, [{"symbol": "KRW-LOWA", "rank": 1, "score": 59}, {"symbol": "KRW-LOWB", "rank": 2, "score": 42}])
    p3 = plan(rows_8, [{"symbol": "KRW-RANK1LOW", "rank": 1, "score": 50}])
    p4 = plan(rows_8, [{"symbol": "KRW-M1", "rank": 1, "score": 99}, {"symbol": "KRW-NEW", "rank": 2, "score": 80}])

    fixtures = [
        _fixture_result("max_10_pass_2_adds_2_only", len(p1.get("planned_add") or []) == 2, p1),
        _fixture_result("max_10_pass_0_adds_0", len(p2.get("planned_add") or []) == 0, p2),
        _fixture_result(
            "high_rank_low_score_rejected",
            len(p3.get("planned_add") or []) == 0
            and any(item.get("symbol") == "KRW-RANK1LOW" for item in p3.get("rejected_candidates") or []),
            p3,
        ),
        _fixture_result(
            "already_managed_rejected",
            all(item.get("symbol") != "KRW-M1" for item in p4.get("planned_add") or [])
            and any(item.get("symbol") == "KRW-M1" for item in p4.get("rejected_candidates") or []),
            p4,
        ),
        _fixture_result("max_cap_applied_not_target", bool(p1.get("fill_to_max")) is False and len(p1.get("planned_add") or []) < int(max_managed or 10), p1),
        _fixture_result("fill_to_max_false", bool(p1.get("fill_to_max")) is False, p1),
    ]
    fixture_pass = all(item.get("passed") for item in fixtures)
    report.update(
        {
            "quality_gate_supported": True,
            "max_managed_pool_size": int(max_managed or 10),
            "fill_to_max": False,
            "promotion_min_score": float(min_score),
            "current_count": p1.get("current_pool_size", 0),
            "remaining_slots": p1.get("remaining_slots", 0),
            "candidate_count": p1.get("candidate_count", 0),
            "quality_pass_count": p1.get("quality_pass_count", 0),
            "quality_fail_count": p1.get("quality_fail_count", 0),
            "planned_add_count": len(p1.get("planned_add") or []),
            "planned_add": p1.get("planned_add", []),
            "rejected_candidates": p1.get("rejected_candidates", []),
            "rejection_reasons": p1.get("rejection_reasons", []),
            "score_distribution": p1.get("score_distribution", {}),
            "not_filled_reason": p1.get("not_filled_reason", ""),
            "fixture_results": fixtures,
            "fixture_pass_count": sum(1 for item in fixtures if item.get("passed")),
            "fixture_total_count": len(fixtures),
            "order_risk_detected": False,
            "provider_external_call_count": 0,
            "actual_mutation_performed": False,
            "managed_pool_mutation_performed": False,
            "pass_status": "pass" if fixture_pass else "fail",
        }
    )


