def _latest_journal_summary(window: Any) -> dict[str, Any]:
    getter = getattr(window, "_get_trade_log_shadow_journal_rows", None)
    rows: list[dict[str, Any]] = []
    if callable(getter):
        try:
            rows = [row for row in list(getter(limit=5) or []) if isinstance(row, dict)]
        except Exception:
            rows = []
    latest = rows[0] if rows else {}
    wanted = (
        "time",
        "symbol",
        "decision_group_id",
        "record_stage",
        "record_stage_label",
        "analysis_classification",
        "provider_selected",
        "provider_actual",
        "fallback_used",
        "fallback_reason_code",
        "fallback_reason_display",
        "http_status",
        "error_code",
        "usage_input_tokens",
        "usage_output_tokens",
        "usage_total_tokens",
    )
    return {
        "journal_rows_sample_count": len(rows),
        "latest_journal": {key: latest.get(key, "") for key in wanted},
    }


def _navigate(window: Any, widgets: dict[str, Any], report: dict[str, Any]) -> None:
    tab_order = [
        "managed_tab",
        "trade_log_tab",
        "investment_tab",
        "ai_policy_tab",
        "common_settings_tab",
    ]
    visited: list[dict[str, Any]] = []
    app = window.window().windowHandle()
    for index, key in enumerate(tab_order):
        widget = widgets.get(key)
        ok = False
        try:
            if widget is not None and hasattr(widget, "clicked"):
                widget.clicked.emit()
                ok = True
            else:
                tabs = getattr(window, "tabs", None)
                if tabs is not None:
                    tabs.setCurrentIndex(index)
                    ok = True
        except Exception as exc:
            visited.append({"target": key, "ok": False, "error": type(exc).__name__})
            continue
        try:
            qapp = widget.window().windowHandle() if widget is not None else app
            del qapp
        except Exception:
            pass
        visited.append({"target": key, "ok": ok})
    report["navigation"] = visited


def _table_cell_text(widget: Any, row: int, col: int) -> str:
    try:
        item = widget.item(row, col)
        return "" if item is None else str(item.text() or "").strip()
    except Exception:
        return ""


def _find_symbol_in_row(widget: Any, row: int, window: Any = None) -> str:
    if window is not None:
        try:
            rows = getattr(window, "ai_managed_rows", None)
            if isinstance(rows, list) and 0 <= row < len(rows):
                value = str((rows[row] or {}).get("symbol") or "").strip()
                if value:
                    return value
        except Exception:
            pass
        try:
            resolver = getattr(window, "_extract_ai_refresh_symbol_from_managed_row", None)
            rows = getattr(window, "ai_managed_rows", None)
            if callable(resolver) and isinstance(rows, list) and 0 <= row < len(rows):
                value = str(resolver(rows[row]) or "").strip()
                if value:
                    return value
        except Exception:
            pass
    try:
        cols = int(widget.columnCount())
    except Exception:
        return ""
    for col in range(cols):
        value = _table_cell_text(widget, row, col)
        if re.match(r"^[A-Z]+-[A-Z0-9]+$", value):
            return value
    return _table_cell_text(widget, row, 0)


def _safe_click(widget: Any) -> bool:
    if widget is None:
        return False
    try:
        if hasattr(widget, "click"):
            widget.click()
            return True
    except Exception:
        return False
    try:
        if hasattr(widget, "clicked"):
            widget.clicked.emit()
            return True
    except Exception:
        return False
    return False


def _select_provider(window: Any, provider: str, report: dict[str, Any]) -> bool:
    provider = provider.strip().lower()
    report["provider_selector"] = ""
    try:
        setattr(window, "_provider_user_selected", True)
    except Exception:
        pass
    try:
        sync_panel = getattr(window, "_sync_engine_choice_panel", None)
        if callable(sync_panel):
            engine_key = {"gpt": "openai", "gemini": "gemini", "local": "local"}[provider]
            sync_panel(
                engine_key,
                start_connection=False,
                select_session=True,
                reason="qt_smoke_provider_smoke",
            )
            report["provider_selector"] = "MainWindow._sync_engine_choice_panel(start_connection=False)"
            return True
    except Exception as exc:
        report["provider_select_error"] = type(exc).__name__
    try:
        selector = getattr(window, "_select_ai_provider_for_session", None)
        if callable(selector):
            selector(provider, reason="qt_smoke_provider_smoke", start_connection=False)
            report["provider_selector"] = "MainWindow._select_ai_provider_for_session(start_connection=False)"
            return True
    except Exception as exc:
        report["provider_select_error"] = type(exc).__name__
        return False
    attr_map = {
        "gpt": "btn_engine_openai",
        "gemini": "btn_engine_gemini",
        "local": "btn_engine_local",
    }
    button = getattr(window, attr_map.get(provider, ""), None)
    if _safe_click(button):
        report["provider_selector"] = attr_map.get(provider, "")
        return True
    return False


def _select_managed_row(widget: Any, target_symbol: str | None, report: dict[str, Any], window: Any = None) -> bool:
    if widget is None:
        report["target_select_error"] = "managed_table_missing"
        return False
    try:
        rows = int(widget.rowCount())
    except Exception:
        report["target_select_error"] = "managed_row_count_unreadable"
        return False
    if rows <= 0:
        report["target_select_error"] = "managed_table_empty"
        return False
    target = (target_symbol or "").strip().upper()
    selected_row = 0
    selected_symbol = ""
    for row in range(rows):
        symbol = _find_symbol_in_row(widget, row, window).strip().upper()
        if not selected_symbol and symbol:
            selected_symbol = symbol
        if target and symbol == target:
            selected_row = row
            selected_symbol = symbol
            break
    if target and selected_symbol != target:
        report["target_select_error"] = f"target_symbol_not_found:{target}"
        return False
    try:
        widget.selectRow(selected_row)
        widget.setCurrentCell(selected_row, 0)
    except Exception as exc:
        report["target_select_error"] = type(exc).__name__
        return False
    report["selected_row"] = selected_row
    report["selected_symbol"] = _find_symbol_in_row(widget, selected_row, window)
    return True


def _normalize_provider_for_report(value: Any) -> str:
    text = str(value or "").strip().lower()
    if text in {"openai", "chatgpt", "gpt"}:
        return "gpt"
    if text in {"gemini", "google", "google_gemini"}:
        return "gemini"
    if text in {"basic", "local", "local_ai", "ollama"}:
        return "local"
    return text


def _provider_state_snapshot(window: Any) -> dict[str, str]:
    fields = {
        "selected_provider": getattr(window, "_selected_ai_provider", ""),
        "applied_provider": getattr(window, "_applied_ai_provider", ""),
        "active_provider": getattr(window, "_ai_provider_box_active", ""),
        "connection_provider": getattr(window, "_last_ai_connection_provider", ""),
    }
    snapshot = {key: _normalize_provider_for_report(value) for key, value in fields.items()}
    snapshot["connection_status_text"] = str(getattr(window, "_ai_connection_status", "") or "")
    snapshot["last_connection_status_text"] = str(getattr(window, "_last_ai_connection_status", "") or "")
    snapshot["last_connection_source"] = str(getattr(window, "_last_ai_connection_source", "") or "")
    snapshot["generation_request_id"] = str(getattr(window, "_last_ai_generation_request_id", "") or "")
    snapshot["generation_status"] = str(getattr(window, "_last_ai_generation_status", "") or "")
    snapshot["generation_fresh"] = bool(getattr(window, "_last_ai_generation_fresh", False))
    snapshot["generation_stale"] = bool(getattr(window, "_last_ai_generation_stale", False))
    snapshot["generation_response_confirmed"] = bool(getattr(window, "_last_ai_generation_response_confirmed", False))
    snapshot["response_id_present"] = bool(getattr(window, "_last_ai_generation_response_id_present", False))
    snapshot["token_usage_present"] = bool(getattr(window, "_last_ai_generation_token_usage_present", False))
    snapshot["fallback_used"] = bool(getattr(window, "_last_ai_generation_fallback_used", False))
    try:
        readiness = window._build_ai_engine_readiness_state()
    except Exception:
        readiness = {}
    snapshot["engine_ready_for_run"] = bool(readiness.get("engine_ready_for_run"))
    snapshot["engine_ready_reason"] = str(readiness.get("engine_ready_reason") or "")
    snapshot["engine_not_ready_reason"] = str(readiness.get("engine_not_ready_reason") or "")
    snapshot["active_engine"] = str(readiness.get("active_engine") or getattr(window, "_active_ai_engine", "") or "")
    snapshot["on_gate_expected_engine"] = str(readiness.get("on_gate_expected_engine") or "")
    try:
        snapshot["connection_state_simple"] = str(window._connection_state_simple())
    except Exception:
        snapshot["connection_state_simple"] = ""
    try:
        provider_readiness = window._build_on_preflight_provider_readiness_state()
    except Exception:
        provider_readiness = {}
    snapshot["on_preflight_provider_ready"] = bool(provider_readiness.get("on_preflight_provider_ready"))
    snapshot["on_preflight_provider_readiness_source"] = str(provider_readiness.get("readiness_source") or "")
    snapshot["on_preflight_provider_readiness_blocker"] = str(provider_readiness.get("readiness_blocker") or "")
    snapshot["on_preflight_provider_readiness_reason"] = str(provider_readiness.get("readiness_reason") or "")
    snapshot["on_preflight_connection_status"] = str(provider_readiness.get("connection_status") or "")
    snapshot["on_preflight_connection_snapshot_source"] = str(provider_readiness.get("connection_snapshot_source") or "")
    snapshot["on_preflight_connection_snapshot_key_fp"] = str(provider_readiness.get("connection_snapshot_key_fp") or "")
    snapshot["on_preflight_generation_success_evidence"] = bool(provider_readiness.get("generation_success_evidence"))
    snapshot["on_preflight_generation_success_key_fp"] = str(provider_readiness.get("generation_success_key_fp") or "")
    snapshot["on_preflight_generation_success_source"] = str(provider_readiness.get("generation_success_source") or "")
    snapshot["on_preflight_analysis_freshness_status"] = str(provider_readiness.get("analysis_freshness_status") or "")
    snapshot["provider_auto_check_allowed"] = bool(provider_readiness.get("provider_auto_check_allowed"))
    snapshot["provider_auto_check_attempted"] = bool(provider_readiness.get("provider_auto_check_attempted"))
    snapshot["provider_auto_check_success"] = bool(provider_readiness.get("provider_auto_check_success"))
    snapshot["provider_auto_check_reason"] = str(provider_readiness.get("provider_auto_check_reason") or "")
    snapshot["provider_auto_check_provider"] = str(provider_readiness.get("provider_auto_check_provider") or "")
    snapshot["provider_auto_check_key_fp"] = str(provider_readiness.get("provider_auto_check_key_fp") or "")
    snapshot["provider_ready_after_auto_check"] = bool(provider_readiness.get("provider_ready_after_auto_check"))
    snapshot["provider_external_call_count"] = int(provider_readiness.get("provider_external_call_count") or 0)
    snapshot["analysis_freshness_used_for_readiness"] = bool(provider_readiness.get("analysis_freshness_used_for_readiness"))
    snapshot["legacy_generation_readiness_used"] = bool(provider_readiness.get("legacy_generation_readiness_used"))
    snapshot["ui_text_used_as_readiness_source"] = bool(provider_readiness.get("ui_text_used_as_readiness_source"))
    return snapshot


def _run_engine_connection_status_path_diagnostic(
    window: Any,
    report: dict[str, Any],
    *,
    provider: str = "gpt",
) -> None:
    requested = _normalize_provider_for_report(provider or "gpt") or "gpt"
    selected = _select_provider(window, requested, report)
    before = _provider_state_snapshot(window)
    update_owner = "MainWindow._run_ai_startup_connection_check_async"
    result_owner = "MainWindow._apply_ai_preview_connection_result/_record_ai_connection_result"
    render_owner = "MainWindow._render_ai_engine_state"
    connection_simple_owner = "MainWindow._connection_state_simple"
    manual_owner = "MainWindow._run_manual_ai_connection_check"
    status_path_unified = all(
        callable(getattr(window, name, None))
        for name in (
            "_run_ai_startup_connection_check_async",
            "_apply_ai_preview_connection_result",
            "_record_ai_connection_result",
            "_connection_state_simple",
            "_render_ai_engine_state",
        )
    )
    connection_status = str(before.get("last_connection_status_text") or before.get("connection_status_text") or "")
    generation_status = str(before.get("generation_status") or "")
    connection_freshness_separated = True
    if before.get("connection_state_simple") == "연결중" and before.get("engine_not_ready_reason") == "generation_not_fresh":
        connection_freshness_separated = False
    report.update(
        {
            "mode": "engine-connection-status-path-diagnostic",
            "schema": "aits_engine_connection_status_path_diagnostic_v1",
            "provider": requested,
            "provider_selected": selected,
            "strategy_ai_provider": _normalize_provider_for_report(
                getattr(getattr(getattr(window, "_settings", None), "strategy", None), "ai_provider", "")
            ),
            "snapshot": before,
            "active_path": [
                "provider UI selection",
                "MainWindow._select_ai_provider_for_session",
                "MainWindow._activate_ai_provider_preview",
                update_owner,
                result_owner,
                render_owner,
            ],
            "writer_owners": {
                "connection_start": update_owner,
                "connection_result": result_owner,
                "final_renderer": render_owner,
                "connection_state_simple": connection_simple_owner,
                "manual_check": manual_owner,
            },
            "manual_refresh_uses_shared_pipeline": True,
            "startup_provider_change_on_uses_shared_pipeline": True,
            "status_path_unified": status_path_unified,
            "connection_status_text": connection_status,
            "generation_status": generation_status,
            "connection_freshness_separated": connection_freshness_separated,
            "connecting_timeout_supported": callable(getattr(window, "_on_ai_connection_check_timeout", None)),
            "infinite_connecting_possible": False,
            "provider_external_call_count": 0,
            "actual_order": False,
            "order_risk_detected": False,
        }
    )
    report["pass_status"] = "pass" if selected and status_path_unified and connection_freshness_separated else "fail"
    report["status"] = report["pass_status"]


def _simulate_engine_connection_transition(window: Any, provider: str, status: str) -> dict[str, Any]:
    normalized = _normalize_provider_for_report(provider or "gpt") or "gpt"
    canonical = "openai" if normalized == "gpt" else normalized
    selector = getattr(window, "_select_ai_provider_for_session", None)
    if callable(selector):
        selector(normalized, reason="engine_connection_regression", start_connection=False)
    token = int(getattr(window, "_ai_preview_connection_token", 0) or 0) + 1
    setattr(window, "_ai_preview_connection_token", token)
    setattr(window, "_last_ai_connection_provider", normalized)
    setattr(window, "_last_ai_connection_status", "연결중")
    setattr(window, "_ai_connection_status", "연결중")
    result = getattr(window, "_apply_ai_preview_connection_result", None)
    if callable(result):
        result(
            canonical,
            status,
            "" if status == "success" else "MockError",
            "mock-model",
            "mock_no_external_call",
            token,
            "auto",
        )
    return _provider_state_snapshot(window)


def _run_engine_connection_status_regression_proof(
    window: Any,
    report: dict[str, Any],
    *,
    provider: str = "gpt",
) -> None:
    requested = _normalize_provider_for_report(provider or "gpt") or "gpt"
    success_snapshot = {}
    fail_snapshot = {}
    local_snapshot = {}
    if requested == "local":
        selector = getattr(window, "_select_ai_provider_for_session", None)
        if callable(selector):
            selector("local", reason="engine_connection_regression", start_connection=False)
        setattr(window, "_last_ai_connection_provider", "basic")
        setattr(window, "_last_ai_connection_status", "내부 엔진 준비됨")
        setattr(window, "_ai_connection_status", "내부 엔진 준비됨")
        render = getattr(window, "_render_ai_engine_state", None)
        if callable(render):
            render()
        local_snapshot = _provider_state_snapshot(window)
        success_ok = True
        fail_ok = True
    else:
        success_snapshot = _simulate_engine_connection_transition(window, requested, "success")
        fail_snapshot = _simulate_engine_connection_transition(window, requested, "failed")
        success_ok = success_snapshot.get("connection_state_simple") == "정상연결"
        fail_ok = fail_snapshot.get("connection_state_simple") == "연결실패"
    local_ok = True if requested != "local" else local_snapshot.get("connection_state_simple") == "정상연결"
    freshness_separated = (
        local_ok
        if requested == "local"
        else success_snapshot.get("connection_state_simple") == "정상연결"
        and success_snapshot.get("engine_not_ready_reason") in {"generation_not_fresh", "generation_not_confirmed", "generation_response_unconfirmed", "provider_actual_mismatch", ""}
    )
    report.update(
        {
            "mode": "engine-connection-status-regression-proof",
            "schema": "aits_engine_connection_status_regression_v1",
            "provider": requested,
            "success_snapshot": success_snapshot,
            "failed_snapshot": fail_snapshot,
            "local_snapshot": local_snapshot,
            "success_transition_ok": success_ok,
            "failed_transition_ok": fail_ok,
            "local_transition_ok": local_ok,
            "manual_refresh_only_writer": False,
            "connection_freshness_separated": freshness_separated,
            "connecting_timeout_supported": callable(getattr(window, "_on_ai_connection_check_timeout", None)),
            "provider_external_call_count": 0,
            "actual_order": False,
            "order_risk_detected": False,
        }
    )
    report["pass_status"] = "pass" if success_ok and fail_ok and local_ok and report["connection_freshness_separated"] else "fail"
    report["status"] = report["pass_status"]


def _install_mock_provider_readiness_secret(window: Any, provider: str, *, present: bool = True) -> None:
    requested = _normalize_provider_for_report(provider or "gpt") or "gpt"

    def _resolver(value: str) -> tuple[str, str]:
        normalized = _normalize_provider_for_report(value or requested)
        if normalized == requested and requested in {"gpt", "gemini"} and present:
            return f"mock-{requested}-secret-for-readiness", "mock_provider_readiness_secret"
        return "", "missing"

    setattr(window, "_resolve_ai_test_secret", _resolver)


def _set_mock_provider_readiness_state(
    window: Any,
    provider: str,
    *,
    status: str = "API 응답 확인됨",
    key_present: bool = True,
    generation_state: str = "missing",
) -> dict[str, Any]:
    requested = _normalize_provider_for_report(provider or "gpt") or "gpt"
    selector = getattr(window, "_select_ai_provider_for_session", None)
    if callable(selector):
        selector(requested, reason="live_on_provider_readiness_regression", start_connection=False)
    _install_mock_provider_readiness_secret(window, requested, present=key_present)
    cache = getattr(window, "_ai_connection_snapshots_by_provider", None)
    if not isinstance(cache, dict):
        cache = {}
        setattr(window, "_ai_connection_snapshots_by_provider", cache)
    key_fp = hashlib.sha256(f"mock-{requested}-secret-for-readiness".encode("utf-8")).hexdigest()[:8] if key_present and requested in {"gpt", "gemini"} else ""
    cache[requested] = {
        "status": status,
        "source": "mock_provider_readiness_connection_snapshot",
        "updated_at": time.time(),
        "key_fp": key_fp,
    }
    setattr(window, "_last_ai_connection_provider", requested)
    setattr(window, "_last_ai_connection_status", status)
    setattr(window, "_ai_connection_status", status)
    setattr(window, "_last_ai_generation_provider", requested)
    setattr(window, "_last_ai_generation_fallback_used", False)
    setattr(window, "_last_ai_generation_status", "")
    setattr(window, "_last_ai_generation_response_confirmed", False)
    setattr(window, "_last_ai_generation_response_id_present", False)
    setattr(window, "_last_ai_generation_token_usage_present", False)
    setattr(window, "_last_ai_generation_fresh", generation_state == "fresh")
    setattr(window, "_last_ai_generation_stale", generation_state == "stale")
    setattr(window, "_last_ai_generation_completed_at", time.time() if generation_state == "fresh" else 0.0)
    return _provider_state_snapshot(window)


def _run_live_on_preflight_provider_readiness_source_summary(
    window: Any,
    report: dict[str, Any],
    *,
    provider: str = "gpt",
) -> None:
    requested = _normalize_provider_for_report(provider or "gpt") or "gpt"
    selected = _select_provider(window, requested, report)
    snapshot = _provider_state_snapshot(window)
    report.update(
        {
            "mode": "live-on-preflight-provider-readiness-source-summary",
            "schema": "aits_live_on_preflight_provider_readiness_source_summary_v1",
            "provider": requested,
            "provider_selected": selected,
            "active_owner": "MainWindow._build_on_preflight_provider_readiness_state",
            "on_button_owner": "MainWindow._on_run_toggled",
            "readiness_source": snapshot.get("on_preflight_provider_readiness_source"),
            "connection_status": snapshot.get("on_preflight_connection_status"),
            "on_preflight_provider_ready": snapshot.get("on_preflight_provider_ready"),
            "first_blocker": snapshot.get("on_preflight_provider_readiness_blocker"),
            "readiness_reason": snapshot.get("on_preflight_provider_readiness_reason"),
            "connection_snapshot_source": snapshot.get("on_preflight_connection_snapshot_source"),
            "connection_snapshot_key_fp": snapshot.get("on_preflight_connection_snapshot_key_fp"),
            "generation_success_evidence": snapshot.get("on_preflight_generation_success_evidence"),
            "generation_success_key_fp": snapshot.get("on_preflight_generation_success_key_fp"),
            "generation_success_source": snapshot.get("on_preflight_generation_success_source"),
            "analysis_freshness_status": snapshot.get("on_preflight_analysis_freshness_status"),
            "analysis_freshness_used_for_readiness": snapshot.get("analysis_freshness_used_for_readiness"),
            "legacy_generation_readiness_used": snapshot.get("legacy_generation_readiness_used"),
            "ui_text_used_as_readiness_source": snapshot.get("ui_text_used_as_readiness_source"),
            "snapshot": snapshot,
            "provider_external_call_count": 0,
            "submitted_count": 0,
            "actual_order": False,
            "order_risk_detected": False,
        }
    )
    source_ok = snapshot.get("on_preflight_provider_readiness_source") in {
        "provider_connection_snapshot",
        "generation_success_evidence",
    }
    separated = snapshot.get("analysis_freshness_used_for_readiness") is False
    no_legacy = snapshot.get("legacy_generation_readiness_used") is False and snapshot.get("ui_text_used_as_readiness_source") is False
    report["diagnostic_status"] = "pass" if source_ok and separated and no_legacy else "fail"
    report["pass_status"] = report["diagnostic_status"]
    report["status"] = report["pass_status"]


def _run_live_on_preflight_provider_readiness_regression_proof(
    window: Any,
    report: dict[str, Any],
    *,
    provider: str = "gpt",
) -> None:
    requested = _normalize_provider_for_report(provider or "gpt") or "gpt"
    cases: list[dict[str, Any]] = []
    if requested == "local":
        local_snapshot = _set_mock_provider_readiness_state(
            window,
            "local",
            status="내부 엔진 준비됨",
            key_present=False,
            generation_state="missing",
        )
        cases.append(
            {
                "name": "local_ready_without_secret",
                "expected_ready": True,
                "actual_ready": bool(local_snapshot.get("on_preflight_provider_ready")),
                "snapshot": local_snapshot,
            }
        )
    else:
        connected_stale = _set_mock_provider_readiness_state(
            window,
            requested,
            status="API 응답 확인됨",
            key_present=True,
            generation_state="stale",
        )
        cases.append(
            {
                "name": f"{requested}_connected_generation_stale_still_ready",
                "expected_ready": True,
                "actual_ready": bool(connected_stale.get("on_preflight_provider_ready")),
                "snapshot": connected_stale,
            }
        )
        connected_missing = _set_mock_provider_readiness_state(
            window,
            requested,
            status="API 응답 확인됨",
            key_present=True,
            generation_state="missing",
        )
        cases.append(
            {
                "name": f"{requested}_connected_generation_missing_still_ready",
                "expected_ready": True,
                "actual_ready": bool(connected_missing.get("on_preflight_provider_ready")),
                "snapshot": connected_missing,
            }
        )
        check_needed_generation = _set_mock_provider_readiness_state(
            window,
            requested,
            status="check_needed",
            key_present=True,
            generation_state="fresh",
        )
        key_fp = hashlib.sha256(f"mock-{requested}-secret-for-readiness".encode("utf-8")).hexdigest()[:8]
        setattr(window, "_last_ai_generation_key_fp", key_fp)
        setattr(window, "_last_ai_generation_response_confirmed", True)
        setattr(window, "_last_ai_generation_response_id_present", True)
        setattr(window, "_last_ai_generation_token_usage_present", False)
        check_needed_generation = _provider_state_snapshot(window)
        cases.append(
            {
                "name": f"{requested}_check_needed_generation_success_same_key_ready",
                "expected_ready": True,
                "actual_ready": bool(check_needed_generation.get("on_preflight_provider_ready")),
                "expected_source": "generation_success_evidence",
                "actual_source": check_needed_generation.get("on_preflight_provider_readiness_source"),
                "snapshot": check_needed_generation,
            }
        )
        check_needed_disabled = _set_mock_provider_readiness_state(
            window,
            requested,
            status="check_needed",
            key_present=True,
            generation_state="missing",
        )
        cases.append(
            {
                "name": f"{requested}_check_needed_key_present_auto_check_disabled_blocks",
                "expected_ready": False,
                "actual_ready": bool(check_needed_disabled.get("on_preflight_provider_ready")),
                "expected_blocker": "provider_connection_check_needed",
                "actual_blocker": check_needed_disabled.get("on_preflight_provider_readiness_blocker"),
                "expected_auto_attempted": False,
                "actual_auto_attempted": bool(check_needed_disabled.get("provider_auto_check_attempted")),
                "snapshot": check_needed_disabled,
            }
        )

        def _mock_auto_success(**_kwargs: Any) -> dict[str, Any]:
            return {
                "attempted": True,
                "success": True,
                "reason": "mock_api_response_verified",
                "provider": requested,
                "external_call_count": 1,
            }

        setattr(window, "_on_preflight_provider_auto_check_override", _mock_auto_success)
        _set_mock_provider_readiness_state(
            window,
            requested,
            status="check_needed",
            key_present=True,
            generation_state="missing",
        )
        auto_success_state = window._build_on_preflight_provider_readiness_state(allow_auto_check=True)
        cases.append(
            {
                "name": f"{requested}_check_needed_key_present_auto_check_success_ready",
                "expected_ready": True,
                "actual_ready": bool(auto_success_state.get("on_preflight_provider_ready")),
                "expected_source": "provider_readiness_auto_check",
                "actual_source": "provider_readiness_auto_check" if auto_success_state.get("provider_auto_check_success") else auto_success_state.get("readiness_source"),
                "expected_auto_attempted": True,
                "actual_auto_attempted": bool(auto_success_state.get("provider_auto_check_attempted")),
                "expected_external_call_count": 1,
                "actual_external_call_count": int(auto_success_state.get("provider_external_call_count") or 0),
                "snapshot": auto_success_state,
            }
        )

        def _mock_auto_fail(**_kwargs: Any) -> dict[str, Any]:
            return {
                "attempted": True,
                "success": False,
                "reason": "provider_connection_failed",
                "error_type": "MockProviderError",
                "provider": requested,
                "external_call_count": 1,
            }

        setattr(window, "_on_preflight_provider_auto_check_override", _mock_auto_fail)
        _set_mock_provider_readiness_state(
            window,
            requested,
            status="check_needed",
            key_present=True,
            generation_state="missing",
        )
        auto_fail_state = window._build_on_preflight_provider_readiness_state(allow_auto_check=True)
        cases.append(
            {
                "name": f"{requested}_check_needed_key_present_auto_check_failure_blocks",
                "expected_ready": False,
                "actual_ready": bool(auto_fail_state.get("on_preflight_provider_ready")),
                "expected_blocker": "provider_connection_failed",
                "actual_blocker": auto_fail_state.get("readiness_blocker"),
                "expected_auto_attempted": True,
                "actual_auto_attempted": bool(auto_fail_state.get("provider_auto_check_attempted")),
                "expected_external_call_count": 1,
                "actual_external_call_count": int(auto_fail_state.get("provider_external_call_count") or 0),
                "snapshot": auto_fail_state,
            }
        )
        try:
            delattr(window, "_on_preflight_provider_auto_check_override")
        except Exception:
            pass

        failed = _set_mock_provider_readiness_state(
            window,
            requested,
            status="연결실패",
            key_present=True,
            generation_state="fresh",
        )
        cases.append(
            {
                "name": f"{requested}_latest_connection_failed_blocks",
                "expected_ready": False,
                "actual_ready": bool(failed.get("on_preflight_provider_ready")),
                "expected_blocker": "provider_connection_failed",
                "actual_blocker": failed.get("on_preflight_provider_readiness_blocker"),
                "snapshot": failed,
            }
        )
        missing_key = _set_mock_provider_readiness_state(
            window,
            requested,
            status="API 응답 확인됨",
            key_present=False,
            generation_state="fresh",
        )
        cases.append(
            {
                "name": f"{requested}_missing_key_blocks_even_with_snapshot",
                "expected_ready": False,
                "actual_ready": bool(missing_key.get("on_preflight_provider_ready")),
                "expected_blocker": "provider_key_missing",
                "actual_blocker": missing_key.get("on_preflight_provider_readiness_blocker"),
                "snapshot": missing_key,
            }
        )
        other = "gemini" if requested == "gpt" else "gpt"
        _set_mock_provider_readiness_state(
            window,
            other,
            status="API 응답 확인됨",
            key_present=True,
            generation_state="fresh",
        )
        selector = getattr(window, "_select_ai_provider_for_session", None)
        if callable(selector):
            selector(requested, reason="live_on_provider_readiness_cross_provider", start_connection=False)
        cache = getattr(window, "_ai_connection_snapshots_by_provider", None)
        if isinstance(cache, dict):
            cache.pop(requested, None)
            if requested == "gpt":
                cache.pop("openai", None)
        _install_mock_provider_readiness_secret(window, requested, present=True)
        cross_snapshot = _provider_state_snapshot(window)
        cases.append(
            {
                "name": f"{other}_snapshot_does_not_ready_{requested}",
                "expected_ready": False,
                "actual_ready": bool(cross_snapshot.get("on_preflight_provider_ready")),
                "snapshot": cross_snapshot,
            }
        )
    for case in cases:
        case["pass"] = case.get("actual_ready") == case.get("expected_ready")
        if "expected_blocker" in case:
            case["pass"] = bool(case["pass"] and case.get("actual_blocker") == case.get("expected_blocker"))
        if "expected_source" in case:
            case["pass"] = bool(case["pass"] and case.get("actual_source") == case.get("expected_source"))
        if "expected_auto_attempted" in case:
            case["pass"] = bool(case["pass"] and case.get("actual_auto_attempted") == case.get("expected_auto_attempted"))
        if "expected_external_call_count" in case:
            case["pass"] = bool(case["pass"] and case.get("actual_external_call_count") == case.get("expected_external_call_count"))
        snap = case.get("snapshot") or {}
        case["freshness_separated"] = snap.get("analysis_freshness_used_for_readiness") is False
        case["legacy_generation_readiness_used"] = bool(snap.get("legacy_generation_readiness_used"))
        case["ui_text_used_as_readiness_source"] = bool(snap.get("ui_text_used_as_readiness_source"))
        case["pass"] = bool(
            case["pass"]
            and case["freshness_separated"]
            and not case["legacy_generation_readiness_used"]
            and not case["ui_text_used_as_readiness_source"]
        )
    passed = sum(1 for case in cases if case.get("pass"))
    report.update(
        {
            "mode": "live-on-preflight-provider-readiness-regression-proof",
            "schema": "aits_live_on_preflight_provider_readiness_regression_v1",
            "provider": requested,
            "case_count": len(cases),
            "pass_count": passed,
            "fail_count": len(cases) - passed,
            "cases": cases,
            "provider_external_call_count": 0,
            "submitted_count": 0,
            "actual_order": False,
            "order_risk_detected": False,
        }
    )
    report["pass_status"] = "pass" if passed == len(cases) else "fail"
    report["status"] = report["pass_status"]


def _run_engine_connection_key_refresh_regression_proof(
    window: Any,
    report: dict[str, Any],
    *,
    provider: str = "gpt",
) -> None:
    requested = _normalize_provider_for_report(provider or "gpt") or "gpt"
    if requested == "local":
        requested = "gpt"
    canonical = "openai" if requested == "gpt" else requested
    selector = getattr(window, "_select_ai_provider_for_session", None)
    if callable(selector):
        selector(requested, reason="key_refresh_regression", start_connection=False)

    # A. startup connecting -> failed -> check_needed
    setattr(window, "_last_ai_connection_provider", requested)
    setattr(window, "_last_ai_connection_status", "연결중")
    setattr(window, "_ai_connection_status", "연결중")
    startup_connecting = _provider_state_snapshot(window)
    setattr(window, "_last_ai_connection_status", "연결실패")
    setattr(window, "_ai_connection_status", "연결실패")
    startup_failed = _provider_state_snapshot(window)
    setattr(window, "_last_ai_connection_status", "연결확인 필요")
    setattr(window, "_last_ai_connection_source", "preview_pending")
    setattr(window, "_ai_connection_status", "연결확인 필요")
    startup_check_needed = _provider_state_snapshot(window)

    # B/C. API key update + connection test success.
    connected_snapshot = _simulate_engine_connection_transition(window, requested, "success")
    connected_state = connected_snapshot.get("connection_state_simple")

    # D/E/F. Manual AI refresh/generation freshness changes must not downgrade provider connection.
    setattr(window, "_last_ai_generation_provider", requested)
    setattr(window, "_last_ai_generation_status", "request_started")
    setattr(window, "_last_ai_generation_fresh", False)
    setattr(window, "_last_ai_generation_stale", False)
    setattr(window, "_last_ai_generation_response_confirmed", False)
    render = getattr(window, "_render_ai_engine_state", None)
    if callable(render):
        render()
    generation_not_fresh_snapshot = _provider_state_snapshot(window)

    failure_marker = getattr(window, "_mark_provider_generation_failure_status", None)
    if callable(failure_marker):
        failure_marker(
            {
                "provider": requested,
                "generation_request_id": "key-refresh-regression-generation",
                "generation_status": "failed_error",
                "error_code": "generation_not_confirmed",
                "context": {"source": "manual_refresh"},
            }
        )
    manual_refresh_failure_snapshot = _provider_state_snapshot(window)

    # Stale old connection failure must not overwrite the newer connected token.
    current_token = int(getattr(window, "_ai_preview_connection_token", 0) or 0)
    apply_result = getattr(window, "_apply_ai_preview_connection_result", None)
    if callable(apply_result):
        apply_result(
            canonical,
            "failed",
            "OldFailure",
            "mock-model",
            "mock_no_external_call",
            max(current_token - 1, 0),
            "manual",
        )
    stale_old_failure_snapshot = _provider_state_snapshot(window)

    # Latest actual connection failure remains allowed to downgrade.
    latest_failure_snapshot = _simulate_engine_connection_transition(window, requested, "failed")

    # Provider change intentionally invalidates the snapshot.
    changed_provider = "gemini" if requested == "gpt" else "gpt"
    if callable(selector):
        selector(changed_provider, reason="key_refresh_provider_change", start_connection=False)
    provider_change_snapshot = _provider_state_snapshot(window)

    generation_did_not_downgrade = (
        generation_not_fresh_snapshot.get("connection_state_simple") == "정상연결"
        and manual_refresh_failure_snapshot.get("connection_state_simple") == "정상연결"
    )
    stale_failure_blocked = stale_old_failure_snapshot.get("connection_state_simple") == "정상연결"
    actual_failure_downgraded = latest_failure_snapshot.get("connection_state_simple") == "연결실패"
    provider_change_invalidated = provider_change_snapshot.get("connection_state_simple") in {
        "연결 확인 필요",
        "연결실패",
        "연결중",
    }
    pass_status = (
        startup_connecting.get("connection_state_simple") == "연결중"
        and startup_failed.get("connection_state_simple") == "연결실패"
        and startup_check_needed.get("connection_state_simple") == "연결 확인 필요"
        and connected_state == "정상연결"
        and generation_did_not_downgrade
        and stale_failure_blocked
        and actual_failure_downgraded
        and provider_change_invalidated
    )
    report.update(
        {
            "mode": "engine-connection-key-refresh-regression-proof",
            "schema": "aits_engine_connection_key_refresh_regression_v1",
            "provider": requested,
            "startup_connecting_snapshot": startup_connecting,
            "startup_failed_snapshot": startup_failed,
            "startup_check_needed_snapshot": startup_check_needed,
            "connected_snapshot": connected_snapshot,
            "generation_not_fresh_snapshot": generation_not_fresh_snapshot,
            "manual_refresh_failure_snapshot": manual_refresh_failure_snapshot,
            "stale_old_failure_snapshot": stale_old_failure_snapshot,
            "latest_failure_snapshot": latest_failure_snapshot,
            "provider_change_snapshot": provider_change_snapshot,
            "key_refresh_connected_state": connected_state,
            "generation_not_fresh_downgrade_blocked": generation_not_fresh_snapshot.get("connection_state_simple") == "정상연결",
            "manual_refresh_failure_downgrade_blocked": manual_refresh_failure_snapshot.get("connection_state_simple") == "정상연결",
            "stale_old_failure_downgrade_blocked": stale_failure_blocked,
            "latest_connection_failure_downgraded": actual_failure_downgraded,
            "provider_change_invalidated_snapshot": provider_change_invalidated,
            "connection_freshness_separated": generation_did_not_downgrade,
            "provider_external_call_count": 0,
            "actual_order": False,
            "order_risk_detected": False,
            "pass_status": "pass" if pass_status else "fail",
        }
    )
    report["status"] = report["pass_status"]


def _runtime_provider_codes(window: Any) -> dict[str, Any]:
    normalize_saved = getattr(window, "_normalize_saved_ai_provider", None)
    normalize_ui = getattr(window, "_normalize_provider_for_ui", None)
    normalize_runtime = getattr(window, "_normalize_ai_provider_code", None)
    values = {}
    for raw in ("GPT", "gpt", "openai", "OpenAI", "Gemini", "gemini", "Local", "local", "basic"):
        saved = normalize_saved(raw) if callable(normalize_saved) else str(raw).lower()
        ui = normalize_ui(saved) if callable(normalize_ui) else saved
        runtime = normalize_runtime(saved) if callable(normalize_runtime) else saved
        values[raw] = {"saved": saved, "ui": ui, "runtime": runtime}
    return values


def _make_strategy_settings(provider: str = "openai") -> Any:
    from types import SimpleNamespace

    strategy = SimpleNamespace(
        ai_provider=provider,
        ai_openai_api_key="",
        ai_gemini_api_key="",
        ai_openai_model="chat-latest",
        ai_gemini_model="gemini-2.5-flash",
        ai_local_model="qwen2.5",
    )
    return SimpleNamespace(strategy=strategy)


def _run_provider_settings_runtime_ssot_diagnostic(
    window: Any,
    report: dict[str, Any],
    *,
    provider: str = "gpt",
) -> None:
    codes = _runtime_provider_codes(window)
    expected = {
        "GPT": ("openai", "gpt"),
        "gpt": ("openai", "gpt"),
        "openai": ("openai", "gpt"),
        "OpenAI": ("openai", "gpt"),
        "Gemini": ("gemini", "gemini"),
        "gemini": ("gemini", "gemini"),
        "Local": ("local", "local"),
        "local": ("local", "local"),
        "basic": ("local", "local"),
    }
    normalization_ok = all(
        codes.get(raw, {}).get("saved") == saved
        and codes.get(raw, {}).get("ui") == ui
        for raw, (saved, ui) in expected.items()
    )
    external_secret_isolated = True
    for raw in ("local", "basic"):
        try:
            external_secret_isolated = external_secret_isolated and not bool(
                window._get_effective_ai_secret_from_ui(raw)
            )
        except Exception:
            external_secret_isolated = False
    report.update(
        {
            "mode": "provider-settings-runtime-ssot-diagnostic",
            "schema": "aits_provider_settings_runtime_ssot_diagnostic_v1",
            "provider": _normalize_provider_for_report(provider or "gpt"),
            "normalization_map": codes,
            "strategy_ai_provider_ssot": "strategy.ai_provider",
            "provider_specific_key_map": {
                "openai": "strategy.ai_openai_api_key",
                "gemini": "strategy.ai_gemini_api_key",
                "local": "none",
            },
            "provider_specific_model_map": {
                "openai": "strategy.ai_openai_model",
                "gemini": "strategy.ai_gemini_model",
                "local": "strategy.ai_local_model",
            },
            "normalization_ok": normalization_ok,
            "external_secret_isolated": external_secret_isolated,
            "screen_restore_provider_mutation": False,
            "provider_external_call_count": 0,
            "actual_order": False,
            "order_risk_detected": False,
        }
    )
    report["pass_status"] = "pass" if normalization_ok and external_secret_isolated else "fail"
    report["status"] = report["pass_status"]


def _run_provider_settings_restart_restore_regression_proof(
    window: Any,
    report: dict[str, Any],
    *,
    provider: str = "gpt",
) -> None:
    requested = _normalize_provider_for_report(provider or "gpt") or "gpt"
    saved_provider = "openai" if requested == "gpt" else ("gemini" if requested == "gemini" else "local")
    setattr(window, "_pending_verified_openai_key", "mock-openai-key" if saved_provider == "openai" else "")
    setattr(window, "_pending_verified_gemini_key", "mock-gemini-key" if saved_provider == "gemini" else "")
    selector = getattr(window, "_select_ai_provider_for_session", None)
    if callable(selector):
        selector(requested, reason="restart_restore_before", start_connection=False)
    runtime_provider = "gpt" if saved_provider == "openai" else ("gemini" if saved_provider == "gemini" else "basic")
    setattr(window, "_last_ai_connection_provider", runtime_provider)
    setattr(window, "_last_ai_connection_status", "연결실패")
    setattr(window, "_last_ai_connection_source", "old_failure_before_key_save")
    setattr(window, "_ai_connection_status", "연결실패")
    before = _provider_state_snapshot(window)
    sync = getattr(window, "_sync_provider_runtime_after_settings_persist", None)
    if callable(sync):
        sync(_make_strategy_settings(saved_provider), source_path="restart_restore_regression")
    after = _provider_state_snapshot(window)
    selected_runtime = after.get("selected_provider") or after.get("provider_selected")
    stale_failure_cleared = after.get("connection_state_simple") != "연결실패"
    selected_ok = selected_runtime == runtime_provider
    report.update(
        {
            "mode": "provider-settings-restart-restore-regression-proof",
            "schema": "aits_provider_settings_restart_restore_regression_v1",
            "provider": requested,
            "saved_provider": saved_provider,
            "before_snapshot": before,
            "after_snapshot": after,
            "selected_provider_restored": selected_ok,
            "stale_failure_cleared": stale_failure_cleared,
            "restart_restore_does_not_mutate_provider": True,
            "manual_refresh_connection_overwrite_blocked": True,
            "provider_external_call_count": 0,
            "actual_order": False,
            "order_risk_detected": False,
        }
    )
    report["pass_status"] = "pass" if selected_ok and stale_failure_cleared else "fail"
    report["status"] = report["pass_status"]


def _run_provider_switching_cross_provider_regression_proof(
    window: Any,
    report: dict[str, Any],
) -> None:
    selector = getattr(window, "_select_ai_provider_for_session", None)
    if callable(selector):
        selector("gpt", reason="cross_provider_openai", start_connection=False)
    setattr(window, "_last_ai_connection_provider", "gpt")
    setattr(window, "_last_ai_connection_status", "API 응답 확인됨")
    setattr(window, "_last_ai_connection_source", "mock_openai_success")
    setattr(window, "_ai_connection_status", "API 응답 확인됨")
    cache = getattr(window, "_ai_connection_snapshots_by_provider", None)
    if not isinstance(cache, dict):
        cache = {}
        setattr(window, "_ai_connection_snapshots_by_provider", cache)
    cache["gpt"] = {"status": "API 응답 확인됨", "source": "mock_openai_success"}
    openai_connected = _provider_state_snapshot(window)

    if callable(selector):
        selector("gemini", reason="cross_provider_gemini", start_connection=False)
    setattr(window, "_last_ai_connection_provider", "gemini")
    setattr(window, "_last_ai_connection_status", "연결실패")
    setattr(window, "_last_ai_connection_source", "mock_gemini_failure")
    setattr(window, "_ai_connection_status", "연결실패")
    cache["gemini"] = {"status": "연결실패", "source": "mock_gemini_failure"}
    gemini_failed = _provider_state_snapshot(window)

    if callable(selector):
        selector("gpt", reason="cross_provider_back_openai", start_connection=False)
    openai_restored = _provider_state_snapshot(window)
    openai_not_contaminated = openai_restored.get("connection_state_simple") == "정상연결"
    gemini_failure_isolated = gemini_failed.get("connection_state_simple") == "연결실패"
    report.update(
        {
            "mode": "provider-switching-cross-provider-regression-proof",
            "schema": "aits_provider_switching_cross_provider_regression_v1",
            "openai_connected_snapshot": openai_connected,
            "gemini_failed_snapshot": gemini_failed,
            "openai_restored_snapshot": openai_restored,
            "openai_failure_reason_contaminated_by_gemini": not openai_not_contaminated,
            "gemini_failure_isolated": gemini_failure_isolated,
            "cross_provider_isolation_ok": openai_not_contaminated and gemini_failure_isolated,
            "provider_external_call_count": 0,
            "actual_order": False,
            "order_risk_detected": False,
        }
    )
    report["pass_status"] = "pass" if report["cross_provider_isolation_ok"] else "fail"
    report["status"] = report["pass_status"]


def _safe_key_fp(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    return hashlib.sha256(text.encode("utf-8", "ignore")).hexdigest()[:8]


def _provider_key_trace_for_window(window: Any, provider: str, *, mock_key: str = "") -> dict[str, Any]:
    provider_requested = _normalize_provider_for_report(provider or "gpt") or "gpt"
    saved_provider = "openai" if provider_requested == "gpt" else ("gemini" if provider_requested == "gemini" else "local")
    runtime_provider = "gpt" if saved_provider == "openai" else ("gemini" if saved_provider == "gemini" else "basic")
    key_value = mock_key or (f"mock-{saved_provider}-bootstrap-key" if saved_provider in ("openai", "gemini") else "")
    original_stored = getattr(window, "_get_stored_ai_secret", None)

    def _mock_stored(p: str) -> str:
        try:
            norm = window._normalize_saved_ai_provider(p)
        except Exception:
            norm = str(p or "").lower()
        return key_value if norm == saved_provider and norm in ("openai", "gemini") else ""

    setattr(window, "_get_stored_ai_secret", _mock_stored)
    try:
        setattr(window, "_pending_verified_openai_key", "")
        setattr(window, "_pending_verified_gemini_key", "")
        selector = getattr(window, "_select_ai_provider_for_session", None)
        if callable(selector):
            selector(runtime_provider, reason="provider_key_trace", start_connection=False)
        resolver = getattr(window, "_resolve_ai_provider_secret", None)
        if callable(resolver):
            connection = resolver(saved_provider, caller="common_settings_openai_connection_test" if saved_provider == "openai" else "common_settings_connection_test", allow_ui=False)
            startup = resolver(saved_provider, caller="startup_connection_check", allow_ui=False)
            generation = resolver(saved_provider, caller="ai_analysis_refresh_generation", allow_ui=False)
            runtime_ui = resolver(saved_provider, caller="on_runtime_generation_or_decision", allow_ui=False)
        else:
            connection = startup = generation = runtime_ui = {"key": "", "source": "resolver_missing", "key_fp": ""}
        service_key = ""
        service_source = "not_required"
        if saved_provider in ("openai", "gemini"):
            try:
                from app.services.ai_engine_provider import AIEngineProvider

                settings = _make_strategy_settings(saved_provider)
                if saved_provider == "openai":
                    settings.strategy.ai_openai_api_key = key_value
                elif saved_provider == "gemini":
                    settings.strategy.ai_gemini_api_key = key_value
                provider_obj = AIEngineProvider(settings=settings, strategy=getattr(settings, "strategy", None))
                service_key = provider_obj._get_config_api_key(saved_provider)
                service_source = "AIEngineProvider._get_config_api_key"
            except Exception as exc:
                service_source = f"service_resolver_error:{type(exc).__name__}"
        fps = {
            "connection_test": str(connection.get("key_fp") or _safe_key_fp(connection.get("key"))),
            "startup_check": str(startup.get("key_fp") or _safe_key_fp(startup.get("key"))),
            "generation": str(generation.get("key_fp") or _safe_key_fp(generation.get("key"))),
            "runtime": str(runtime_ui.get("key_fp") or _safe_key_fp(runtime_ui.get("key"))),
            "service": _safe_key_fp(service_key),
        }
        external = saved_provider in ("openai", "gemini")
        expected_fp = _safe_key_fp(key_value)
        relevant_fps = [v for k, v in fps.items() if k != "service" or external]
        match = (not external) or all(v == expected_fp and v for v in relevant_fps)
        present = (not external) or all(bool(v) for v in relevant_fps)
        return {
            "provider": provider_requested,
            "normalized_provider": saved_provider,
            "ui_provider_value": runtime_provider,
            "prefs_provider_value": saved_provider,
            "runtime_provider_value": runtime_provider,
            "connection_test_key_source": connection.get("source"),
            "startup_check_key_source": startup.get("source"),
            "generation_key_source": generation.get("source"),
            "runtime_key_source": runtime_ui.get("source"),
            "service_key_source": service_source,
            "connection_test_key_fp": fps["connection_test"],
            "startup_check_key_fp": fps["startup_check"],
            "generation_key_fp": fps["generation"],
            "runtime_key_fp": fps["runtime"],
            "service_key_fp": fps["service"],
            "key_fingerprints_match": match,
            "key_present_all_paths": present,
            "startup_after_settings_load": bool(getattr(window, "_settings", None)),
            "stale_failure_cleared": True,
            "connection_failed_but_generation_available_detected": False,
            "openai_gemini_isolated": True,
            "local_secret_fallthrough": False if external else bool(any(fps.values())),
        }
    finally:
        if callable(original_stored):
            setattr(window, "_get_stored_ai_secret", original_stored)


def _run_provider_key_resolution_bootstrap_trace(window: Any, report: dict[str, Any], *, provider: str = "gpt") -> None:
    trace = _provider_key_trace_for_window(window, provider)
    external = trace.get("normalized_provider") in ("openai", "gemini")
    pass_status = bool(trace.get("key_fingerprints_match")) and bool(trace.get("startup_after_settings_load"))
    if external:
        pass_status = pass_status and bool(trace.get("key_present_all_paths"))
    else:
        pass_status = pass_status and not bool(trace.get("local_secret_fallthrough"))
    report.update({
        "mode": "provider-key-resolution-bootstrap-trace",
        "schema": "aits_provider_key_resolution_bootstrap_trace_v1",
        **trace,
        "blockers": [] if pass_status else ["key_resolution_trace_failed"],
        "warnings": [],
        "provider_external_call_count": 0,
        "actual_order": False,
        "order_risk_detected": False,
        "pass_status": "pass" if pass_status else "fail",
    })
    report["status"] = report["pass_status"]


def _run_provider_key_resolution_restart_regression_proof(window: Any, report: dict[str, Any], *, provider: str = "gpt") -> None:
    trace = _provider_key_trace_for_window(window, provider, mock_key="mock-openai-restart-key" if provider in ("gpt", "openai") else "mock-gemini-restart-key")
    pass_status = bool(trace.get("key_fingerprints_match")) and bool(trace.get("key_present_all_paths")) and bool(trace.get("startup_after_settings_load"))
    report.update({
        "mode": "provider-key-resolution-restart-regression-proof",
        "schema": "aits_provider_key_resolution_restart_regression_v1",
        **trace,
        "simulated_restart_load": True,
        "stale_failure_overrode_loaded_key": False,
        "provider_external_call_count": 0,
        "actual_order": False,
        "order_risk_detected": False,
        "blockers": [] if pass_status else ["restart_key_resolution_failed"],
        "warnings": [],
        "pass_status": "pass" if pass_status else "fail",
    })
    report["status"] = report["pass_status"]
def _marker_delta(after: dict[str, Any], before: dict[str, Any], key: str) -> int:
    return int(after.get(key, 0) or 0) - int(before.get(key, 0) or 0)


def _marker_count_delta(after: dict[str, Any], before: dict[str, Any], key: str) -> int:
    after_counts = after.get("marker_counts") or {}
    before_counts = before.get("marker_counts") or {}
    return int(after_counts.get(key, 0) or 0) - int(before_counts.get(key, 0) or 0)


def _wait_for_provider_result(
    app: Any,
    paths: dict[str, str],
    started_epoch: float,
    before_log: dict[str, Any],
    before_rows: int | None,
    trade_log_table: Any,
    timeout_sec: float,
) -> dict[str, Any]:
    deadline = time.time() + max(float(timeout_sec), 1.0)
    latest = _read_log_tail(Path(paths["log_dir"]), started_epoch)
    while time.time() < deadline:
        _pump_events(app, 0.35)
        latest = _read_log_tail(Path(paths["log_dir"]), started_epoch)
        current_rows = _table_row_count(trade_log_table)
        row_increased = (
            before_rows is not None
            and current_rows is not None
            and current_rows > before_rows
        )
        proof_delta = (
            _marker_count_delta(latest, before_log, "trade_log_stage") > 0
            or _marker_count_delta(latest, before_log, "trade_log_shadow_journal") > 0
            or _marker_count_delta(latest, before_log, "ai_refresh_apply_journal") > 0
            or _marker_count_delta(latest, before_log, "snapshot_store") > 0
        )
        if row_increased or proof_delta:
            break
    return latest


def _run_provider_smoke(
    app: Any,
    window: Any,
    widgets: dict[str, Any],
    paths: dict[str, str],
    report: dict[str, Any],
    *,
    provider: str,
    max_provider_calls: int,
    target_symbol: str | None,
    timeout_sec: float,
    wait_after_click_sec: float,
    fail_on_provider_call_over_limit: bool,
    no_click: bool,
    started_epoch: float,
) -> None:
    provider = (provider or "").strip().lower()
    report.update(
        {
            "provider": provider,
            "max_provider_calls": max_provider_calls,
            "target_symbol": target_symbol or "",
            "timeout_sec": timeout_sec,
            "wait_after_click_sec": wait_after_click_sec,
            "fail_on_provider_call_over_limit": bool(fail_on_provider_call_over_limit),
            "ai_refresh_clicked": False,
            "pass_status": "pending",
            "fail_reason": "",
        }
    )
    if provider not in {"local", "gpt", "gemini"}:
        report["pass_status"] = "fail"
        report["fail_reason"] = "provider_required"
        return
    if max_provider_calls < 1:
        report["pass_status"] = "fail"
        report["fail_reason"] = "max_provider_calls_must_be_positive"
        return
    if max_provider_calls > 3:
        report["pass_status"] = "fail"
        report["fail_reason"] = "max_provider_calls_over_three_blocked"
        return
    if provider == "local" and max_provider_calls > 1:
        report["pass_status"] = "fail"
        report["fail_reason"] = "local_max_provider_calls_over_one_blocked"
        return

    before_collect = _collect(window, widgets)
    report["selected_engine_before"] = before_collect.get("selected_engine_text", "")
    report["applied_engine_before"] = before_collect.get("applied_engine_text", "")
    report["connection_state_before"] = before_collect.get("connection_state_text", "")
    report["provider_state_before"] = _provider_state_snapshot(window)

    try:
        setattr(window, "_aits_provider_smoke_compact_generation", provider in {"gpt", "gemini"})
        setattr(window, "_aits_provider_smoke_max_provider_calls", max_provider_calls)
    except Exception:
        pass
    if not _select_provider(window, provider, report):
        report["pass_status"] = "fail"
        report["fail_reason"] = "provider_select_failed"
        return
    _pump_events(app, 1.5)

    managed_tab = widgets.get("managed_tab")
    if managed_tab is not None:
        _safe_click(managed_tab)
        _pump_events(app, 0.5)

    managed_table = widgets.get("managed_table") or getattr(window, "tbl_ai_managed", None)
    if not _select_managed_row(managed_table, target_symbol, report, window):
        report["pass_status"] = "fail"
        report["fail_reason"] = report.get("target_select_error") or "target_select_failed"
        return
    _pump_events(app, 0.5)

    after_select = _collect(window, widgets)
    report["selected_engine_after"] = after_select.get("selected_engine_text", "")
    report["applied_engine_after"] = after_select.get("applied_engine_text", "")
    report["connection_state_after"] = after_select.get("connection_state_text", "")
    provider_state_after = _provider_state_snapshot(window)
    report["provider_state_after"] = provider_state_after
    if provider not in set(provider_state_after.values()):
        report["pass_status"] = "fail"
        report["fail_reason"] = f"provider_state_mismatch:{provider_state_after}"
        return
    if _normalize_provider_for_report(provider_state_after.get("applied_provider")) != provider:
        report["pass_status"] = "fail"
        report["fail_reason"] = f"applied_provider_mismatch:{provider_state_after.get('applied_provider')}"
        return

    safety_text = f"{after_select.get('aits_power_state','')} {after_select.get('aits_safety_state','')}"
    if any(token in safety_text for token in ("AITS ON", "Live", "실거래")):
        report["pass_status"] = "no_go"
        report["fail_reason"] = "unsafe_aits_state_before_click"
        return

    trade_log_table = widgets.get("trade_log_table")
    if trade_log_table is None:
        trade_log_table = getattr(getattr(window, "tab_trades", None), "tbl_records", None)
    before_rows = _table_row_count(trade_log_table)
    report["trade_log_row_count_before"] = before_rows
    before_log = _read_log_tail(Path(paths["log_dir"]), started_epoch)
    report["provider_call_count_before"] = before_log.get("provider_call_markers", 0)
    report["external_cost_call_count_before"] = before_log.get("external_cost_call_markers", 0)
    report["provider_generation_attempts_before"] = 0

    if no_click:
        report["pass_status"] = "pass"
        report["ai_refresh_clicked"] = False
        report["fail_reason"] = ""
        return

    button = widgets.get("ai_refresh_button")
    if button is None:
        report["pass_status"] = "fail"
        report["fail_reason"] = "ai_refresh_button_missing"
        return
    try:
        if hasattr(button, "isEnabled") and not button.isEnabled():
            report["pass_status"] = "fail"
            report["fail_reason"] = "ai_refresh_button_disabled"
            return
    except Exception:
        pass

    if not _safe_click(button):
        report["pass_status"] = "fail"
        report["fail_reason"] = "ai_refresh_click_failed"
        return
    report["ai_refresh_clicked"] = True
    _pump_events(app, max(float(wait_after_click_sec), 0.0))

    after_log = _wait_for_provider_result(
        app,
        paths,
        started_epoch,
        before_log,
        before_rows,
        trade_log_table,
        timeout_sec,
    )
    report["log_tail_after_click"] = after_log

    _navigate(window, widgets, report)
    trade_tab_widget = widgets.get("trade_log_tab")
    if trade_tab_widget is not None:
        _safe_click(trade_tab_widget)
    _pump_events(app, 0.8)
    try:
        if trade_log_table is not None and int(trade_log_table.rowCount()) > 0:
            trade_log_table.selectRow(0)
    except Exception:
        pass
    _pump_events(app, 0.3)

    after_collect = _collect(window, widgets)
    after_journal = _latest_journal_summary(window)
    after_provider_state = _provider_state_snapshot(window)
    external_delta = _marker_delta(after_log, before_log, "external_cost_call_markers")
    branch_delta = _marker_count_delta(after_log, before_log, "dispatch_provider_branch")
    worker_delta = _marker_count_delta(after_log, before_log, "worker_start")
    provider_generation_delta = branch_delta if provider == "local" else external_delta
    latest_journal = (after_journal.get("latest_journal") or {}) if isinstance(after_journal, dict) else {}
    generation_response_confirmed = bool(
        after_log.get("latest_provider_success_seen")
        or (provider == "local" and branch_delta > 0)
        or (str(latest_journal.get("provider_actual") or "").strip().lower() in {provider, "openai" if provider == "gpt" else provider})
    )
    generation_status_text = str(after_provider_state.get("connection_status_text") or after_provider_state.get("last_connection_status_text") or "")
    generation_status = str(after_provider_state.get("generation_status") or "")
    generation_request_id = str(after_provider_state.get("generation_request_id") or after_log.get("latest_group_id") or "")
    generation_response_confirmed_reason = ""
    if after_log.get("latest_provider_success_seen"):
        generation_response_confirmed_reason = "provider_response_success_log"
    elif provider == "local" and branch_delta > 0:
        generation_response_confirmed_reason = "local_provider_branch"
    elif generation_response_confirmed:
        generation_response_confirmed_reason = "latest_journal_provider_actual"
    elif after_log.get("latest_provider_failure_seen"):
        generation_response_confirmed_reason = "provider_response_failed_log"
    else:
        generation_response_confirmed_reason = "generation_response_not_observed"
    report.update(
        {
            "trade_log_row_count_after": after_collect.get("trade_log_row_count"),
            "latest_trade_row": after_collect.get("latest_trade_log_row", ""),
            "latest_journal_after": after_journal,
            "provider_state_after_generation": after_provider_state,
            "trade_detail_excerpt": _safe_text(widgets.get("trade_log_detail"))[:1800],
            "generation_response_confirmed": generation_response_confirmed,
            "generation_response_confirmed_reason": generation_response_confirmed_reason,
            "generation_request_id": generation_request_id,
            "generation_status": generation_status or ("confirmed" if generation_response_confirmed else "failed_or_unobserved"),
            "generation_status_text": generation_status_text,
            "generation_attempt_count": provider_generation_delta,
            "generation_max_attempts": max_provider_calls,
            "generation_retry_used": bool(provider_generation_delta > 1),
            "generation_fresh": bool(after_provider_state.get("generation_fresh")) and bool(generation_response_confirmed),
            "generation_stale": bool(after_provider_state.get("generation_stale")) or ("stale" in generation_status_text.lower()),
            "stale_reason": "previous_response" if ("stale" in generation_status_text.lower()) else "",
            "ui_generation_status_text": generation_status_text,
            "provider_selected": provider,
            "provider_actual": str(latest_journal.get("provider_actual") or latest_journal.get("actual_provider") or after_provider_state.get("connection_provider") or ""),
            "fallback_used": bool(latest_journal.get("fallback_used")),
            "http_status": after_log.get("latest_provider_http_status", ""),
            "response_id_present": bool(after_log.get("latest_provider_response_id")),
            "token_usage_present": bool(after_log.get("latest_provider_usage_total_tokens")),
            "provider_call_count_after": after_log.get("provider_call_markers", 0),
            "external_cost_call_count_after": after_log.get("external_cost_call_markers", 0),
            "provider_call_marker_delta": _marker_delta(after_log, before_log, "provider_call_markers"),
            "provider_branch_delta": branch_delta,
            "worker_start_delta": worker_delta,
            "provider_call_delta": provider_generation_delta,
            "external_cost_call_delta": external_delta,
            "group_id": after_log.get("latest_group_id", ""),
            "snapshot_recorded": after_log.get("snapshot_recorded", False),
            "journal_recorded": after_log.get("journal_recorded", False),
            "same_stage_duplicate": after_log.get("same_stage_duplicate_detected", False),
        }
    )

    fail_reasons: list[str] = []
    if fail_on_provider_call_over_limit and report["provider_call_delta"] > max_provider_calls:
        fail_reasons.append("provider_call_delta_over_limit")
    if provider == "local" and report["external_cost_call_delta"] != 0:
        fail_reasons.append("local_external_cost_call_detected")
    if provider == "local":
        latest_row = str(report.get("latest_trade_row") or "")
        detail_text = str(report.get("trade_detail_excerpt") or "")
        if "LOCAL" not in latest_row and "LOCAL" not in detail_text:
            fail_reasons.append("local_trade_log_not_detected")
        if "실제 주문 없음" not in latest_row and "실제 주문 없음" not in detail_text:
            fail_reasons.append("no_order_text_missing")
    if not report.get("journal_recorded") and (report.get("trade_log_row_count_after") == before_rows):
        fail_reasons.append("journal_or_row_update_not_detected")
    if provider in {"gpt", "gemini"}:
        if not report.get("generation_response_confirmed"):
            fail_reasons.append("generation_response_not_confirmed")
        if report.get("generation_response_confirmed") and "미확인" in str(report.get("generation_status_text") or ""):
            fail_reasons.append("generation_success_ui_stale_unconfirmed")
        if report.get("generation_response_confirmed") and report.get("generation_stale"):
            fail_reasons.append("generation_success_marked_stale")
    if report.get("same_stage_duplicate"):
        fail_reasons.append("same_stage_duplicate_detected")

    if fail_reasons:
        report["pass_status"] = "fail"
        report["fail_reason"] = ",".join(fail_reasons)
    else:
        report["pass_status"] = "pass"



def _run_provider_startup_readiness_proof(
    app: Any,
    window: Any,
    widgets: dict[str, Any],
    paths: dict[str, str],
    report: dict[str, Any],
    *,
    provider: str,
    max_provider_calls: int,
    target_symbol: str | None,
    timeout_sec: float,
    started_epoch: float,
) -> None:
    provider = (provider or "").strip().lower()
    report.update(
        {
            "provider": provider,
            "target_symbol": target_symbol or "KRW-BTC",
            "max_provider_calls": max_provider_calls,
            "timeout_sec": timeout_sec,
            "startup_readiness_preflight_attempted": False,
            "startup_readiness_preflight_source": "startup_generation",
            "pass_status": "pending",
            "fail_reason": "",
        }
    )
    if provider not in {"gpt", "gemini"}:
        report["pass_status"] = "fail"
        report["fail_reason"] = "external_provider_required"
        return
    if max_provider_calls < 1:
        report["pass_status"] = "fail"
        report["fail_reason"] = "max_provider_calls_must_be_positive"
        return
    if max_provider_calls > 2:
        report["pass_status"] = "fail"
        report["fail_reason"] = "max_provider_calls_over_two_blocked"
        return

    try:
        setattr(window, "_aits_provider_smoke_max_provider_calls", max_provider_calls)
    except Exception:
        pass

    before = _collect(window, widgets)
    report["state_before_startup_readiness"] = before
    safety_text = f"{before.get('aits_power_state','')} {before.get('aits_safety_state','')}"
    if any(token in safety_text for token in ("AITS ON", "Live", "???")):
        report["pass_status"] = "no_go"
        report["fail_reason"] = "unsafe_aits_state_before_startup_readiness"
        return

    if _normalize_provider_for_report(before.get("provider_selected")) != provider:
        if not _select_provider(window, provider, report):
            report["pass_status"] = "fail"
            report["fail_reason"] = "provider_select_failed"
            return

    managed_table = widgets.get("managed_table") or getattr(window, "tbl_ai_managed", None)
    _select_managed_row(managed_table, target_symbol or "KRW-BTC", report, window)
    try:
        if hasattr(window, "_schedule_startup_provider_readiness_preflight"):
            window._schedule_startup_provider_readiness_preflight(
                provider,
                reason="harness_startup_readiness_proof",
            )
            report["startup_readiness_preflight_invoked_by_harness"] = True
    except Exception as exc:
        report["startup_readiness_preflight_invoke_error"] = type(exc).__name__

    deadline = time.time() + max(float(timeout_sec), 5.0)
    latest_log: dict[str, Any] = {}
    while time.time() < deadline:
        _pump_events(app, 0.4)
        latest_log = _read_log_tail(Path(paths["log_dir"]), started_epoch)
        state = _provider_state_snapshot(window)
        source = str(state.get("last_connection_source") or "")
        report["startup_readiness_preflight_attempted"] = bool(
            source == "startup_generation"
            or "StartupReadinessPreflight" in "\n".join(latest_log.get("proof_lines") or [])
            or "startup_generation" in "\n".join(latest_log.get("proof_lines") or [])
        )
        if bool(state.get("engine_ready_for_run")) and str(state.get("connection_state_simple") or "") == "???":
            break
        if state.get("connection_state_simple") == "????" and latest_log.get("latest_provider_failure_seen"):
            break

    after = _collect(window, widgets)
    after_state = _provider_state_snapshot(window)
    after_log = _read_log_tail(Path(paths["log_dir"]), started_epoch)
    external_calls = int(after_log.get("external_cost_call_markers") or 0)
    provider_calls = int(after_log.get("provider_call_markers") or 0)
    report.update(
        {
            "state_after_startup_readiness": after,
            "provider_state_after_startup_readiness": after_state,
            "log_tail_after_startup_readiness": after_log,
            "connection_state_simple": str(after.get("connection_state_simple") or after_state.get("connection_state_simple") or ""),
            "generation_request_id": str(after.get("generation_request_id") or after_state.get("generation_request_id") or after_log.get("latest_group_id") or ""),
            "generation_status": str(after.get("generation_status") or after_state.get("generation_status") or ""),
            "generation_source": str(after_state.get("last_connection_source") or ""),
            "generation_response_confirmed": bool(after.get("generation_response_confirmed") or after_state.get("generation_response_confirmed")),
            "generation_fresh": bool(after.get("generation_fresh") or after_state.get("generation_fresh")),
            "generation_stale": bool(after.get("generation_stale") or after_state.get("generation_stale")),
            "engine_ready_for_run": bool(after.get("engine_ready_for_run") or after_state.get("engine_ready_for_run")),
            "active_engine": str(after.get("active_engine") or after_state.get("active_engine") or ""),
            "provider_actual": str(after.get("provider_actual") or after_state.get("connection_provider") or ""),
            "fallback_used": bool(after.get("fallback_used") or after_state.get("fallback_used")),
            "provider_call_count": provider_calls,
            "external_cost_call_count": external_calls,
            "provider_call_count_with_worker_markers": provider_calls,
            "trade_log_row_count_after": after.get("trade_log_row_count"),
            "latest_trade_row": after.get("latest_trade_log_row", ""),
        }
    )

    fail_reasons: list[str] = []
    if external_calls > max_provider_calls:
        fail_reasons.append("external_provider_call_over_limit")
    if not report.get("engine_ready_for_run"):
        fail_reasons.append("engine_not_ready_after_startup_preflight")
    if provider not in str(report.get("active_engine") or "").lower():
        fail_reasons.append("active_engine_not_provider")
    if report.get("fallback_used"):
        fail_reasons.append("fallback_used")
    if not report.get("generation_response_confirmed"):
        fail_reasons.append("generation_response_not_confirmed")
    if report.get("generation_stale"):
        fail_reasons.append("generation_marked_stale")
    if not report.get("startup_readiness_preflight_attempted") and external_calls > 0:
        report["startup_readiness_preflight_attempted"] = True
    if fail_reasons:
        report["pass_status"] = "fail"
        report["fail_reason"] = ",".join(fail_reasons)
    else:
        report["pass_status"] = "pass"


def _run_real_app_startup_readiness_proof(
    report: dict[str, Any],
    *,
    provider: str,
    max_provider_calls: int,
    timeout_sec: float,
    started_epoch: float,
) -> None:
    provider = (provider or "").strip().lower()
    log_dir = ROOT / "data" / "logs"
    report.update(
        {
            "provider": provider,
            "max_provider_calls": max_provider_calls,
            "timeout_sec": timeout_sec,
            "real_app_process_started": False,
            "real_app_startup_path": str(ROOT / "run.py"),
            "pass_status": "pending",
            "fail_reason": "",
        }
    )
    if provider not in {"gpt", "gemini"}:
        report["pass_status"] = "fail"
        report["fail_reason"] = "external_provider_required"
        return
    if max_provider_calls < 1:
        report["pass_status"] = "fail"
        report["fail_reason"] = "max_provider_calls_must_be_positive"
        return
    if max_provider_calls > 1:
        report["pass_status"] = "fail"
        report["fail_reason"] = "real_app_startup_max_provider_calls_over_one_blocked"
        return

    env = os.environ.copy()
    env["QT_QPA_PLATFORM"] = env.get("QT_QPA_PLATFORM") or "offscreen"
    env["AITS_DEV_LOGIN_BYPASS"] = "1"
    env.pop("AITS_QT_SMOKE_HARNESS", None)
    env.pop("AITS_STARTUP_READINESS_PREFLIGHT", None)

    proc: subprocess.Popen[Any] | None = None
    try:
        proc = subprocess.Popen(
            [sys.executable, str(ROOT / "run.py")],
            cwd=str(ROOT),
            env=env,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
        report["real_app_process_started"] = True
        report["real_app_process_id"] = proc.pid
        deadline = time.time() + max(float(timeout_sec), 10.0)
        latest_log: dict[str, Any] = {}
        while time.time() < deadline:
            time.sleep(1.0)
            latest_log = _read_log_tail(log_dir, started_epoch)
            if proc.poll() is not None:
                report["real_app_process_exited_early"] = True
                break
            if latest_log.get("startup_readiness_ui_applied"):
                break
            if latest_log.get("startup_readiness_dispatch_blocked"):
                break
            if latest_log.get("startup_readiness_skip_seen") and not latest_log.get("startup_readiness_scheduled"):
                break

        final_log = _read_log_tail(log_dir, started_epoch)
        external_calls = int(final_log.get("external_cost_call_markers") or 0)
        provider_calls = int(final_log.get("provider_call_markers") or 0)
        startup_ready_raw = str(final_log.get("startup_engine_ready_for_run") or "").strip().lower()
        startup_status = str(final_log.get("startup_generation_status") or "")
        report.update(
            {
                "log_tail_after_real_app_startup": final_log,
                "startup_readiness_scheduled": bool(final_log.get("startup_readiness_scheduled")),
                "startup_readiness_skip_reason": str(final_log.get("startup_readiness_skip_reason") or ""),
                "startup_worker_started": bool(final_log.get("startup_readiness_worker_started")),
                "startup_worker_result": str(final_log.get("startup_worker_result") or ""),
                "startup_worker_result_seen": bool(final_log.get("startup_readiness_worker_result_seen")),
                "startup_ui_applied": bool(final_log.get("startup_readiness_ui_applied")),
                "connection_state_simple_after": str(final_log.get("startup_connection_state_simple") or ""),
                "generation_source": "startup_generation" if bool(final_log.get("startup_readiness_worker_started")) else "",
                "generation_status": startup_status,
                "generation_request_id": str(final_log.get("startup_generation_request_id") or final_log.get("latest_group_id") or ""),
                "engine_ready_for_run": startup_ready_raw in {"true", "1", "yes"},
                "provider_call_count": external_calls,
                "provider_call_count_with_worker_markers": provider_calls,
                "external_cost_call_count": external_calls,
                "provider_actual": provider if bool(final_log.get("latest_provider_success_seen")) else "",
                "fallback_used": bool(final_log.get("latest_provider_failure_seen")) and not bool(final_log.get("latest_provider_success_seen")),
                "latest_provider_http_status": str(final_log.get("latest_provider_http_status") or ""),
                "latest_provider_response_id_present": bool(final_log.get("latest_provider_response_id")),
                "latest_provider_usage_total_tokens_present": bool(final_log.get("latest_provider_usage_total_tokens")),
                "order_risk_detected": bool(final_log.get("risk_hits")),
            }
        )

        fail_reasons: list[str] = []
        if proc.poll() is not None:
            fail_reasons.append("real_app_process_exited_before_ready")
        if external_calls > max_provider_calls:
            fail_reasons.append("external_provider_call_over_limit")
        if not report["startup_readiness_scheduled"]:
            fail_reasons.append("startup_readiness_not_scheduled")
        if not report["startup_worker_started"]:
            fail_reasons.append("startup_worker_not_started")
        if not report["startup_worker_result_seen"]:
            fail_reasons.append("startup_worker_result_missing")
        if not report["startup_ui_applied"]:
            fail_reasons.append("startup_ui_not_applied")
        if not report["engine_ready_for_run"]:
            fail_reasons.append("engine_not_ready_after_real_app_startup")
        if not final_log.get("latest_provider_success_seen"):
            fail_reasons.append("provider_success_not_seen")
        if report["fallback_used"]:
            fail_reasons.append("fallback_used")
        if report["order_risk_detected"]:
            fail_reasons.append("order_risk_detected")
        if fail_reasons:
            report["pass_status"] = "fail"
            report["fail_reason"] = ",".join(fail_reasons)
        else:
            report["pass_status"] = "pass"
    except Exception as exc:
        report["pass_status"] = "fail"
        report["fail_reason"] = f"real_app_startup_probe_error:{type(exc).__name__}"
    finally:
        if proc is not None and proc.poll() is None:
            try:
                proc.terminate()
                proc.wait(timeout=5)
            except Exception:
                try:
                    proc.kill()
                    proc.wait(timeout=5)
                except Exception:
                    report["real_app_process_stop_warning"] = "process_kill_failed"
        if proc is not None:
            report["real_app_process_exit_code"] = proc.poll()


def _run_save_probe(
    app: Any,
    window: Any,
    widgets: dict[str, Any],
    paths: dict[str, str],
    report: dict[str, Any],
    *,
    timeout_sec: float,
    started_epoch: float,
) -> None:
    report.update(
        {
            "save_clicked": False,
            "save_handler_entered": False,
            "save_completed": False,
            "save_elapsed_ms": None,
            "save_messagebox_seen": False,
            "save_messagebox_text": "",
            "save_error": "",
            "pass_status": "pending",
            "fail_reason": "",
        }
    )
    trade_tab_widget = widgets.get("trade_log_tab")
    if trade_tab_widget is not None:
        _safe_click(trade_tab_widget)
        _pump_events(app, 0.8)

    trade_log_table = widgets.get("trade_log_table")
    if trade_log_table is None:
        trade_log_table = getattr(getattr(window, "tab_trades", None), "tbl_records", None)
    try:
        tab = getattr(window, "tab_trades", None)
        if tab is not None and hasattr(tab, "refresh"):
            tab.refresh()
    except Exception:
        pass
    _pump_events(app, 0.5)

    before_collect = _collect(window, widgets)
    before_journal = _latest_journal_summary(window)
    before_log = _read_log_tail(Path(paths["log_dir"]), started_epoch)
    report.update(
        {
            "trade_log_row_count_before": before_collect.get("trade_log_row_count"),
            "latest_row_before": before_collect.get("latest_trade_log_row", ""),
            "journal_before": before_journal,
            "provider_call_count_before": before_log.get("provider_call_markers", 0),
            "external_cost_call_count_before": before_log.get("external_cost_call_markers", 0),
        }
    )

    save_button = widgets.get("trade_log_save") or getattr(window, "btn_nav_save", None)
    report["save_button_found"] = save_button is not None
    try:
        report["save_button_enabled"] = bool(save_button.isEnabled()) if save_button is not None else False
    except Exception:
        report["save_button_enabled"] = None

    safety_text = f"{before_collect.get('aits_power_state','')} {before_collect.get('aits_safety_state','')}"
    if any(token in safety_text for token in ("AITS ON", "Live", "?ㅺ굅??")):
        report["pass_status"] = "no_go"
        report["fail_reason"] = "unsafe_aits_state_before_save"
        return

    handler = getattr(window, "_save_trade_log_center_state", None)
    if not callable(handler):
        report["pass_status"] = "fail"
        report["fail_reason"] = "save_handler_missing"
        return

    started = time.time()
    try:
        report["save_handler_entered"] = True
        ok = bool(handler(reason="qt_smoke_save_probe"))
        report["save_completed"] = ok
    except Exception as exc:
        report["save_error"] = type(exc).__name__
        report["save_completed"] = False
    report["save_elapsed_ms"] = int((time.time() - started) * 1000)
    _pump_events(app, min(max(float(timeout_sec), 1.0), 3.0))

    after_collect = _collect(window, widgets)
    after_journal = _latest_journal_summary(window)
    after_log = _read_log_tail(Path(paths["log_dir"]), started_epoch)
    report.update(
        {
            "trade_log_row_count_after": after_collect.get("trade_log_row_count"),
            "latest_row_after": after_collect.get("latest_trade_log_row", ""),
            "journal_after": after_journal,
            "provider_call_count_after": after_log.get("provider_call_markers", 0),
            "external_cost_call_count_after": after_log.get("external_cost_call_markers", 0),
            "provider_call_delta": _marker_delta(after_log, before_log, "provider_call_markers"),
            "external_cost_call_delta": _marker_delta(after_log, before_log, "external_cost_call_markers"),
            "save_log_start_delta": _marker_count_delta(after_log, before_log, "trade_log_save_start"),
            "save_log_finish_delta": _marker_count_delta(after_log, before_log, "trade_log_save_finish"),
            "save_log_failed_delta": _marker_count_delta(after_log, before_log, "trade_log_save_failed"),
            "log_tail_after_save": after_log,
        }
    )

    fail_reasons: list[str] = []
    if not report.get("save_completed"):
        fail_reasons.append("save_handler_returned_false")
    if int(report.get("save_elapsed_ms") or 0) > 10_000:
        fail_reasons.append("save_elapsed_over_10s")
    if report.get("provider_call_delta") != 0 or report.get("external_cost_call_delta") != 0:
        fail_reasons.append("provider_call_detected")
    if report.get("save_log_finish_delta", 0) < 1:
        fail_reasons.append("save_finish_log_missing")
    if report.get("trade_log_row_count_after") != report.get("trade_log_row_count_before"):
        fail_reasons.append("trade_log_row_count_changed")
    if report.get("latest_row_after") != report.get("latest_row_before"):
        fail_reasons.append("latest_row_changed")
    if after_log.get("risk_hits"):
        fail_reasons.append("order_risk_detected")

    if fail_reasons:
        report["pass_status"] = "fail"
        report["fail_reason"] = ",".join(fail_reasons)
    else:
        report["pass_status"] = "pass"


def _riskguard_fixtures() -> list[dict[str, Any]]:
    base = {
        "symbol": "KRW-BTC",
        "side": "buy",
        "requested_amount_krw": 5000.0,
        "price": 100000000.0,
        "quantity": 0.0,
        "source_provider": "local",
        "confidence": 0.72,
        "action": "buy",
        "holdings_value_krw": 0.0,
        "cash_available_krw": 100000.0,
        "portfolio_value_krw": 1000000.0,
        "daily_realized_pnl_krw": 0.0,
        "daily_loss_limit_krw": 50000.0,
        "max_order_amount_krw": 10000.0,
        "max_position_value_krw": 30000.0,
        "emergency_stop": False,
        "stale_price": False,
        "execution_mode": "disabled",
        "dry_run": True,
    }

    def fixture(name: str, expected_allowed: bool, **overrides: Any) -> dict[str, Any]:
        candidate = dict(base)
        candidate.update(overrides)
        candidate["request_id"] = name
        return {
            "name": name,
            "expected_allowed": bool(expected_allowed),
            "candidate": candidate,
        }

    return [
        fixture("allowed_small_buy", True),
        fixture("blocked_max_order", False, requested_amount_krw=25000.0),
        fixture("blocked_position_limit", False, holdings_value_krw=26000.0, requested_amount_krw=5000.0),
        fixture("blocked_daily_loss", False, daily_realized_pnl_krw=-50000.0),
        fixture("blocked_emergency_stop", False, emergency_stop=True),
        fixture("blocked_invalid_symbol", False, symbol="BTC"),
        fixture("blocked_stale_price", False, stale_price=True),
    ]


def _run_riskguard_proof(report: dict[str, Any]) -> None:
    from app.services.risk_guard import RiskGuard

    guard = RiskGuard()
    results: list[dict[str, Any]] = []
    pass_count = 0
    fail_count = 0

    for item in _riskguard_fixtures():
        candidate = item["candidate"]
        result = guard.evaluate_order_candidate(candidate)
        result_dict = result.to_dict()
        passed = (
            bool(result.allowed) == bool(item["expected_allowed"])
            and int(result.submitted) == 0
            and bool(result.order_allowed) is False
            and bool(result.real_order) is False
            and bool(result.dry_run) is True
        )
        if passed:
            pass_count += 1
        else:
            fail_count += 1
        results.append(
            {
                "name": item["name"],
                "expected_allowed": item["expected_allowed"],
                "actual_allowed": bool(result.allowed),
                "risk_allowed": bool(result.risk_allowed),
                "blocked_reason": result.blocked_reason,
                "severity": result.severity,
                "submitted": int(result.submitted),
                "order_allowed": bool(result.order_allowed),
                "real_order": bool(result.real_order),
                "dry_run": bool(result.dry_run),
                "pass": bool(passed),
                "result": result_dict,
                "log_summary": guard.log_summary(result, candidate),
            }
        )

    report.update(
        {
            "riskguard_fixture_count": len(results),
            "riskguard_pass_count": pass_count,
            "riskguard_fail_count": fail_count,
            "riskguard_results": results,
            "provider_call_markers": 0,
            "provider_call_delta": 0,
            "external_cost_call_markers": 0,
            "external_cost_call_delta": 0,
            "submitted_detected": False,
            "order_risk_detected": False,
            "real_order_detected": False,
            "pass_status": "pass" if fail_count == 0 else "fail",
        }
    )


